// ==========================================================
// v62 SINGLE VIEW ROUTER
// 빠른 카테고리 전환 시 여러 view가 동시에 표시되는 현상 방지
// ==========================================================
(function(){
  const VIEW_MAP={
    contract:'dfViewContract',
    company:'dfViewCompany',
    schedule:'dfViewSchedule',
    'schedule-add':'dfViewScheduleAdd',
    progress:'dfViewProgress',
    repository:'dfViewRepository',
    employees:'dfViewEmployees',
    analysis:'dfViewAnalysis',
    sample:'dfViewSample'
  };

  let routeToken=0;

  function v62ShowOnly(viewName,opts={}){
    const id=VIEW_MAP[viewName];
    if(!id)return;

    // v112.7: 내부 화면 전환을 브라우저 History에 기록한다.
    // 따라서 일정등록 등에서 브라우저 뒤로가기를 눌러도 사이트를 이탈하지 않고 이전 화면으로 돌아간다.
    if(opts.history!==false){
      try{
        const cur=history.state?.dfRoute;
        const hash='#'+viewName;
        if(cur!==viewName) history.pushState({dfRoute:viewName},'',hash);
        else if(location.hash!==hash) history.replaceState({dfRoute:viewName},'',hash);
      }catch(e){console.warn('내부 화면 history 기록 실패',e)}
    }

    // v110.1: 새로고침 시 현재 화면을 유지한다.
    // sessionStorage를 사용해 새 탭/새 로그인은 역할별 기본화면에서 시작한다.
    if(dfCloudProfile){try{sessionStorage.setItem('dreampoen_current_view_v1101',viewName)}catch(e){}}

    const myToken=++routeToken;

    // 모든 화면을 즉시 닫고 선택한 화면 하나만 연다.
    Object.values(VIEW_MAP).forEach(viewId=>{
      const el=document.getElementById(viewId);
      if(!el)return;
      el.classList.remove('df-view-active');
      el.hidden=true;
      el.style.setProperty('display','none','important');
      el.setAttribute('aria-hidden','true');
    });

    const target=document.getElementById(id);
    if(target){
      target.hidden=false;
      target.classList.add('df-view-active');
      target.style.setProperty('display','block','important');
      target.setAttribute('aria-hidden','false');
    }

    document.querySelectorAll('.df-nav-item[data-view]').forEach(btn=>{
      btn.classList.toggle('active',btn.dataset.view===viewName);
    });

    // 혹시 이전 버전의 지연 동작이 뒤늦게 실행돼도 다시 정리.
    requestAnimationFrame(()=>{
      if(myToken!==routeToken)return;
      Object.entries(VIEW_MAP).forEach(([name,viewId])=>{
        const el=document.getElementById(viewId);
        if(!el)return;
        const active=name===viewName;
        el.hidden=!active;
        el.classList.toggle('df-view-active',active);
        el.style.setProperty('display',active?'block':'none','important');
        el.setAttribute('aria-hidden',active?'false':'true');
      });
    });

        if(viewName==='contract' && typeof dfV68LoadContracts==='function')dfV68LoadContracts();
    if(viewName==='company'){try{companyRender?.()}catch(e){console.warn('[COMPANY-1202-01]',e)}}
    if(viewName==='schedule'){try{scheduleRenderAll?.();dfV1101RefreshSchedulesOnline?.(false)}catch(e){console.warn('[SCHEDULE-1202-01]',e)}}
    if(viewName==='progress'){try{dfV1201RenderProgress?.()}catch(e){console.warn('[PROGRESS-1201-01]',e)}}
    if(viewName==='repository' && typeof dfRepositoryOpen==='function')dfRepositoryOpen();
    if(viewName==='sample' && typeof dfRepositorySync==='function')setTimeout(()=>dfRepositorySync({quiet:true}),20);
    if(viewName==='analysis' && typeof dfRepositorySync==='function')setTimeout(async()=>{await dfRepositorySync({quiet:true});refreshAnalysisRecordList();if(typeof v66ReloadSelectedAnalysis==='function')v66ReloadSelectedAnalysis()},20);
    if(viewName==='employees' && typeof dfEmployeesLoad==='function')dfEmployeesLoad();
    if(viewName==='analysis' && typeof refreshAnalysisRecordList==='function'){
      refreshAnalysisRecordList();
      if(typeof v66ReloadSelectedAnalysis==='function')v66ReloadSelectedAnalysis();
    }
  }

  // capture 단계에서 한 번만 처리하고, 과거 버전의 라우팅 리스너까지 전달하지 않는다.
  document.addEventListener('click',function(e){
    const btn=e.target.closest?.('.df-nav-item[data-view]');
    if(!btn)return;
    const viewName=btn.dataset.view;
    if(!VIEW_MAP[viewName])return;

    e.preventDefault();
    e.stopPropagation();
    e.stopImmediatePropagation();
    v62ShowOnly(viewName);
  },true);

  window.v62ShowOnly=v62ShowOnly;

  document.addEventListener('DOMContentLoaded',()=>{
    let remembered='';try{remembered=sessionStorage.getItem('dreampoen_current_view_v1101')||''}catch(e){}
    const hashView=(location.hash||'').replace(/^#/,'');
    const active=(hashView&&VIEW_MAP[hashView])?hashView:((remembered&&VIEW_MAP[remembered])?remembered:(document.querySelector('.df-nav-item[data-view].active')?.dataset.view || (dfCloudProfile?.role==='admin'?'contract':'sample')));
    try{history.replaceState({dfRoute:active},'','#'+active)}catch(e){}
    v62ShowOnly(active,{history:false});
  });

  window.addEventListener('popstate',(e)=>{
    let target=e.state?.dfRoute || (location.hash||'').replace(/^#/,'') || (dfCloudProfile?.role==='admin'?'contract':'sample');
    if(!VIEW_MAP[target])target=(dfCloudProfile?.role==='admin'?'contract':'sample');
    v62ShowOnly(target,{history:false});
  });

  window.dfV1101OpenRoleHome=function(forceDefault=false){
    let target='';
    if(!forceDefault){try{target=sessionStorage.getItem('dreampoen_current_view_v1101')||''}catch(e){}}
    if(!VIEW_MAP[target])target=(dfCloudProfile?.role==='admin'?'contract':'sample');
    v62ShowOnly(target,{history:false});
  };
})();

