const fmt=(n,d=2)=>Number.isFinite(n)?Number(n).toFixed(d):'-';
const num=id=>{const v=parseFloat($(id)?.value); return Number.isFinite(v)?v:0};
const clone=o=>JSON.parse(JSON.stringify(o));
