// v44 업체관리 - 기존 공용출장일정 v2.7의 데이터 구조/상태판정 방식 기반
// ==========================================================
const COMPANY_DB_STORAGE='dreampoen_company_db_v51';

const companyState={
  db:null,
  selectedId:null,
  search:'',
  year:2026,
  month:0,
  h2Incomplete:false,
  statusFilter:'all',
  sortMode:'name'
};

function companyClone(x){return JSON.parse(JSON.stringify(x))}
function companyIsoDate(v,defaultYear=companyState?.year||2026){
  if(v===null||v===undefined||v==='')return '';
  const s=String(v).trim();
  if(!s)return '';
  const n=Number(s);
  if(Number.isFinite(n)&&n>=30000&&n<=60000){
    const d=new Date(Date.UTC(1899,11,30)+n*86400000);
    return d.toISOString().slice(0,10);
  }
  let m=s.match(/(\d{4})[-./](\d{1,2})[-./](\d{1,2})/);
  if(m)return `${m[1]}-${String(+m[2]).padStart(2,'0')}-${String(+m[3]).padStart(2,'0')}`;
  m=s.match(/(\d{1,2})\s*월\s*(\d{1,2})\s*일/);
  if(m)return `${defaultYear}-${String(+m[1]).padStart(2,'0')}-${String(+m[2]).padStart(2,'0')}`;
  const d=new Date(s);
  return Number.isNaN(d.getTime())?s:d.toISOString().slice(0,10);
}
function companyEnsureFields(c){
  c.Facilities=Array.isArray(c.Facilities)?c.Facilities:[];
  c.MeasurementHistory=Array.isArray(c.MeasurementHistory)?c.MeasurementHistory:[];
  if(c.ManualMeasurementDates!==undefined&&!Array.isArray(c.ManualMeasurementDates))c.ManualMeasurementDates=[];
  c.MeasurementItems=Array.isArray(c.MeasurementItems)?c.MeasurementItems:(c.Item?String(c.Item).split(',').map(x=>x.trim()).filter(Boolean):[]);
  c.Cycle=c.Cycle||'반기 1회';
  c.Tracking=c.Tracking||{};
  for(let m=1;m<=12;m++){
    for(const part of ['First','Second']){
      const k=`M${m}${part}`;
      c.Tracking[k]=companyIsoDate(c.Tracking[k]||'',companyState.year||2026);
    }
  }
  c.Active=c.Active!==false;
  return c;
}
function companyYearDates(c,year){
  companyEnsureFields(c);
  const set=new Set();
  for(const h of c.MeasurementHistory||[]){
    const d=companyIsoDate(h.Date);
    if(d&&+d.slice(0,4)===year)set.add(d);
  }
  if(year===2026){
    for(let m=1;m<=12;m++){
      for(const p of ['First','Second']){
        const d=companyIsoDate(c.Tracking?.[`M${m}${p}`]||'');
        if(d&&+d.slice(0,4)===year)set.add(d);
      }
    }
  }
  return [...set].sort();
}
function companyFacilityDates(c,f,year){
  const fk=companyNormFacility(f?.FacilityName||f?.EmissionFacility||'');
  const fh=(f?.MeasurementHistory||[]).filter(h=>+String(h.Date||'').slice(0,4)===year).map(h=>companyIsoDate(h.Date)).filter(Boolean);
  if(fh.length)return [...new Set(fh)].sort();
  return (c.MeasurementHistory||[]).filter(h=>{
    const d=companyIsoDate(h.Date);
    const hk=companyNormFacility(h.FacilityName||'');
    return d&&+d.slice(0,4)===year&&fk&&hk&&(fk===hk||fk.includes(hk)||hk.includes(fk));
  }).map(h=>companyIsoDate(h.Date)).filter(Boolean).sort();
}
function companyNormFacility(v){return String(v||'').toLowerCase().replace(/[\s\-_/().,#]/g,'').replace(/^(방|배)\d+/,'')}
function companyCycleStatus(dates,cycle){
  const month=d=>+d.slice(5,7);
  const txt=String(cycle||'반기 1회');
  if(/반기|연\s*2회|2회/.test(txt)){
    const h1=dates.filter(d=>month(d)<=6),h2=dates.filter(d=>month(d)>=7);
    return {h1:h1.at(-1)||'',h2:h2.at(-1)||'',missing:(h1.length?0:1)+(h2.length?0:1)};
  }
  if(/연\s*1회|연측정|연 1회|1회/.test(txt)){
    return {h1:dates.at(-1)||'',h2:'-',missing:dates.length?0:1};
  }
  if(/분기|4회/.test(txt)){
    let missing=0;
    for(let q=1;q<=4;q++){const a=(q-1)*3+1,b=a+2;if(!dates.some(d=>month(d)>=a&&month(d)<=b))missing++}
    return {h1:dates.some(d=>month(d)<=6)?'측정':'',h2:dates.some(d=>month(d)>=7)?'측정':'',missing};
  }
  if(/월|12회/.test(txt)){
    let missing=0;for(let m=1;m<=12;m++)if(!dates.some(d=>month(d)===m))missing++;
    return {h1:dates.some(d=>month(d)<=6)?'측정':'',h2:dates.some(d=>month(d)>=7)?'측정':'',missing};
  }
  return {h1:dates.at(-1)||'',h2:'-',missing:dates.length?0:1};
}
function companyNeedsH2(c){
  const cycles=[];
  (c.Facilities||[]).forEach(f=>{
    const rows=window.dfV1205EffectiveItemCycles?.(f)||(f.ItemCycles||[]);
    rows.forEach(x=>{if(x.Cycle)cycles.push(String(x.Cycle))});
    if(!rows.length&&f.Cycle)cycles.push(String(window.dfV1205EffectiveCycle?.(f)||f.Cycle));
  });
  if(!cycles.length&&c.Cycle)cycles.push(String(c.Cycle));
  return cycles.some(x=>/반기|연\s*2회|2회|분기|4회|월\s*1회|월\s*2회|12회/.test(x));
}
function companyAnnualStatus(c,year){
  companyEnsureFields(c);
  const dates=companyYearDates(c,year);
  const h1=dates.filter(d=>+d.slice(5,7)<=6);
  const h2=dates.filter(d=>+d.slice(5,7)>=7);
  const H1=h1.length?h1.at(-1):'미측정';
  const needsH2=companyNeedsH2(c);
  const H2=h2.length?h2.at(-1):(needsH2?'미측정':'-');

  // 상태는 실제 상·하반기 날짜를 우선한다.
  // 시설명 매칭 차이 때문에 측정된 업체가 '미측정'으로 보이는 현상을 방지.
  let Status='';
  if(needsH2){
    const miss=[];
    if(!h1.length)miss.push('상반기');
    if(!h2.length)miss.push('하반기');
    Status=miss.length?`${miss.join('·')} 미측정`:'연간 완료';
  }else{
    Status=dates.length?'연간 완료':'연간 미측정';
  }
  return {H1,H2,Status};
}
function companySaveDb(){
  localStorage.setItem(COMPANY_DB_STORAGE,JSON.stringify(companyState.db));
}

