async function companyLoadDb(){
  // v76: index.html을 더블클릭(file://)해도 fetch 차단 때문에 0건이 되지 않도록
  // 내장 DB를 즉시 기본값으로 사용하고, 웹서버 실행 시에는 data/shared_db.json으로 갱신합니다.
  let shipped=companyClone(DF_V76_EMBEDDED_COMPANY_DB);
  try{
    if(location.protocol!=='file:'){
      const r=await fetch('./data/shared_db.json',{cache:'no-store'});
      if(r.ok)shipped=await r.json();
    }
  }catch(e){console.warn('shared_db.json 외부 로드 실패 - v76 내장 DB 사용',e)}
  const local48=localStorage.getItem(COMPANY_DB_STORAGE);
  if(local48){
    try{companyState.db=JSON.parse(local48)}catch{}
  }
  if(!companyState.db){
    // 업체 사용자가 수정한 내용은 v47에서 가져오되,
    // v48의 실제 측정자료 기반 달력 일정은 새 배포본을 우선 적용한다.
    const old=localStorage.getItem('dreampoen_company_db_v55')||localStorage.getItem('dreampoen_company_db_v54')||localStorage.getItem('dreampoen_company_db_v50')||localStorage.getItem('dreampoen_company_db_v49')||localStorage.getItem('dreampoen_company_db_v48');
    if(old){
      try{
        companyState.db=JSON.parse(old);
        if(shipped){
          companyState.db.Schedules=shipped.Schedules||[];
          companyState.db.ScheduleRebuild=shipped.ScheduleRebuild;
          companyState.db.Settings=Object.assign({},shipped.Settings||{},companyState.db.Settings||{});
          // 측정인에서 보완된 업체/시설 정보는 기존 업체에 가능한 범위로 병합
          const shippedCompanies=shipped.Companies||[];
          (companyState.db.Companies||[]).forEach(c=>{
            const match=shippedCompanies.find(s=>s.Id===c.Id);
            if(match){
              c.MeasurementHistory=match.MeasurementHistory||c.MeasurementHistory||[];
              c.Tracking=Object.assign({},c.Tracking||{},match.Tracking||{});
              if((!c.Facilities||!c.Facilities.length)&&match.Facilities)c.Facilities=match.Facilities;
              if((!c.MeasurementItems||!c.MeasurementItems.length)&&match.MeasurementItems)c.MeasurementItems=match.MeasurementItems;
            }
          });
        }
      }catch{}
    }
  }
  if(!companyState.db)companyState.db=shipped;
  if(!companyState.db)throw new Error('업체 DB를 불러오지 못했습니다.');
  const v76State=document.getElementById('companyOnlineState');
  if(v76State)v76State.textContent=`기본DB ${companyState.db.Companies?.length||0}개 로드`;

  // v51: 출장일지의 시설명/항목/주기/내경 기준정보는 배포 DB를 기준으로 병합.
  // 사용자가 기존에 수정한 업체 기본정보/일정/측정일은 유지한다.
  if(shipped){
    const shippedById=new Map((shipped.Companies||[]).map(c=>[String(c.Id),c]));
    (companyState.db.Companies||[]).forEach(c=>{
      const s=shippedById.get(String(c.Id));
      if(!s)return;
      // v56: 시설 구조는 사용자의 최신 수정내용을 우선하고,
      // 배포 DB에서는 빠진 내경/단면값만 ID 기준으로 보완한다.
      const localFacilities=c.Facilities||[];
      const shippedFacilities=s.Facilities||[];
      if(!localFacilities.length){
        c.Facilities=shippedFacilities;
      }else{
        const shippedById=new Map(shippedFacilities.map(f=>[String(f.Id),f]));
        localFacilities.forEach(f=>{
          const sf=shippedById.get(String(f.Id));
          if(!sf)return;
          if(!f.StackShape&&sf.StackShape)f.StackShape=sf.StackShape;
          if(!f.Diameter&&sf.Diameter)f.Diameter=sf.Diameter;
          if(!f.StackW&&sf.StackW)f.StackW=sf.StackW;
          if(!f.StackH&&sf.StackH)f.StackH=sf.StackH;
          if(!f.DimensionRaw&&sf.DimensionRaw)f.DimensionRaw=sf.DimensionRaw;
        });
        c.Facilities=localFacilities;
      }
      if(!c.MeasurementItems?.length)c.MeasurementItems=s.MeasurementItems||[];
      if(!c.Item)c.Item=s.Item||'';
      if(!c.Cycle)c.Cycle=s.Cycle||'';
      if(!c.PreventionFacility)c.PreventionFacility=s.PreventionFacility||'';
      if(!c.EmissionFacility)c.EmissionFacility=s.EmissionFacility||'';
      c.FacilityMasterSource=c.FacilityMasterSource||s.FacilityMasterSource;
      // 측정일은 상하반기 기준을 유지
      if(s.MeasurementHistory?.length)c.MeasurementHistory=s.MeasurementHistory;
      if(s.Tracking)c.Tracking=s.Tracking;
    });
  }
  companyState.db.Companies=(companyState.db.Companies||[]).map(companyEnsureFields);
  companyState.db.Schedules=Array.isArray(companyState.db.Schedules)?companyState.db.Schedules:[];
  companySaveDb();
  companyRender();
  scheduleRenderAll();
  syncSampleCompanySelectors(true);
  setTimeout(async()=>{try{await dfV73BuildCompanyStatusFromContracts();companyRender()}catch(e){console.warn('초기 계약업체 연결',e)}},0);
}

