function dfV75ExpectedItemRows(c){
  const rows=[];
  (c.Facilities||[]).forEach(f=>{
    const ics=window.dfV1205EffectiveItemCycles?.(f)||((f.ItemCycles||[]).length?f.ItemCycles:(f.Items||[]).map(it=>({Item:it,Cycle:f.Cycle||'반기 1회'})));
    ics.forEach(x=>rows.push({facility:f,item:x.Item||'',cycle:x.Cycle||f.Cycle||'반기 1회'}));
  });
  return rows;
}


function dfV81ItemHistoryDates(c,f,item,year){
  const itemKey=String(item||'').trim().toLowerCase();
  const fk=companyNormFacility(f?.FacilityName||f?.EmissionFacility||'');
  const all=[...(f?.MeasurementHistory||[]),...(c?.MeasurementHistory||[])];
  return [...new Set(all.filter(h=>{
    const d=companyIsoDate(h?.Date);
    if(!d||+d.slice(0,4)!==year)return false;
    const hk=companyNormFacility(h?.FacilityName||'');
    if(fk&&hk&&!(fk===hk||fk.includes(hk)||hk.includes(fk)))return false;
    const items=Array.isArray(h?.Items)?h.Items:[h?.Item].filter(Boolean);
    if(!items.length)return true;
    return items.some(v=>String(v||'').trim().toLowerCase()===itemKey);
  }).map(h=>companyIsoDate(h.Date)).filter(Boolean))].sort();
}
function dfV81TrackingFromHistory(c,f,item,cycle,year){
  const ds=dfV81ItemHistoryDates(c,f,item,year), month=d=>+d.slice(5,7), out={year};
  const txt=String(cycle||'반기 1회');
  if(/월\s*2회/.test(txt)){
    for(let m=1;m<=12;m++){const arr=ds.filter(d=>month(d)===m).slice(0,2);out[`M${m}`]=arr}
  }else if(/월|12회/.test(txt)){
    for(let m=1;m<=12;m++)out[`M${m}`]=ds.filter(d=>month(d)===m).at(-1)||''
  }else if(/분기|4회/.test(txt)){
    for(let q=1;q<=4;q++){const a=(q-1)*3+1,b=a+2;out[`Q${q}`]=ds.filter(d=>month(d)>=a&&month(d)<=b).at(-1)||''}
  }else if(/반기|연\s*2회|2회/.test(txt)){
    out.H1=ds.filter(d=>month(d)<=6).at(-1)||'';out.H2=ds.filter(d=>month(d)>=7).at(-1)||''
  }else out.Y1=ds.at(-1)||'';
  return out;
}
function dfV81TrackingNormalize(x,c,f,year){
  const saved=x?.Dates&&Number(x.Dates.year)===Number(year)?companyClone(x.Dates):null;
  return saved||dfV81TrackingFromHistory(c,f,x?.Item,x?.Cycle||f?.Cycle,year);
}
function dfV81TrackingDateList(x,c,f,year){
  const t=dfV81TrackingNormalize(x,c,f,year), txt=String(x?.Cycle||f?.Cycle||'');
  if(/월\s*2회/.test(txt)){
    return Array.from({length:12},(_,i)=>Array.isArray(t[`M${i+1}`])?t[`M${i+1}`]:[]).flat().filter(Boolean).sort();
  }
  if(/월|12회/.test(txt))return Array.from({length:12},(_,i)=>t[`M${i+1}`]).filter(Boolean).sort();
  if(/분기|4회/.test(txt))return [t.Q1,t.Q2,t.Q3,t.Q4].filter(Boolean).sort();
  if(/반기|연\s*2회|2회/.test(txt))return [t.H1,t.H2].filter(Boolean).sort();
  return [t.Y1].filter(Boolean);
}
function dfV81TrackingStatus(x,c,f,year){
  const t=dfV81TrackingNormalize(x,c,f,year), txt=String(x?.Cycle||f?.Cycle||'반기 1회');
  const now=new Date(), cy=now.getFullYear(), cm=now.getMonth()+1;
  if(year>cy)return 'check';
  const past=year<cy;
  if(/월\s*2회/.test(txt)){
    const upto=past?12:cm;
    for(let m=1;m<=upto;m++){
      const got=(Array.isArray(t[`M${m}`])?t[`M${m}`]:[]).filter(Boolean).length;
      if(got<2)return m<(past?13:cm)?'incomplete':'check';
    }
    return 'complete';
  }
  if(/월|12회/.test(txt)){
    const upto=past?12:cm;
    for(let m=1;m<=upto;m++)if(!t[`M${m}`])return m<(past?13:cm)?'incomplete':'check';
    return 'complete';
  }
  if(/분기|4회/.test(txt)){
    const cq=Math.ceil(cm/3), upto=past?4:cq;
    for(let q=1;q<=upto;q++)if(!t[`Q${q}`])return q<(past?5:cq)?'incomplete':'check';
    return 'complete';
  }
  if(/반기|연\s*2회|2회/.test(txt)){
    if(past)return t.H1&&t.H2?'complete':'incomplete';
    if(cm<=6)return t.H1?'complete':'check';
    if(!t.H1)return 'incomplete';
    return t.H2?'complete':'check';
  }
  return t.Y1?'complete':(past?'incomplete':'check');
}
function dfV81DateInput(key,value,label){
  return `<label class="v81-date-cell"><span>${label}</span><input type="date" data-track-key="${key}" value="${companyEsc(value||'')}"></label>`;
}
function dfV81TrackingEditor(x,c,f){
  const t=dfV81TrackingNormalize(x,c,f,companyState.year), txt=String(x.Cycle||f.Cycle||'반기 1회');
  if(/월\s*2회/.test(txt)){
    return `<div class="v81-track-grid monthly double">${Array.from({length:12},(_,i)=>{
      const m=i+1,a=Array.isArray(t[`M${m}`])?t[`M${m}`]:[];
      return `<div class="v81-month-pair"><b>${m}월</b><input type="date" data-track-key="M${m}:0" value="${companyEsc(a[0]||'')}"><input type="date" data-track-key="M${m}:1" value="${companyEsc(a[1]||'')}"></div>`;
    }).join('')}</div>`;
  }
  if(/월|12회/.test(txt))return `<div class="v81-track-grid monthly">${Array.from({length:12},(_,i)=>dfV81DateInput(`M${i+1}`,t[`M${i+1}`],`${i+1}월`)).join('')}</div>`;
  if(/분기|4회/.test(txt))return `<div class="v81-track-grid">${[1,2,3,4].map(q=>dfV81DateInput(`Q${q}`,t[`Q${q}`],`${q}분기`)).join('')}</div>`;
  if(/반기|연\s*2회|2회/.test(txt))return `<div class="v81-track-grid">${dfV81DateInput('H1',t.H1,'상반기')}${dfV81DateInput('H2',t.H2,'하반기')}</div>`;
  return `<div class="v81-track-grid">${dfV81DateInput('Y1',t.Y1,'연 1회')}</div>`;
}
function dfV81CollectTracking(row,x){
  const obj={year:companyState.year};
  row.querySelectorAll('[data-track-key]').forEach(inp=>{
    const k=inp.dataset.trackKey,v=inp.value||'';
    if(k.includes(':')){
      const [base,idxs]=k.split(':'),idx=+idxs;
      obj[base]=Array.isArray(obj[base])?obj[base]:['',''];obj[base][idx]=v;
    }else obj[k]=v;
  });
  x.Dates=obj;
}

function dfV77PeriodStatus(dates,cycle,year){
  const now=new Date(), currentYear=now.getFullYear(), currentMonth=now.getMonth()+1;
  const months=dates.map(d=>+String(d).slice(5,7)).filter(Boolean);
  const txt=String(cycle||'반기 1회');
  const futureYear=year>currentYear, pastYear=year<currentYear;
  if(futureYear)return {state:'check',last:dates.at(-1)||'',detail:'측정확인필요'};

  const hasMonth=m=>months.includes(m);
  const missingPast=[], missingCurrent=[];

  if(/월\s*2회/.test(txt)){
    const counts={};months.forEach(m=>counts[m]=(counts[m]||0)+1);
    const upto=pastYear?12:currentMonth;
    for(let m=1;m<=upto;m++){
      const need=2, got=counts[m]||0;
      if(got<need)(m<(pastYear?13:currentMonth)?missingPast:missingCurrent).push(`${m}월 ${got}/2`);
    }
  }else if(/월|12회/.test(txt)){
    const upto=pastYear?12:currentMonth;
    for(let m=1;m<=upto;m++)if(!hasMonth(m))(m<(pastYear?13:currentMonth)?missingPast:missingCurrent).push(`${m}월`);
  }else if(/분기|4회/.test(txt)){
    const currentQ=Math.ceil(currentMonth/3), upto=pastYear?4:currentQ;
    for(let q=1;q<=upto;q++){
      const a=(q-1)*3+1,b=a+2,ok=months.some(m=>m>=a&&m<=b);
      if(!ok)(q<(pastYear?5:currentQ)?missingPast:missingCurrent).push(`${q}분기`);
    }
  }else if(/반기|연\s*2회|2회/.test(txt)){
    const h1=months.some(m=>m<=6),h2=months.some(m=>m>=7);
    if(pastYear){if(!h1)missingPast.push('상반기');if(!h2)missingPast.push('하반기')}
    else if(currentMonth<=6){if(!h1)missingCurrent.push('상반기')}
    else {if(!h1)missingPast.push('상반기');if(!h2)missingCurrent.push('하반기')}
  }else {
    if(!dates.length)(pastYear?missingPast:missingCurrent).push('연 1회');
  }
  if(missingPast.length)return {state:'incomplete',last:dates.at(-1)||'',detail:'미완료',missing:missingPast};
  if(missingCurrent.length)return {state:'check',last:dates.at(-1)||'',detail:'측정확인필요',missing:missingCurrent};
  return {state:'complete',last:dates.at(-1)||'',detail:'완료',missing:[]};
}

function dfV79MemoStatus(memo){
  const t=String(memo||'').trim();
  if(!t)return null;
  // 명시적 완료 문구는 자동 경고보다 우선
  if(/측정\\s*완료|완료처리|완료$/.test(t)&&!/미완료/.test(t))return null;
  if(/미완료|기한초과|누락|미실시/.test(t))return {state:'incomplete',label:'미완료'};
  if(/미측정|다음에\\s*측정|다음\\s*측정|고장|정지|휴업|확인|추후|보류/.test(t))return {state:'check',label:'측정확인필요'};
  return null;
}

function dfV77FacilityStatus(c,f,year){
  const memoFlag=dfV79MemoStatus(f.Memo);
  const rows=window.dfV1205EffectiveItemCycles?.(f)||((f.ItemCycles||[]).length?f.ItemCycles:(f.Items||[]).map(it=>({Item:it,Cycle:f.Cycle||'반기 1회'})));
  if(!rows.length)return {state:'check',label:'측정확인필요',last:'',note:f.Memo||''};
  const states=rows.map(x=>dfV81TrackingStatus(x,c,f,year));
  let state=states.includes('incomplete')?'incomplete':states.includes('check')?'check':'complete';
  let label=state==='complete'?'완료':state==='incomplete'?'미완료':'측정확인필요';
  if(memoFlag){
    if(memoFlag.state==='incomplete'||state==='complete'){state=memoFlag.state;label=memoFlag.label}
    else if(memoFlag.state==='check'&&state!=='incomplete'){state='check';label='측정확인필요'}
  }
  const dates=rows.flatMap(x=>dfV81TrackingDateList(x,c,f,year)).filter(Boolean).sort();
  return {state,label,last:dates.at(-1)||'',note:f.Memo||'',items:states};
}
function dfV77FacilityNoteSummary(c){
  return (c.Facilities||[]).filter(f=>String(f.Memo||'').trim()).map(f=>{
    const n=f.FacilityName||f.EmissionFacility||'시설';
    return `${n}: ${String(f.Memo).trim()}`;
  }).join(' / ');
}

function dfV75CompanyProgress(c,year){
  const facilities=c.Facilities||[];
  if(!facilities.length)return {key:'unregistered',label:'측정확인필요'};
  const fs=facilities.map(f=>dfV77FacilityStatus(c,f,year));
  if(fs.some(x=>x.state==='incomplete'))return {key:'incomplete',label:'미완료'};
  if(fs.some(x=>x.state==='check'))return {key:'check',label:'측정확인필요'};
  return {key:'complete',label:'완료'};
}
function dfV75SourceCompanies(){
  if(Array.isArray(companyState.contractCompanies)&&companyState.contractCompanies.length)return companyState.contractCompanies;
  const all=(companyState.db?.Companies||[]).filter(c=>c.Active!==false);
  const current=all.filter(c=>dfV68CompanyIsCurrent(c));
  return current.length?current:all;
}
function companyFiltered(){
  const q=dfV95SearchNorm(companyState.search||'');
  return dfV75SourceCompanies().filter(c=>{
    const pg=dfV1206ProgressInfo(c,companyState.year);
    if(companyState.statusFilter==='complete'&&!pg.ok)return false;
    if(companyState.statusFilter==='inprogress'&&pg.ok)return false;
    if(!q)return true;
    return [c.Name,c.Address,c.BizNo,c.Representative,c.EnvironmentManager,c.Phone,c.Email,c.Industry].some(v=>dfV95SearchNorm(v).includes(q));
  }).sort((a,b)=>{
    if(companyState.sortMode==='facilities'){
      const d=(b.Facilities||[]).length-(a.Facilities||[]).length;
      if(d)return d;
    }
    return String(a.Name||'').localeCompare(String(b.Name||''),'ko');
  });
}

function dfV83FacilityManualDates(f,year){
  if(!Array.isArray(f?.ManualMeasurementDates))return null;
  return [...new Set(f.ManualMeasurementDates.map(companyIsoDate).filter(d=>d&&+d.slice(0,4)===year))].sort();
}
function dfV83FacilityMatchesHistory(f,h){
  const fk=companyNormFacility(f?.FacilityName||f?.EmissionFacility||'');
  const hk=companyNormFacility(h?.FacilityName||'');
  return !!(fk&&hk&&(fk===hk||fk.includes(hk)||hk.includes(fk)));
}
function dfV83FacilityEffectiveDates(c,f,year){
  const manual=dfV83FacilityManualDates(f,year);
  if(manual!==null)return manual;
  return companyFacilityDates(c,f,year);
}
function dfV83AllFacilityDateEntries(c,f,year){
  const manual=dfV83FacilityManualDates(f,year);
  if(manual!==null)return manual.map(d=>({Date:d,Source:'수정값'}));
  const entries=[];
  (f?.MeasurementHistory||[]).forEach(h=>{const d=companyIsoDate(h.Date);if(d&&+d.slice(0,4)===year)entries.push({Date:d,Source:h.Source||'시설이력'})});
  (c?.MeasurementHistory||[]).forEach(h=>{const d=companyIsoDate(h.Date);if(d&&+d.slice(0,4)===year&&dfV83FacilityMatchesHistory(f,h))entries.push({Date:d,Source:h.Source||'측정이력'})});
  const seen=new Set();
  return entries.filter(x=>{if(seen.has(x.Date))return false;seen.add(x.Date);return true}).sort((a,b)=>a.Date.localeCompare(b.Date));
}
function dfV83ManualDatesEditor(c,f){
  const entries=dfV83AllFacilityDateEntries(c,f,companyState.year);
  return `<div class="v83-date-manager">
    <div class="v83-date-head"><strong>측정현황</strong><span>${companyState.year}년 · 날짜 추가/삭제 시 자동 정렬</span></div>
    <div class="v83-date-add"><input type="date" data-v83-date-input><button type="button" class="company-btn secondary" data-v83-date-add>+ 날짜 추가</button></div>
    <div class="v83-date-list">
      ${entries.map(x=>`<div class="v83-date-chip" data-v83-date="${companyEsc(x.Date)}"><span>${companyEsc(x.Date)}</span><small>${companyEsc(x.Source||'')}</small><button type="button" data-v83-date-remove="${companyEsc(x.Date)}">×</button></div>`).join('')||'<span class="v83-date-empty">등록된 측정일이 없습니다.</span>'}
    </div>
  </div>`;
}
function dfV83CollectManualDates(card,f){
  if(!card.querySelector('.v83-date-manager'))return;
  const thisYear=[...card.querySelectorAll('[data-v83-date]')].map(x=>x.dataset.v83Date).filter(Boolean);
  const otherYears=Array.isArray(f.ManualMeasurementDates)?f.ManualMeasurementDates.filter(d=>+String(d).slice(0,4)!==companyState.year):[];
  f.ManualMeasurementDates=[...new Set([...otherYears,...thisYear])].sort();
}
function dfV83AddManualDate(c,facilities,card,draw){
  const i=+card.dataset.v75Facility,inp=card.querySelector('[data-v83-date-input]');
  const d=companyIsoDate(inp?.value||'');if(!d){alert('추가할 날짜를 선택해주세요.');return}
  dfV75CollectEditor(c,facilities);
  const f=facilities[i],cur=dfV83AllFacilityDateEntries(c,f,companyState.year).map(x=>x.Date);
  const other=Array.isArray(f.ManualMeasurementDates)?f.ManualMeasurementDates.filter(x=>+String(x).slice(0,4)!==companyState.year):[];
  f.ManualMeasurementDates=[...new Set([...other,...cur,d])].sort();
  draw();
}
function dfV83RemoveManualDate(c,facilities,card,date,draw){
  const i=+card.dataset.v75Facility;
  dfV75CollectEditor(c,facilities);
  const f=facilities[i],cur=dfV83AllFacilityDateEntries(c,f,companyState.year).map(x=>x.Date).filter(d=>d!==date);
  const other=Array.isArray(f.ManualMeasurementDates)?f.ManualMeasurementDates.filter(x=>+String(x).slice(0,4)!==companyState.year):[];
  f.ManualMeasurementDates=[...new Set([...other,...cur])].sort();
  draw();
}

function dfV1129TrustedCompletedSchedule(s){
  if(!s||s.Deleted||s.Type!=='측정출장'||!s.Completed)return false;
  // 상태만 눌러두고 '변경사항 저장'을 하지 않은 임시값은 측정이력으로 인정하지 않는다.
  const by=String(s.UpdatedBy||'');
  if(by.includes('저장대기'))return false;
  return true;
}
function dfV82MonthDates(c,year,m){
  const vals=[],overridden=(c.Facilities||[]).filter(f=>Array.isArray(f.ManualMeasurementDates));
  // v96.2: 일정에서 측정완료한 업체는 시설이력과 분리하되, 업체현황 월별 측정일에는 완료일을 표시한다.
  // 시설/항목을 순회하지 않으므로 다수 시설 업체도 동일하게 처리된다.
  const cid=String(c?.Id||''), cname=normTextCompany(c?.Name||'');
  (companyState.db?.Schedules||[]).forEach(s=>{
    if(!dfV1129TrustedCompletedSchedule(s))return;
    const d=companyIsoDate(s.Date);
    if(!d||+d.slice(0,4)!==+year||+d.slice(5,7)!==+m)return;
    const ids=Array.isArray(s.CompanyIds)?s.CompanyIds.map(String):[];
    if(ids.includes(cid)||normTextCompany(s.Company||'')===cname) vals.push(d);
  });
  (c.MeasurementHistory||[]).forEach(h=>{
    const d=companyIsoDate(h.Date);
    if(!d||+d.slice(0,4)!==year||+d.slice(5,7)!==m)return;
    if(overridden.some(f=>dfV83FacilityMatchesHistory(f,h)))return;
    vals.push(d);
  });
  (c.Facilities||[]).forEach(f=>{
    const manual=dfV83FacilityManualDates(f,year);
    if(manual!==null){manual.filter(d=>+d.slice(5,7)===m).forEach(d=>vals.push(d));return}
    (f.MeasurementHistory||[]).forEach(h=>{const d=companyIsoDate(h.Date);if(d&&+d.slice(0,4)===year&&+d.slice(5,7)===m)vals.push(d)});
  });
  return [...new Set(vals)].sort();
}
function dfV86CycleRank(cycle){
  const t=String(cycle||'');
  if(/월\s*2회/.test(t))return 5;
  if(/월|12회/.test(t))return 4;
  if(/분기|4회/.test(t))return 3;
  if(/반기|연\s*2회|2회/.test(t))return 2;
  return 1;
}
function dfV86FacilityCycle(f){
  const contractCycle=window.dfV1205EffectiveCycle?.(f);
  if(contractCycle)return contractCycle;
  const cs=(f.ItemCycles||[]).map(x=>x.Cycle).filter(Boolean);
  if(!cs.length)return f.Cycle||'반기 1회';
  // 여러 항목 주기가 섞였으면 가장 잦은 법정주기를 시설 상태 기준으로 사용.
  return cs.sort((a,b)=>dfV86CycleRank(b)-dfV86CycleRank(a))[0];
}
function dfV96CompletedScheduleDatesForCompany(c,year){
  const cid=String(c?.Id||''),cname=normTextCompany(c?.Name||'');
  return [...new Set((companyState.db?.Schedules||[]).filter(s=>{
    if(!dfV1129TrustedCompletedSchedule(s)||+String(s.Date||'').slice(0,4)!==+year)return false;
    const ids=Array.isArray(s.CompanyIds)?s.CompanyIds.map(String):[];
    return ids.includes(cid)||normTextCompany(s.Company||'')===cname;
  }).map(s=>companyIsoDate(s.Date)).filter(Boolean))].sort();
}
function dfV82StatusFromHistory(c,year){
  const memoFlags=(c.Facilities||[]).map(f=>dfV79MemoStatus(f.Memo)).filter(Boolean);
  if(memoFlags.some(x=>x.state==='incomplete'))return {key:'incomplete',label:'미완료'};
  // v96: 수기 비고의 고장/미측정/보류 등은 일정 완료보다 우선하여 확인필요로 표시한다.
  if(memoFlags.some(x=>x.state==='check'))return {key:'check',label:'측정확인필요'};
  // v112.8: 일정의 '측정완료' 하나만으로 업체 전체를 완료 처리하지 않는다.
  // 완료 일정은 해당 연도의 측정일 후보로만 사용하고, 최종 완료 여부는 시설별 법정 측정주기로 계산한다.
  const facilities=c.Facilities||[];
  if(!facilities.length)return {key:'check',label:'측정확인필요'};

  const now=new Date(),cy=now.getFullYear(),cm=now.getMonth()+1;
  const companyDates=[...new Set([...companyYearDates(c,year),...dfV96CompletedScheduleDatesForCompany(c,year)])].sort();
  const states=[];

  facilities.forEach(f=>{
    const cycle=dfV86FacilityCycle(f);
    const facDates=dfV83FacilityEffectiveDates(c,f,year);

    // v88:
    // 반기/연 1회는 과거 데이터의 시설명 오매칭이 많아 업체 전체 측정일을 함께 사용한다.
    // 월/분기는 다른 시설 측정일이 섞이면 안 되므로 시설 이력을 우선한다.
    let dates;
    if(/반기|연\s*2회|2회|연\s*1회|년\s*1회/.test(cycle)){
      dates=[...new Set([...facDates,...companyDates])].sort();
    }else{
      dates=facDates.length?facDates:companyDates;
    }

    const months=dates.map(d=>+d.slice(5,7));

    if(year>cy){states.push('check');return}

    if(/월\s*2회/.test(cycle)){
      const upto=year<cy?12:cm;let ok=true;
      for(let m=1;m<=upto;m++){
        if(dates.filter(d=>+d.slice(5,7)===m).length<2){ok=false;break}
      }
      states.push(ok?'complete':'check');return;
    }

    if(/월|12회/.test(cycle)){
      const upto=year<cy?12:cm;let ok=true;
      for(let m=1;m<=upto;m++){
        if(!months.includes(m)){ok=false;break}
      }
      states.push(ok?'complete':'check');return;
    }

    if(/분기|4회/.test(cycle)){
      const upto=year<cy?4:Math.ceil(cm/3);let ok=true;
      for(let q=1;q<=upto;q++){
        const a=(q-1)*3+1,b=a+2;
        if(!months.some(m=>m>=a&&m<=b)){ok=false;break}
      }
      states.push(ok?'complete':'check');return;
    }

    if(/반기|연\s*2회|2회/.test(cycle)){
      const h1=months.some(m=>m<=6), h2=months.some(m=>m>=7);
      if(year<cy){states.push(h1&&h2?'complete':'check');return}
      if(cm<=6){states.push(h1?'complete':'check');return}
      states.push(h1&&h2?'complete':'check');return;
    }

    // 연 1회
    states.push(dates.length?'complete':'check');
  });

  let state=states.includes('check')?'check':'complete';
  if(memoFlags.some(x=>x.state==='check')&&state==='complete')state='check';
  return {key:state,label:state==='complete'?'완료':'측정확인필요'};
}
// v120.6 업체현황 + 측정진행현황 통합 계산기
// 일정관리 데이터는 읽기만 하며 저장/상태변경은 하지 않는다.
let dfV120631BizLookup=null;
function dfV1206ProgressInfo(c,year){
  const norm=v=>String(v||'').toLowerCase().replace(/\s/g,'');
  const biz=v=>String(v||'').replace(/\D/g,'');
  const cycles=new Set();
  (c.Facilities||[]).forEach(f=>{
    const effective=window.dfV1205EffectiveItemCycles?.(f)||f.ItemCycles||[];
    const values=[window.dfV1205EffectiveCycle?.(f)||f.Cycle,...effective.map(x=>x.Cycle)].filter(Boolean);
    values.forEach(x=>{x=String(x);if(/월|12회/.test(x))cycles.add('월');else if(/분기|4회/.test(x))cycles.add('분기');else if(/반기|연\s*2회|2회/.test(x))cycles.add('반기');else cycles.add('연')});
  });
  if(!cycles.size)cycles.add('연');

  const dates=[];
  const manual=Array.isArray(c.ManualMeasurementDates)?c.ManualMeasurementDates.map(companyIsoDate).filter(d=>d&&+d.slice(0,4)===+year):null;
  if(manual){
    // 사용자가 업체정보에서 직접 저장한 측정일은 자동/기존 이력보다 항상 우선한다.
    dates.push(...manual);
  }else{
    const pushHistory=src=>{
      (src?.MeasurementHistory||[]).forEach(h=>{const d=companyIsoDate(h?.Date);if(d&&+d.slice(0,4)===+year&&String(h?.Source||'')!=='일정완료')dates.push(d)});
      (src?.Facilities||[]).forEach(f=>(f?.MeasurementHistory||[]).forEach(h=>{const d=companyIsoDate(h?.Date);if(d&&+d.slice(0,4)===+year&&String(h?.Source||'')!=='일정완료')dates.push(d)}));
    };
    const cbiz=biz(c.BizNo);
    const matched=cbiz?(dfV120631BizLookup?.get(cbiz)||(companyState.db?.Companies||[]).find(x=>biz(x.BizNo)===cbiz)):null;
    pushHistory(c);
    if(matched&&matched!==c)pushHistory(matched);
  }
  const ds=[...new Set(dates)].sort(), months=ds.map(d=>+d.slice(5,7));
  const need=k=>k==='월'?12:k==='분기'?4:k==='반기'?2:1;
  const count=k=>k==='월'?new Set(months).size:k==='분기'?new Set(months.map(x=>Math.ceil(x/3))).size:k==='반기'?new Set(months.map(x=>x<=6?1:2)).size:ds.length?1:0;
  const ok=[...cycles].every(k=>count(k)>=need(k));
  let next='-';
  if(!ok){
    if(cycles.has('월')){const m=Array.from({length:12},(_,i)=>i+1).find(m=>!months.includes(m));next=m?`${m}월 측정 필요`:'측정 필요'}
    else if(cycles.has('분기')){const q=Array.from({length:4},(_,i)=>i+1).find(q=>!months.some(m=>Math.ceil(m/3)===q));next=q?`${q}분기 측정 필요`:'측정 필요'}
    else if(cycles.has('반기')){next=!months.some(m=>m<=6)?'상반기 측정 필요':!months.some(m=>m>=7)?'하반기 측정 필요':'측정 필요'}
    else next='연 1회 측정 필요';
  }
  const cell=k=>cycles.has(k)?`${count(k)}/${need(k)}`:'-';
  return {cycles:[...cycles],dates:ds,recent:ds.at(-1)||'-',next,ok,annual:cell('연'),half:cell('반기'),quarter:cell('분기'),month:cell('월')};
}
function companyRender(){
  if(!companyState.db)return;
  // v120.6.3.1: 업체현황이 보이지 않을 때는 무거운 진행률 계산/DOM 렌더를 하지 않는다.
  // 초기 로딩 중 여러 모듈이 companyRender()를 호출해도 실제 업체현황 진입 시 1회만 계산한다.
  const view=document.getElementById('dfViewCompany');
  if(view && (view.hidden || view.getAttribute('aria-hidden')==='true' || getComputedStyle(view).display==='none'))return;

  const setText=(id,value)=>{const el=document.getElementById(id);if(el)el.textContent=value};
  const year=companyState.year;
  const all=dfV75SourceCompanies();

  // 사업자번호 조회를 매 업체마다 전체 DB 순회하지 않도록 1회 인덱싱한다.
  const biz=v=>String(v||'').replace(/\D/g,'');
  dfV120631BizLookup=new Map();
  (companyState.db?.Companies||[]).forEach(x=>{const k=biz(x.BizNo);if(k&&!dfV120631BizLookup.has(k))dfV120631BizLookup.set(k,x)});

  // 한 번의 렌더에서 업체별 진행현황 계산은 정확히 1회만 한다.
  const progressMap=new Map();
  all.forEach(c=>progressMap.set(String(c.Id),dfV1206ProgressInfo(c,year)));
  const list=companyFiltered();
  const thead=document.getElementById('companyThead'),tbody=document.getElementById('companyTbody');if(!thead||!tbody)return;
  thead.innerHTML=`<tr>
    <th class="v82-name">기관명</th><th class="v82-address">소재지</th><th>시설</th><th>계약주기</th>
    <th>연</th><th>반기</th><th>분기</th><th>월</th><th>최근 측정일</th><th>다음 필요</th><th>상태</th><th class="v82-note">시설 비고</th>
  </tr>`;
  tbody.innerHTML=list.map(c=>{
    const pg=progressMap.get(String(c.Id))||dfV1206ProgressInfo(c,year),note=dfV77FacilityNoteSummary(c)||'-';
    return `<tr data-company-id="${companyEsc(c.Id)}">
      <td class="v82-name"><strong>${companyEsc(c.Name)}</strong><small class="v1206-bizno">${companyEsc(c.BizNo||'')}</small></td>
      <td class="v82-address" title="${companyEsc(c.Address)}">${companyEsc(c.Address)}</td>
      <td>${(c.Facilities||[]).length}</td>
      <td class="v1206-cycle">${companyEsc(pg.cycles.join(' + '))}</td>
      <td class="v1206-count">${companyEsc(pg.annual)}</td><td class="v1206-count">${companyEsc(pg.half)}</td><td class="v1206-count">${companyEsc(pg.quarter)}</td><td class="v1206-count">${companyEsc(pg.month)}</td>
      <td class="v1206-date" title="${companyEsc(pg.dates.join(', '))}">${companyEsc(pg.recent)}</td>
      <td class="v1206-next">${companyEsc(pg.next)}</td>
      <td><span class="df1201-status ${pg.ok?'done':'need'}">${pg.ok?'완료':'진행중'}</span></td>
      <td class="v77-note-cell v82-note" title="${companyEsc(note)}">${companyEsc(note)}</td>
    </tr>`;
  }).join('')||'<tr><td colspan="12" style="text-align:center;padding:32px;color:#74858f">표시할 계약 진행업체가 없습니다.</td></tr>';
  const progress=[...progressMap.values()];
  const doneCount=progress.filter(x=>x.ok).length;
  const missingCount=progress.length-doneCount;
  setText('companyCount',`업체 ${list.length}개`);
  setText('companyTotalCount',all.length);
  setText('companyDoneCount',doneCount);
  setText('companyMissingCount',missingCount);
  setText('companyCheckCount',missingCount);
  setText('companyFacilityCount',all.reduce((sum,c)=>sum+(c.Facilities||[]).length,0));
  setText('companyPosition',`현재 ${list.length}개 표시 / 계약 진행업체 ${all.length}개 · 측정완료 ${doneCount}개`);
  window.DF_DIAG?.info('COMPANY-RENDER-HOTFIX','업체현황 1회 렌더 완료',`업체 ${all.length}개 / 완료 ${doneCount}개 / 진행중 ${missingCount}개`);
  tbody.querySelectorAll('tr[data-company-id]').forEach(tr=>tr.onclick=()=>{
    const c=all.find(x=>String(x.Id)===String(tr.dataset.companyId));if(c)dfV75OpenCompanyEditor(c,false);
  });
  dfV83ApplyColumnWidths();
}

// v113.2 compatibility guard: legacy company-table width hook was referenced but never defined.
// Keep this intentionally conservative so existing table/CSS sizing is not changed.
function dfV83ApplyColumnWidths(){
  try {
    // Column widths are currently controlled by the existing stylesheet/table layout.
    // This hook remains for backward compatibility with the v83 render path.
    return true;
  } catch (e) {
    console.warn('[UI-COL-1132-01] 업체현황 열너비 적용 오류', e);
    return false;
  }
}
