function scheduleAddClear(keepDate=true){
  const currentDate=$('#scheduleAddDate')?.value||scheduleState.selectedDate||scheduleIso(new Date());
  if($('#scheduleAddDate'))$('#scheduleAddDate').value=keepDate?currentDate:scheduleIso(new Date());
  if($('#scheduleAddType'))$('#scheduleAddType').value='측정출장';
  if($('#scheduleAddEmployee'))$('#scheduleAddEmployee').value='';
  if($('#scheduleAddStatus'))$('#scheduleAddStatus').value='planned';
  if($('#scheduleAddCompany'))$('#scheduleAddCompany').value='';
  if($('#scheduleAddCompanyId'))$('#scheduleAddCompanyId').value='';
  if($('#scheduleAddFacility'))$('#scheduleAddFacility').value='';
  scheduleAddSelectedFacilities=[];
  scheduleAddRenderSelected();
  if($('#scheduleAddDetail'))$('#scheduleAddDetail').value='';
  if($('#scheduleAddNote'))$('#scheduleAddNote').value='';
  smartPickCloseAll?.();
}
function scheduleAddPrepare(){
  if(!$('#scheduleAddDate'))return;
  const requested=dfV81PendingScheduleDate||localStorage.getItem('dreampoen_schedule_draft_date')||scheduleState.selectedDate||scheduleIso(new Date());
  scheduleAddClear(false);
  $('#scheduleAddDate').value=requested;
  dfV81PendingScheduleDate='';
  localStorage.removeItem('dreampoen_schedule_draft_date');
  scheduleAddFillCompanies();
  if(dfV1101ScheduleEditId){
    const s=scheduleItems().find(x=>String(x.Id)===String(dfV1101ScheduleEditId));
    if(s){
      $('#scheduleAddDate').value=s.Date||requested;
      $('#scheduleAddType').value=s.Type||'측정출장';
      $('#scheduleAddEmployee').value=s.Employee||'';
      $('#scheduleAddStatus').value=s.Completed?'completed':(s.Confirmed?'confirmed':'planned');
      $('#scheduleAddCompany').value=s.Company||'';
      $('#scheduleAddCompanyId').value=(Array.isArray(s.CompanyIds)?s.CompanyIds[0]:'')||'';
      $('#scheduleAddDetail').value=s.Detail||'';
      $('#scheduleAddNote').value=s.Note||'';
      const title=document.querySelector('#dfViewScheduleAdd .view-title, #dfViewScheduleAdd h2');if(title)title.dataset.v1101Original=title.dataset.v1101Original||title.textContent,title.textContent='일정 수정';
      const save=$('#scheduleAddSave');if(save)save.textContent='수정 저장';
    }
  }else{
    const title=document.querySelector('#dfViewScheduleAdd .view-title, #dfViewScheduleAdd h2');if(title&&title.dataset.v1101Original)title.textContent=title.dataset.v1101Original;
    const save=$('#scheduleAddSave');if(save)save.textContent='일정 저장';
  }
}
let dfV1126ScheduleAddSaving=false;
async function scheduleAddSave(){
  // v112.6: 연속 클릭/더블클릭으로 동일 일정이 여러 건 생성되는 것을 방지한다.
  if(dfV1126ScheduleAddSaving)return;
  if(!companyState.db){alert('업체/일정 DB를 불러오는 중입니다.');return}
  const date=$('#scheduleAddDate').value;if(!date){alert('일정일을 입력해주세요.');return}
  const type=$('#scheduleAddType').value,status=$('#scheduleAddStatus').value,c=scheduleAddCompany(),companyName=$('#scheduleAddCompany').value.trim();
  if(type==='측정출장'&&!companyName){alert('측정출장은 업체를 선택하거나 입력해주세요.');return}
  const editing=dfV1101ScheduleEditId?scheduleItems().find(x=>String(x.Id)===String(dfV1101ScheduleEditId)):null;
  const saveBtn=$('#scheduleAddSave');
  dfV1126ScheduleAddSaving=true;
  if(saveBtn){saveBtn.disabled=true;saveBtn.dataset.prevText=saveBtn.textContent||'';saveBtn.textContent='저장 중...';}
  try{
    const nowIso=new Date().toISOString().slice(0,19),nowText=nowIso.replace('T',' ');
    const s=editing||{Id:`schedule-web-${Date.now()}-${Math.random().toString(36).slice(2,7)}`,CreatedAt:nowIso,Deleted:false};
    Object.assign(s,{Date:date,Employee:$('#scheduleAddEmployee').value.trim(),Type:type,Company:companyName,Companies:companyName?[companyName]:[],CompanyIds:c?[c.Id]:[],
      Facility:'',Facilities:[],FacilityIds:[],FacilityPlans:[],MeasurementItems:'',
      Detail:$('#scheduleAddDetail').value.trim()||companyName,Note:$('#scheduleAddNote').value.trim(),
      Confirmed:status!=='planned',ConfirmedAt:status!=='planned'?(s.ConfirmedAt||nowText):'',Completed:status==='completed',CompletedAt:status==='completed'?(s.CompletedAt||nowText):'',
      UpdatedAt:nowIso,UpdatedBy:editing?'웹 일정수정':'웹 일정등록',Deleted:false});
    companyState.db.Schedules=companyState.db.Schedules||[];if(!editing)companyState.db.Schedules.push(s);
    try{companySaveDb()}catch(e){console.warn('일정 로컬저장',e)}
    const ok=await dfV95SyncSchedule(s);
    scheduleState.selectedDate=date;scheduleState.selectedId=s.Id;const d=scheduleDateObj(date);scheduleState.year=d.getFullYear();scheduleState.month=d.getMonth()+1;
    scheduleRenderAll();companyRender();
    const stateEl=document.getElementById('companyOnlineState');if(stateEl&&!ok){stateEl.textContent='일정 온라인 저장 실패 · Supabase 권한 확인';stateEl.className='company-online-state warn'}
    if(ok){
      const wasEdit=!!dfV1101ScheduleEditId;dfV1101ScheduleEditId='';
      alert(`${wasEdit?'일정 수정이 저장되었습니다.':'일정이 저장되었습니다.'}\n${date} · ${companyName||type}`);
      window.dfScheduleAddDraftClear?.();scheduleAddClear(true);await dfV1101RefreshSchedulesOnline(false);try{history.replaceState({dfRoute:'schedule'},'','#schedule')}catch(e){}window.v62ShowOnly?.('schedule',{history:false});
    }else{
      // 신규 등록이 온라인 저장에 실패한 경우 로컬에 중복 임시행이 남지 않도록 제거한다.
      if(!editing){companyState.db.Schedules=companyState.db.Schedules.filter(x=>String(x.Id)!==String(s.Id));try{companySaveDb()}catch(e){}}
      alert('일정 온라인 저장에 실패했습니다.\n입력 내용은 그대로 두었습니다. 연결 상태를 확인한 뒤 다시 저장해주세요.');
    }
  }finally{
    dfV1126ScheduleAddSaving=false;
    if(saveBtn){saveBtn.disabled=false;saveBtn.textContent=dfV1101ScheduleEditId?'수정 저장':'일정 저장';delete saveBtn.dataset.prevText;}
  }
}

function initScheduleAdd(){
  if(!$('#scheduleAddDate'))return;
  scheduleAddFillCompanies();
  $('#scheduleAddDate').value=scheduleState.selectedDate||scheduleIso(new Date());
  bindScheduleSmartPick();
  // v96.1: 시설/항목 UI를 제거했으므로 존재하지 않는 버튼에 이벤트를 걸지 않는다.
  const clearBtn=$('#scheduleAddClear');
  const saveBtn=$('#scheduleAddSave');
  const backBtn=$('#scheduleAddBack');
  if(clearBtn)clearBtn.onclick=()=>{window.dfScheduleAddDraftClear?.();scheduleAddClear(true)};
  if(saveBtn)saveBtn.onclick=scheduleAddSave;
  if(backBtn)backBtn.onclick=()=>{dfV1101ScheduleEditId='';try{if(history.state?.dfRoute==='schedule-add'&&history.length>1){history.back();return}}catch(e){}window.v62ShowOnly?.('schedule')};
  // v112.7: 일정등록 작성 중 값은 같은 탭의 임시초안으로 보존한다.
  const draftKey='dreampoen_schedule_add_draft_v1127';
  const ids=['scheduleAddDate','scheduleAddType','scheduleAddEmployee','scheduleAddStatus','scheduleAddCompany','scheduleAddCompanyId','scheduleAddDetail','scheduleAddNote'];
  const saveDraft=()=>{if(dfV1101ScheduleEditId)return;const d={};ids.forEach(id=>{const el=document.getElementById(id);if(el)d[id]=el.value});try{sessionStorage.setItem(draftKey,JSON.stringify(d))}catch(e){}};
  document.getElementById('dfViewScheduleAdd')?.addEventListener('input',saveDraft);
  document.getElementById('dfViewScheduleAdd')?.addEventListener('change',saveDraft);
  const restoreDraft=()=>{try{const d=JSON.parse(sessionStorage.getItem(draftKey)||'null');if(d&&!dfV1101ScheduleEditId){ids.forEach(id=>{const el=document.getElementById(id);if(el&&d[id]!=null)el.value=d[id]})}}catch(e){}};
  restoreDraft();window.dfScheduleAddDraftRestore=restoreDraft;
  window.dfScheduleAddDraftClear=()=>{try{sessionStorage.removeItem(draftKey)}catch(e){}};
}
document.addEventListener('DOMContentLoaded',initScheduleAdd);

