// v65 LAB Raw Data
// "기록 저장" 확정본(data)만 조회 / 시료채취값 readonly
// ==========================================================
let analysisSelectedRecordId=null;
const ANALYSIS_INPUT_CACHE_KEY='dreampoen_lab_raw_input_v64';

function analysisInputCache(){
  try{return JSON.parse(localStorage.getItem(ANALYSIS_INPUT_CACHE_KEY)||'{}')||{}}
  catch{return {}}
}
function saveAnalysisInputCache(){
  if(!analysisSelectedRecordId)return;
  const cache=analysisInputCache();
  const lab={};
  document.querySelectorAll('[data-lab-card]').forEach(card=>{
    const key=card.dataset.labKey||card.dataset.labCard||'';
    if(!key)return;
    const values={};
    card.querySelectorAll('input,select').forEach(el=>{
      const k=el.dataset.labField||el.name||el.id;
      if(!k)return;
      values[k]=el.type==='checkbox'?!!el.checked:el.value;
    });
    lab[key]=values;
  });
  cache[analysisSelectedRecordId]={
    dustWeightBefore:document.getElementById('dustWeightBefore')?.value||'',
    dustWeightAfter:document.getElementById('dustWeightAfter')?.value||'',
    dustCorrection:!!document.getElementById('dustOxygenCorrection')?.checked,
    lab,
    _localUpdatedAt:new Date().toISOString()
  };
  localStorage.setItem(ANALYSIS_INPUT_CACHE_KEY,JSON.stringify(cache));
  const st=document.getElementById('analysisSaveStatus');
  if(st){st.textContent='자동저장됨';st.classList.add('saved')}
}
function restoreAnalysisInputCache(id){
  const x=analysisInputCache()[id]||{};
  const b=document.getElementById('dustWeightBefore'),a=document.getElementById('dustWeightAfter');
  if(b)b.value=x.dustWeightBefore||'';
  if(a)a.value=x.dustWeightAfter||'';
  const dc=document.getElementById('dustOxygenCorrection');if(dc)dc.checked=!!x.dustCorrection;
  window.dfV100PendingLabCache=x.lab||{};
}

function analysisSavedRecords(){
  // RECORDS_KEY에는 기록 저장을 누른 기록만 생성된다.
  // autosaveData는 절대 사용하지 않고 마지막 확정본 data만 분석한다.
  const rows=typeof readRecordStore==='function'?readRecordStore():[];
  const latest=new Map();

  rows.forEach((r,idx)=>{
    if(!r?.data)return;
    const data=r.data, fields=data.fields||{};
    const logicalKey=[
      fields.receiptNo||'',
      fields.company||'',
      fields.facility||'',
      data.recordType||''
    ].join('|') || String(r.id||idx);

    const item={
      id:String(r.id||logicalKey),
      raw:r,
      data,
      fields,
      ts:String(r.updatedAt||r.createdAt||''),
      logicalKey
    };
    const prev=latest.get(logicalKey);
    if(!prev || item.ts>=prev.ts)latest.set(logicalKey,item);
  });

  return [...latest.values()].sort((a,b)=>String(b.ts).localeCompare(String(a.ts)));
}
function analysisRecordLabel(r){
  const f=r.fields||{};
  return `${f.receiptNo||'접수번호 미입력'} / ${f.company||'업체명 미입력'} / ${f.facility||'시설명 미입력'}`;
}
function refreshAnalysisRecordList(preserve=true){
  const sel=document.getElementById('analysisRecordSelect');if(!sel)return;
  const oldId=preserve?analysisSelectedRecordId:null;
  const records=analysisSavedRecords();

  sel.innerHTML='<option value="">저장된 기록을 선택하세요</option>';
  records.forEach(r=>{
    const o=document.createElement('option');
    o.value=r.id;
    o.textContent=analysisRecordLabel(r);
    sel.appendChild(o);
  });
  sel._records=records;

  if(oldId&&records.some(r=>r.id===oldId))sel.value=oldId;

  const info=document.getElementById('analysisRecordInfo');
  if(info&&!analysisSelectedRecordId){
    info.textContent=records.length?`기록 저장 완료된 시료채취기록 ${records.length}건`:'기록 저장 완료된 시료채취기록이 없습니다.';
  }
}

function analysisNums(list){return (list||[]).map(v=>parseFloat(v)).filter(Number.isFinite)}
function analysisAvg(list){const a=analysisNums(list);return a.length?a.reduce((s,v)=>s+v,0)/a.length:null}
function analysisSum(list){return analysisNums(list).reduce((s,v)=>s+v,0)}
function analysisFieldNum(fields,...keys){
  for(const k of keys){
    const n=parseFloat(String(fields?.[k]??'').replace(/,/g,''));
    if(Number.isFinite(n))return n;
  }
  return null;
}
function analysisRecordItems(rec){
  const d=rec?.data||{},f=rec?.fields||{},items=[];
  if(d.recordType==='dust'||d.recordType==='combo')items.push('먼지');
  if(d.recordType==='metal'||d.recordType==='combo'){
    const metals=Array.isArray(d.metalItems)&&d.metalItems.length?d.metalItems:(f.metalAnalyte?[f.metalAnalyte]:[]);
    metals.forEach(x=>{if(x&&!items.includes(x))items.push(x)});
  }
  (d.gasRows||[]).forEach(g=>{
    const name=String(g.item||g.name||g.pollutant||'').trim();
    // 중금속은 반드시 중금속 시료채취기록에서만 LAB로 연결한다.
    if(DF_V100_METALS.includes(name))return;
    if(name&&!items.includes(name))items.push(name);
  });
  return items;
}
function renderAnalysisTargetItems(rec){
  const box=document.getElementById('analysisTargetItems');if(!box)return;
  const items=analysisRecordItems(rec);
  box.innerHTML=items.length
    ?items.map(x=>`<span class="analysis-target-chip">${companyEsc(x)}</span>`).join('')
    :'<span class="analysis-target-empty">등록된 분석항목이 없습니다.</span>';
}

const DF_V100_METALS=['구리화합물','크로뮴화합물','니켈화합물','아연화합물','납화합물','베릴륨','카드뮴화합물'];
const DF_V100_VOC_MW={
  '벤젠':78.11,'염화비닐':62.50,'디클로로메탄':84.93,'클로로포름':119.38,'1,2-디클로로에탄':98.96,
  '사염화탄소':153.82,'트리클로로에틸렌':131.39,'테트라클로로에틸렌':165.83,'에틸벤젠':106.17,'스타이렌':104.15,
  '1,3-부타디엔':54.09,'아크릴로니트릴':53.06,'아닐린':93.13
};
function dfV100Canon(name){
  const n=String(name||'').replace(/\s/g,'');
  if(/총탄화수소|THC/i.test(n))return '총탄화수소';
  if(/질소산화물|NOX/i.test(n))return '질소산화물';
  if(/황산화물|SOX/i.test(n))return '황산화물';
  if(/일산화탄소|CO(?!2)/i.test(n))return '일산화탄소';
  if(/염화수소/i.test(n))return '염화수소';
  if(/플루오린|불소/i.test(n))return '플루오린화합물';
  if(/암모니아/i.test(n))return '암모니아';
  if(/황화수소/i.test(n))return '황화수소';
  if(/이황화탄소|CS2/i.test(n))return '이황화탄소';
  if(/페놀/i.test(n))return '페놀화합물';
  if(/사이안화수소|시안화수소/i.test(n))return '사이안화수소';
  if(/브로민|브롬/i.test(n))return '브로민화합물';
  if(/구리(화합물)?/i.test(n))return '구리화합물';
  if(/크로뮴|크롬/i.test(n))return '크로뮴화합물';
  if(/니켈/i.test(n))return '니켈화합물';
  if(/아연/i.test(n))return '아연화합물';
  if(/납(화합물)?/i.test(n))return '납화합물';
  if(/베릴륨/i.test(n))return '베릴륨';
  if(/카드뮴/i.test(n))return '카드뮴화합물';
  if(/중금속/i.test(n))return '중금속';
  return String(name||'').trim();
}
function dfV100Oxygen(rec){
  const d=rec?.data||{},f=rec?.fields||{};
  const measured=analysisAvg(d.o2vals),std=analysisFieldNum(f,'standardO2','stdO2','standardOxygen','oxygenStandard','stdOxygen');
  return {measured:Number.isFinite(measured)?measured:null,std:Number.isFinite(std)?std:null};
}
function dfV100Num(card,key){const n=parseFloat(card.querySelector(`[data-lab-field="${key}"]`)?.value);return Number.isFinite(n)?n:null}
function dfV100Fmt(v,d=3){return Number.isFinite(v)?v.toFixed(d):'-'}
function dfV101DefinitionRows(fields,resultUnit){
  return `<table class="dust-definition-table lab-v101-definition"><thead><tr><th>기호</th><th>항목</th><th>단위</th></tr></thead><tbody>${fields.map(f=>`<tr><td>${companyEsc(f[0])}</td><td>${companyEsc(f[1])}</td><td>${companyEsc(f[2]||'')}</td></tr>`).join('')}<tr><td>C</td><td>최종 분석농도</td><td>${companyEsc(resultUnit||'')}</td></tr></tbody></table>`;
}
function dfV100BaseCard(key,title,method,formula,fields,resultUnit,extra=''){
  return `<section class="analysis-card gas-analysis-card lab-formula-card" data-lab-card data-lab-key="${companyEsc(key)}">
    <div class="analysis-card-title lab-v101-title"><span>•</span><strong>${companyEsc(title)}</strong><em>${companyEsc(method)}</em></div>
    <div class="dust-equation-panel lab-v101-equation-panel"><div class="dust-equation-title">${companyEsc(title)} 계산식</div><div class="lab-v100-formula">${formula}</div></div>
    ${dfV101DefinitionRows(fields,resultUnit)}
    <div class="lab-v100-grid">${fields.map(f=>`<label><span>${f[1]}</span><div><input type="number" step="0.0001" data-lab-field="${f[0]}" ${f[0]==='Vs'?'readonly':''}><b>${f[2]||''}</b></div>${f[0]==='Vs'?'<small class="lab-readonly-note">시료채취기록 연동값</small>':''}</label>`).join('')}</div>
    ${extra}<div class="lab-trace-row" data-lab-trace>값을 입력하면 식 대입값이 표시됩니다.</div><div class="lab-v100-result"><span>최종결과</span><strong data-lab-result>-</strong><b>${resultUnit}</b></div>
  </section>`;
}
function dfV100AnalyzerCard(item){
  const corr=item==='질소산화물'||item==='황산화물';
  const defs=[['C1','1차 측정농도','ppm'],['C2','2차 측정농도','ppm'],['C3','3차 측정농도','ppm'],['C̄','3회 평균농도','ppm']];
  return `<section class="analysis-card gas-analysis-card lab-formula-card lab-analyzer-v101" data-lab-card data-lab-key="${companyEsc(item)}" data-kind="analyzer">
    <div class="analysis-card-title lab-v101-title"><span>•</span><strong>${companyEsc(item)}</strong><em>자동분석기 · 3회 평균</em></div>
    <div class="dust-equation-panel lab-v101-equation-panel"><div class="dust-equation-title">${companyEsc(item)} 농도 계산식</div><div class="lab-v100-formula">C̄ = <span class="lab-frac"><span>C₁ + C₂ + C₃</span><span>3</span></span></div></div>
    ${dfV101DefinitionRows(defs,'ppm')}
    <div class="lab-v101-analyzer-row">${[1,2,3].map(i=>`<label><span>${i}차 측정값</span><div><input type="number" step="0.1" data-lab-field="v${i}"><b>ppm</b></div></label>`).join('')}</div>
    <div class="lab-v100-result small"><span>3회 평균</span><strong data-lab-average>-</strong><b>ppm</b></div>
    ${corr?`<div class="oxygen-correction-box compact"><label><input type="checkbox" data-lab-field="correction"> 표준산소농도보정 적용</label><div class="oxygen-correction-formula fraction-style"><span>C<sub>보정</sub> = C × </span><span class="lab-frac"><span>21 − O<sub>s</sub></span><span>21 − O₂</span></span></div></div>`:''}
    <div class="lab-v100-result"><span>최종결과</span><strong data-lab-final>-</strong><b>ppm</b></div>
  </section>`;
}
function dfV100WetCard(item){
  if(item==='이황화탄소'||item==='페놀화합물')return dfV100BaseCard(item,item,'시험방법 계산식 확인 필요','C = <span class="lab-formula-pending">원본 분석식 연결 대기</span>', [['a','분석용 시료용액 값',''],['b','현장바탕 시료용액 값',''],['Vs','표준상태 건조가스 시료채취량','L']], 'ppm');
  if(item==='암모니아')return dfV100BaseCard(item,item,'인도페놀법','C = <span class="lab-frac"><span>(a − b) × 25</span><span>Vs</span></span>', [['a','분석용 시료용액의 암모니아 부피','µL'],['b','현장바탕 시료용액의 암모니아 부피','µL'],['Vs','표준상태 건조가스 시료채취량','L']], 'ppm');
  if(item==='황화수소')return dfV100BaseCard(item,item,'메틸렌블루법','C = <span class="lab-frac"><span>(a − b) × 10</span><span>Vs</span></span> × <span class="lab-frac"><span>22.4</span><span>32.06</span></span>', [['a','분석용 시료용액의 황화 이온 질량','µg'],['b','현장바탕 시료용액의 황화 이온 질량','µg'],['Vs','표준상태 건조가스 시료채취량','L']], 'ppm');
  if(item==='사이안화수소')return dfV100BaseCard(item,item,'4-피리딘카복실산-피라졸론법','C = <span class="lab-frac"><span>(a − b) × 10</span><span>Vs</span></span> × <span class="lab-frac"><span>22.4</span><span>26.017</span></span>', [['a','분석용 시료용액의 사이안화 이온 질량','µg'],['b','현장바탕 시료용액의 사이안화 이온 질량','µg'],['Vs','표준상태 건조가스 시료채취량','L']], 'ppm');
  if(item==='브로민화합물')return dfV100BaseCard(item,item+' (IC)','이온크로마토그래피','C = <span class="lab-frac"><span>(a − b) × 100</span><span>Vs</span></span> × <span class="lab-frac"><span>22.4</span><span>79.904</span></span>', [['a','분석용 시료용액의 브로민화 이온 농도','mg/L'],['b','현장바탕 시료용액의 브로민화 이온 농도','mg/L'],['Vs','표준상태 건조가스 시료채취량','L']], 'ppm');
  if(item==='염화수소'){
    const extra=`<label class="lab-v100-method"><span>분석방법</span><select data-lab-field="method"><option value="ic">이온크로마토그래피</option><option value="uv">싸이오사이안산제이수은법</option></select></label>`;
    return dfV100BaseCard(item,item,'방법 선택','C = <span class="lab-frac"><span>(a − b) × K</span><span>Vs</span></span> × <span class="lab-frac"><span>22.4</span><span>35.453</span></span>', [['a','분석용 시료용액의 염화 이온 값',''],['b','현장바탕 시료용액의 염화 이온 값',''],['Vs','표준상태 건조가스 시료채취량','L']], 'ppm',extra);
  }
  if(item==='플루오린화합물'){
    const extra=`<label class="lab-v100-method"><span>분석방법</span><select data-lab-field="method"><option value="ic">이온크로마토그래피</option><option value="lanthanum">란타넘-알리자린콤플렉손</option></select></label><label class="lab-v100-method" data-v-wrap><span>분석용 시료용액 전체부피 V</span><div><input type="number" step="0.1" data-lab-field="V"><b>mL</b></div></label>`;
    return dfV100BaseCard(item,item,'방법 선택','IC: C = (a − b) × V / Vs × 22.4 / 18.998 · 분광법: C = (a − b) × 10 / Vs × 22.4 / 18.998', [['a','분석용 시료용액의 플루오린화 이온 값',''],['b','현장바탕 시료용액의 플루오린화 이온 값',''],['Vs','표준상태 건조가스 시료채취량','L']], 'ppm',extra);
  }
  return '';
}
function dfV100MetalCard(defaultItem='구리화합물'){
  const title=`중금속 · ${defaultItem}`;
  const formula=`C<sub>${companyEsc(defaultItem)}</sub> = <span class="lab-frac"><span>(a − b) × V</span><span>V<sub>s</sub></span></span>`;
  const card=dfV100BaseCard(`중금속:${defaultItem}`,title,'유도결합플라스마원자발광분광법',
    formula,
    [['a',`${defaultItem} 분석용 시료용액 농도`,'µg/mL'],['b',`${defaultItem} 현장바탕 시료용액 농도`,'µg/mL'],['V','분석용 시료용액의 전체 부피','mL'],['Vs','표준상태 건조가스 시료채취량','L']], 'mg/Sm³');
  return card.replace('data-lab-card ',`data-lab-card data-kind="metal" data-analyte="${companyEsc(defaultItem)}" `);
}
function dfV100VocCard(defaultItem='벤젠'){
  const M=DF_V100_VOC_MW[defaultItem]||'';
  const title=`휘발성유기화합물 · ${defaultItem}`;
  const extra=`<div class="lab-v100-mw">분자량 M = <strong data-lab-mw>${M}</strong> g/mol</div>`;
  const card=dfV100BaseCard(`VOC:${defaultItem}`,title,'기체크로마토그래피 · 고체흡착 열탈착법',
    'C = <span class="lab-frac"><span>m<sub>s</sub> − m<sub>b</sub></span><span>V<sub>s</sub></span></span> × <span class="lab-frac"><span>22.4</span><span>M</span></span>',
    [['ms','시료 중 분석물질 양','µg'],['mb','현장바탕시료 중 분석물질 양','µg'],['Vs','표준상태 환산 시료가스량','L']], 'ppm',extra);
  return card.replace('data-lab-card ',`data-lab-card data-kind="voc" data-analyte="${companyEsc(defaultItem)}" `);
}
function dfV100CalcCard(card,rec){
  const kind=card.dataset.kind,key=card.dataset.labKey||'';
  if(kind==='analyzer'){
    const vals=['v1','v2','v3'].map(k=>dfV100Num(card,k)).filter(Number.isFinite),avg=vals.length===3?vals.reduce((a,b)=>a+b,0)/3:null;
    const ae=card.querySelector('[data-lab-average]');if(ae)ae.textContent=dfV100Fmt(avg,1);
    const o=dfV100Oxygen(rec),ck=!!card.querySelector('[data-lab-field="correction"]')?.checked;
    const corrected=ck&&avg!==null&&o.measured!==null&&o.std!==null&&o.measured<21&&o.std<21?avg*(21-o.std)/(21-o.measured):null;
    const final=ck?corrected:avg, fe=card.querySelector('[data-lab-final]');if(fe)fe.textContent=dfV100Fmt(final,1);
    saveAnalysisInputCache();return;
  }
  let result=null;
  if(kind==='metal'){
    const a=dfV100Num(card,'a'),b=dfV100Num(card,'b'),V=dfV100Num(card,'V'),Vs=dfV100Num(card,'Vs');
    if([a,b,V,Vs].every(Number.isFinite)&&Vs>0)result=(a-b)*V/Vs;
  }else if(kind==='voc'){
    const ms=dfV100Num(card,'ms'),mb=dfV100Num(card,'mb'),Vs=dfV100Num(card,'Vs'),item=card.dataset.analyte||'벤젠',M=DF_V100_VOC_MW[item];
    const mw=card.querySelector('[data-lab-mw]');if(mw)mw.textContent=M||'-';
    if([ms,mb,Vs,M].every(Number.isFinite)&&Vs>0)result=(ms-mb)/Vs*22.4/M;
  }else{
    const a=dfV100Num(card,'a'),b=dfV100Num(card,'b'),Vs=dfV100Num(card,'Vs');
    if([a,b,Vs].every(Number.isFinite)&&Vs>0){
      if(key==='암모니아')result=(a-b)*25/Vs;
      else if(key==='황화수소')result=(a-b)*10/Vs*22.4/32.06;
      else if(key==='사이안화수소')result=(a-b)*10/Vs*22.4/26.017;
      else if(key==='브로민화합물')result=(a-b)*100/Vs*22.4/79.904;
      else if(key==='염화수소'){const method=card.querySelector('[data-lab-field="method"]')?.value||'ic',K=method==='uv'?50:100;result=(a-b)*K/Vs*22.4/35.453}
      else if(key==='플루오린화합물'){const method=card.querySelector('[data-lab-field="method"]')?.value||'ic';if(method==='ic'){const V=dfV100Num(card,'V');if(Number.isFinite(V))result=(a-b)*V/Vs*22.4/18.998}else result=(a-b)*10/Vs*22.4/18.998}
    }
  }
  const el=card.querySelector('[data-lab-result]');if(el)el.textContent=dfV100Fmt(result,3);
  const tr=card.querySelector('[data-lab-trace]');if(tr){const vals=[...card.querySelectorAll('[data-lab-field]')].filter(x=>x.type!=='checkbox').map(x=>`${x.dataset.labField} = <b>${companyEsc(x.value||'-')}</b>`);const prefix=card.dataset.kind==='metal'&&card.dataset.analyte?`<b>${companyEsc(card.dataset.analyte)}</b> &nbsp; · &nbsp; `:'';tr.innerHTML=prefix+vals.join(' &nbsp; · &nbsp; ')}
  saveAnalysisInputCache();
}

function dfV103AtmMmHg(fields){
  let pa=analysisFieldNum(fields,'locationPressure','pressure');
  if(pa!==null&&pa>800)pa*=0.750061683;
  return pa;
}
function dfV103GasStandardVs(rec,item){
  const d=rec?.data||{}, f=rec?.fields||{}, canon=dfV100Canon(item);
  const g=(d.gasRows||[]).find(x=>dfV100Canon(x.item||x.name||'')===canon);
  if(!g)return null;
  const raw=parseFloat(g.volume),tm=parseFloat(g.temp),pm=parseFloat(g.pressure),pa=dfV103AtmMmHg(f);
  if(![raw,tm,pa].every(Number.isFinite)||raw<=0)return null;
  // 분석자료(2): Vs = 채취량/(273+Tm) × 273/760 × (Pa + Pm)
  const meterPressure=Number.isFinite(pm)?pm:0;
  const vs=raw/(273+tm)*273/760*(pa+meterPressure);
  return Number.isFinite(vs)&&vs>0?vs:null;
}
function dfV103MetalStandardVs(rec){
  if(!['metal','combo'].includes(rec?.data?.recordType))return null;
  const dust=analysisSavedDustDefaults(rec,'metal');
  if(!(dust.vm>0)||dust.theta===null||dust.pa===null)return null;
  const dh=Number.isFinite(dust.deltaH)?dust.deltaH:0;
  const sm3=dust.vm*(273/(273+dust.theta))*((dust.pa+dh/13.6)/760);
  return Number.isFinite(sm3)&&sm3>0?sm3*1000:null;
}
function dfV102SamplingVs(rec,item,kind=''){
  if(kind==='metal')return dfV103MetalStandardVs(rec);
  return dfV103GasStandardVs(rec,item);
}
function dfV102ApplySamplingLockedFields(card,rec){
  const vs=card.querySelector('[data-lab-field="Vs"]');
  if(vs){
    const item=card.dataset.analyte||card.dataset.labKey||'';
    const v=dfV102SamplingVs(rec,item,card.dataset.kind||'');
    vs.value=v!==null?Number(v).toFixed(3):'';
    vs.readOnly=true;
    const note=vs.closest('label')?.querySelector('.lab-readonly-note');
    if(note)note.textContent=(card.dataset.kind==='metal'?'중금속 시료채취기록 자동환산':'가스시료채취량·온도·압력 자동환산');
  }
  if(card.dataset.kind==='metal'){
    const V=card.querySelector('[data-lab-field="V"]');
    if(V){if(!V.value)V.value='250';V.readOnly=true;}
  }
}
function renderPendingAnalysisCards(rec){
  const box=document.getElementById('analysisPendingCards');if(!box)return;
  const raw=analysisRecordItems(rec).filter(x=>x!=='먼지');
  const canon=[...new Set(raw.map(dfV100Canon))];
  let html=[];
  canon.forEach(item=>{
    if(item==='총탄화수소'){html.push(`<section class="analysis-card gas-analysis-card thc-attachment-card"><div class="analysis-card-title"><strong>총탄화수소</strong><em>THC</em></div><div class="thc-attachment-message"><strong>별도 자료 첨부</strong><span>총탄화수소는 분석기 로우데이터 평균자료를 별도 첨부합니다.</span></div></section>`);return}
    if(['질소산화물','황산화물','일산화탄소'].includes(item)){html.push(dfV100AnalyzerCard(item));return}
    if(['염화수소','플루오린화합물','암모니아','황화수소','이황화탄소','페놀화합물','사이안화수소','브로민화합물'].includes(item)){html.push(dfV100WetCard(item));return}
    if(item==='비소화합물'){html.push(dfV100BaseCard('비소화합물','비소화합물','가스상 시료채취 연동','분석식은 시험방법 확인 후 적용', [['a','분석값',''],['b','현장바탕값',''],['Vs','표준상태 환산 시료가스량','L']], '', '<div class="lab-readonly-note">가스상 채취량은 시료채취기록에서 자동 환산됩니다.</div>'));return}
    if(item==='중금속'||DF_V100_METALS.includes(item)){
      if(['metal','combo'].includes(rec?.data?.recordType))html.push(dfV100MetalCard(DF_V100_METALS.includes(item)?item:(rec?.fields?.metalAnalyte||'구리화합물')));
      return;
    }
    if(Object.prototype.hasOwnProperty.call(DF_V100_VOC_MW,item)){html.push(dfV100VocCard(item));return}
    html.push(`<section class="analysis-pending-card"><div><b>${companyEsc(item)}</b><span>분석 로우데이터 연동대상</span></div><em>계산식 추가 예정</em></section>`);
  });
  box.innerHTML=html.join('');
  const cache=window.dfV100PendingLabCache||analysisInputCache()[analysisSelectedRecordId]?.lab||{};
  box.querySelectorAll('[data-lab-card]').forEach(card=>{
    const x=cache[card.dataset.labKey]||{};
    card.querySelectorAll('input,select').forEach(el=>{const k=el.dataset.labField||el.name||el.id;if(!k||x[k]===undefined)return;if(el.type==='checkbox')el.checked=!!x[k];else if(!el.readOnly)el.value=x[k]});
    dfV102ApplySamplingLockedFields(card,rec);
    card.querySelectorAll('input,select').forEach(el=>{el.addEventListener('input',()=>dfV100CalcCard(card,rec));el.addEventListener('change',()=>dfV100CalcCard(card,rec))});
    dfV100CalcCard(card,rec);
  });
  window.dfV100PendingLabCache=null;
}


function analysisSavedDustDefaults(rec,particleKind='dust'){
  const d=rec?.data||{}, f=rec?.fields||{};
  const points=d.recordType==='combo'?(particleKind==='metal'?(d.comboMetalPoints||[]):(d.comboDustPoints||[])):(d.points||[]);

  const vmLiters=analysisSum(points.map(p=>p.volume));
  const vm=vmLiters>0?vmLiters/1000:null;

  const meterIn=analysisAvg(points.map(p=>p.meterIn));
  const meterOut=analysisAvg(points.map(p=>p.meterOut));
  const thetaVals=[meterIn,meterOut].filter(Number.isFinite);
  const theta=thetaVals.length?thetaVals.reduce((s,v)=>s+v,0)/thetaVals.length:null;

  let pa=analysisFieldNum(f,'locationPressure','pressure');
  if(pa!==null&&pa>800)pa*=0.750061683;

  const moist=analysisAvg(d.moist)||0;
  const o2=analysisAvg(d.o2vals)||0;
  const co2=analysisAvg(d.co2vals)||0;
  const n2=100-o2-co2;
  const mdGas=.32*o2+.44*co2+.28*n2;
  const ms=mdGas*(1-moist/100)+(moist/100)*18.01;
  const pitot=analysisFieldNum(f,'pitot')||0;
  const nozzle=analysisFieldNum(f,'nozzleCm')||0;
  const staticAvg=analysisAvg(points.map(p=>p.static))||0;
  const pStack=(pa||0)+staticAvg/13.6;
  const team=String(d.selectedTeam||'2');
  const oc=EQUIPMENT?.[team]?.orificeCoeff||47.6;

  const dhs=[];
  points.forEach(p=>{
    const temp=parseFloat(p.temp), dynamic=parseFloat(p.dynamic), mi=parseFloat(p.meterIn), mo=parseFloat(p.meterOut);
    if(![temp,dynamic,mi,mo].every(Number.isFinite)||!pa||!ms||!nozzle||!pitot)return;
    const Tm=273+(mi+mo)/2, Ts=273+temp;
    const dh=8.009/100000*Math.pow(pitot,2)*oc*(Tm*pStack*mdGas)/(Ts*pa*ms)*Math.pow(1-moist/100,2)*Math.pow(nozzle*10,4)*dynamic;
    if(Number.isFinite(dh))dhs.push(dh);
  });
  const deltaH=dhs.length?dhs.reduce((s,v)=>s+v,0)/dhs.length:null;
  return {vm,theta,pa,deltaH};
}

function fmtAnalysis(v,d=3){
  const n=parseFloat(v);
  return Number.isFinite(n)?n.toFixed(d):'';
}
function updateDustEquationDynamic(){
  const md=document.getElementById('dustMd')?.value;
  const vm=document.getElementById('dustVm')?.value;
  const theta=document.getElementById('dustTheta')?.value;
  const pa=document.getElementById('dustPa')?.value;
  const dh=document.getElementById('dustDeltaH')?.value;
  const eq=document.getElementById('dustEquationDynamic');if(!eq)return;

  eq.innerHTML=`
    <span class="eq-left">C<sub>n</sub> =</span>
    <span class="eq-frac">
      <span class="eq-num">m<sub>d</sub> (${fmtAnalysis(md,3)||' '} mg)</span>
      <span class="eq-den">
        V′<sub>m</sub> (${fmtAnalysis(vm,4)||' '} m³)
        × <span class="eq-frac mini"><span class="eq-num">273</span><span class="eq-den">273 + θ<sub>m</sub> (${fmtAnalysis(theta,2)||' '} ℃)</span></span>
        × <span class="eq-frac mini"><span class="eq-num">P<sub>a</sub> (${fmtAnalysis(pa,2)||' '} mmHg) + ΔH (${fmtAnalysis(dh,2)||' '} mmH₂O) / 13.6</span><span class="eq-den">760</span></span>
      </span>
    </span>`;
}
function calcDust(){
  const beforeG=parseFloat(document.getElementById('dustWeightBefore')?.value||'');
  const afterG=parseFloat(document.getElementById('dustWeightAfter')?.value||'');
  const md=(Number.isFinite(beforeG)&&Number.isFinite(afterG))?(afterG-beforeG)*1000:NaN;

  document.getElementById('dustMd').value=Number.isFinite(md)?md.toFixed(3):'';

  const vm=parseFloat(document.getElementById('dustVm')?.value||'');
  const theta=parseFloat(document.getElementById('dustTheta')?.value||'');
  const pa=parseFloat(document.getElementById('dustPa')?.value||'');
  const dh=parseFloat(document.getElementById('dustDeltaH')?.value||'');

  updateDustEquationDynamic();

  const finalEl=document.getElementById('dustFinalResult');
  const subEl=document.getElementById('dustSubstitutionText');
  const ok=[md,vm,theta,pa,dh].every(Number.isFinite)&&vm>0;

  if(!ok){
    finalEl.textContent='-';
    subEl.innerHTML=`m<sub>d</sub> = (채취 후 g − 채취 전 g) × 1,000<br>전·후 여지무게를 입력하세요.`;
    saveAnalysisInputCache();
    return;
  }

  const standardVolume=vm*(273/(273+theta))*((pa+dh/13.6)/760);
  const cn=md/standardVolume;

  const rec=analysisSavedRecords().find(r=>r.id===analysisSelectedRecordId)||null;
  const oxy=dfV100Oxygen(rec), correctionChecked=!!document.getElementById('dustOxygenCorrection')?.checked;
  const corrected=(correctionChecked&&oxy.measured!==null&&oxy.std!==null&&oxy.measured<21&&oxy.std<21)?cn*(21-oxy.std)/(21-oxy.measured):null;
  finalEl.textContent=correctionChecked?(Number.isFinite(corrected)?corrected.toFixed(1):'-'):cn.toFixed(1);
  subEl.innerHTML=
    `m<sub>d</sub> = (${afterG.toFixed(6)} g − ${beforeG.toFixed(6)} g) × 1,000 = <b>${md.toFixed(3)} mg</b><br>`+
    `C<sub>n</sub> = ${md.toFixed(3)} / [${vm.toFixed(4)} × 273/(273 + ${theta.toFixed(2)}) × (${pa.toFixed(2)} + ${dh.toFixed(2)}/13.6)/760] = <b>${cn.toFixed(1)} mg/Sm³</b>`;
  saveAnalysisInputCache();
}

function loadAnalysisRecord(rec,{preserveLab=true}={}){
  const previousId=analysisSelectedRecordId;
  analysisSelectedRecordId=rec?.id||null;

  const f=rec?.fields||{};
  const info=document.getElementById('analysisRecordInfo');
  const meta=document.getElementById('analysisMeta');
  const dust=document.getElementById('analysisDustSheet');
  const empty=document.getElementById('analysisEmpty');

  if(!rec){
    if(info)info.textContent='시료채취기록에서 기록 저장을 완료한 뒤 선택하세요.';
    if(meta)meta.innerHTML='';
    if(dust)dust.style.display='none';
    renderAnalysisTargetItems(null);
    renderPendingAnalysisCards(null);
    if(empty){empty.style.display='flex';empty.textContent='기록 저장 완료된 시료채취기록을 선택하세요.'}
    return;
  }

  const no=f.receiptNo||'', company=f.company||'', facility=f.facility||'', date=f.measureDate||'';
  if(info)info.textContent=`${no||'접수번호 미입력'} / ${company||'업체명 미입력'} / ${facility||'시설명 미입력'}`;
  const saveSt=document.getElementById('analysisSaveStatus');if(saveSt){const has=!!analysisInputCache()[rec.id];saveSt.textContent=has?`${no||'접수번호'} 저장됨`:'저장 전';saveSt.classList.toggle('saved',has)}
  if(meta)meta.innerHTML=`${companyEsc(no)}<br>${companyEsc(company)}<br>${companyEsc(facility)}<br>${companyEsc(date)}`;

  renderAnalysisTargetItems(rec);
  renderPendingAnalysisCards(rec);

  if(['dust','combo'].includes(rec.data?.recordType)){
    dust.style.display='block';
    empty.style.display='none';

    const d=analysisSavedDustDefaults(rec);
    document.getElementById('dustVm').value=d.vm!==null?d.vm.toFixed(4):'';
    document.getElementById('dustTheta').value=d.theta!==null?d.theta.toFixed(2):'';
    document.getElementById('dustPa').value=d.pa!==null?d.pa.toFixed(2):'';
    document.getElementById('dustDeltaH').value=d.deltaH!==null?d.deltaH.toFixed(2):'';

    if(!preserveLab||previousId!==rec.id)restoreAnalysisInputCache(rec.id);
    calcDust();
  }else{
    dust.style.display='none';
    empty.style.display=analysisRecordItems(rec).length?'none':'flex';
  }
}

function openAnalysisView(){
  if(typeof v62ShowOnly==='function')v62ShowOnly('analysis');
  refreshAnalysisRecordList(true);
  if(analysisSelectedRecordId){
    const rec=analysisSavedRecords().find(r=>r.id===analysisSelectedRecordId);
    if(rec)loadAnalysisRecord(rec,{preserveLab:true});
  }
}

document.addEventListener('DOMContentLoaded',()=>{
  refreshAnalysisRecordList();

  document.getElementById('analysisRecordSelect')?.addEventListener('change',e=>{
    const rec=(e.target._records||[]).find(r=>r.id===e.target.value)||null;
    loadAnalysisRecord(rec,{preserveLab:false});
  });

  document.getElementById('analysisSaveBtn')?.addEventListener('click',()=>{
    if(!analysisSelectedRecordId){alert('먼저 시료채취기록을 선택해주세요.');return}
    saveAnalysisInputCache();
    const rec=analysisSavedRecords().find(r=>r.id===analysisSelectedRecordId), no=rec?.fields?.receiptNo||'접수번호 미입력';
    const st=document.getElementById('analysisSaveStatus');if(st){st.textContent=`${no} 저장완료`;st.classList.add('saved')}
    alert(`LAB 저장 완료\n${no}`);
  });

  document.getElementById('analysisRefreshBtn')?.addEventListener('click',()=>{
    saveAnalysisInputCache();
    refreshAnalysisRecordList(true);
    if(analysisSelectedRecordId){
      const rec=analysisSavedRecords().find(r=>r.id===analysisSelectedRecordId);
      if(rec)loadAnalysisRecord(rec,{preserveLab:true});
    }
  });

  // 분석실에서 입력 가능한 것은 전/후 여지무게뿐
  ['dustWeightBefore','dustWeightAfter'].forEach(id=>{
    document.getElementById(id)?.addEventListener('input',calcDust);
  });
  document.getElementById('dustOxygenCorrection')?.addEventListener('change',calcDust);

  document.getElementById('analysisPrintBtn')?.addEventListener('click',()=>{
    calcDust();
    document.body.classList.add('analysis-printing');
    window.print();
    setTimeout(()=>document.body.classList.remove('analysis-printing'),300);
  });
});

function v66ReloadSelectedAnalysis(){
  if(!analysisSelectedRecordId)return;
  const rec=analysisSavedRecords().find(r=>r.id===analysisSelectedRecordId);
  if(rec){
    const sel=document.getElementById('analysisRecordSelect');
    if(sel)sel.value=rec.id;
    loadAnalysisRecord(rec,{preserveLab:true});
  }
}
document.addEventListener('dreampoen:record-saved',e=>{
  const id=e.detail?.id;
  refreshAnalysisRecordList(true);
  // 저장한 기록이 현재 LAB 선택기록이면 즉시 최신 항목으로 재로딩.
  if(id && analysisSelectedRecordId===id){
    v66ReloadSelectedAnalysis();
  }
});

