// v68 Supabase 업체/시설 온라인화 + 관리자 계약관리
// ==========================================================
let dfV68ActiveContractData=null;
const dfV68ContractState={rows:[],loaded:false,selectedId:null,year:'2026',status:'all',search:''};

function dfV68NormName(v){return String(v||'').toLowerCase().replace(/주식회사|\(주\)|㈜/g,'').replace(/[\s\-_/().,\[\]]+/g,'')}
function dfV68Biz(v){return String(v||'').replace(/\D/g,'')}
function dfV68CompanyIsCurrent(c){
  if(!dfV68ActiveContractData)return true;
  const biz=dfV68Biz(c?.BizNo);
  if(biz && (dfV68ActiveContractData.business_numbers||[]).includes(biz))return true;
  const n=dfV68NormName(c?.Name);
  if(!n)return false;
  return (dfV68ActiveContractData.company_names||[]).some(x=>{
    const k=dfV68NormName(x);return k===n || (k.length>=5 && (n.includes(k)||k.includes(n)));
  });
}


function dfV68ScheduleIsCurrent(s){
  const names=(s?.Companies&&s.Companies.length)?s.Companies:[s?.Company].filter(Boolean);
  if(!names.length)return true; // 연차/교육/내부일정 등 업체가 없는 일정은 유지
  return names.some(name=>{
    const n=dfV68NormName(name);
    const c=(companyState?.db?.Companies||[]).find(x=>dfV68NormName(x.Name)===n);
    if(c)return dfV68CompanyIsCurrent(c);
    if(!dfV68ActiveContractData)return true;
    return (dfV68ActiveContractData.company_names||[]).some(x=>{const k=dfV68NormName(x);return k===n||(k.length>=5&&(n.includes(k)||k.includes(n)))})
  });
}

async function dfV68RefreshCurrentContractCompaniesOnline(){
  if(!dfSupabase||!dfCloudUser)return;
  try{
    const rows=await dfV68FetchAll('current_contract_companies_safe','company_name,biz_no');
    if(!rows.length){
      const s=document.getElementById('companyContractFilterState');
      if(s)s.textContent='계약업체 기준 · 배포DB 사용';
      return;
    }
    const names=[],biz=[];
    rows.forEach(r=>{
      String(r.company_name||'').split('[.]').forEach(x=>{x=x.trim();if(x&&!names.includes(x))names.push(x)});
      String(r.biz_no||'').split('[.]').forEach(x=>{const b=dfV68Biz(x);if(b&&!biz.includes(b))biz.push(b)})
    });
    const candidate={company_names:names,business_numbers:biz};

    // v72: 온라인 view의 명칭이 업체 DB와 맞지 않아 0건이 되는 경우
    // 정상적으로 들어있던 배포 기준 264개를 덮어쓰지 않는다.
    const companies=companyState?.db?.Companies||[];
    const matches=companies.filter(c=>{
      const b=dfV68Biz(c?.BizNo);
      if(b&&candidate.business_numbers.includes(b))return true;
      const n=dfV68NormName(c?.Name);if(!n)return false;
      return candidate.company_names.some(x=>{const k=dfV68NormName(x);return k===n||(k.length>=5&&(n.includes(k)||k.includes(n)))});
    }).length;

    if(companies.length && matches===0){
      console.warn('v72: 온라인 현재계약 view가 업체DB와 0건 매칭되어 기존 계약업체 기준을 유지합니다.');
      const s=document.getElementById('companyContractFilterState');
      if(s)s.textContent='계약업체 기준 · 기존DB 유지';
      if(companyState?.db){companyRender();syncSampleCompanySelectors(true);scheduleRenderAll()}
      return;
    }

    dfV68ActiveContractData=candidate;
    const s=document.getElementById('companyContractFilterState');
    if(s)s.textContent=`계약진행 업체 · ${matches||rows.length}개`;
    if(companyState?.db){companyRender();syncSampleCompanySelectors(true);scheduleRenderAll()}
  }catch(e){
    console.warn('현재 계약업체 온라인 기준 조회 실패 - 배포 기준 파일 사용',e);
    const s=document.getElementById('companyContractFilterState');
    if(s)s.textContent='계약업체 기준 · 배포DB 사용';
  }
}

async function dfV68LoadCurrentContractCompanies(){
  try{
    const r=await fetch('./data/active_contract_companies.json',{cache:'no-store'});if(!r.ok)throw Error('현재계약 업체 기준 파일을 불러오지 못했습니다.');
    dfV68ActiveContractData=await r.json();
    const s=document.getElementById('companyContractFilterState');
    if(s)s.textContent=`계약진행 기준 · ${dfV68ActiveContractData.company_names?.length||0}개`;
    if(companyState?.db){companyRender();syncSampleCompanySelectors(true);scheduleRenderAll();}
  }catch(e){console.error('v68 current contract filter',e)}
}

function dfApplyRoleAccess(profile){
  const admin=String(profile?.role||'').toLowerCase()==='admin';
  const nav=document.getElementById('dfContractNav');if(nav)nav.hidden=!admin;const empNav=document.getElementById('dfEmployeesNav');if(empNav)empNav.hidden=!admin;document.querySelectorAll('.df-admin-only').forEach(el=>{el.hidden=!admin});if(admin)setTimeout(()=>dfEmployeesUpdatePendingBadge(),250);
  let badge=document.getElementById('dfRoleBadge');
  if(!badge){badge=document.createElement('div');badge.id='dfRoleBadge';badge.className='df-role-badge';document.querySelector('.df-side-nav')?.before(badge)}
  if(badge)badge.textContent=admin?'관리자 계정 · 전체 권한':`${profile?.name||'직원'} · 업무 화면`;
  if(!admin && document.querySelector('.df-nav-item[data-view="contract"].active'))window.v62ShowOnly?.('sample');
  dfV68OnlineBootstrap();dfV68RefreshCurrentContractCompaniesOnline();
}

