// v110 관리자 직원관리 - 승인 / 권한 / 소속 관리
// ==========================================================
function dfEmployeeEsc(v){return String(v??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]))}
function dfEmployeesMsg(text,type=''){const e=document.getElementById('dfEmployeesMessage');if(!e)return;e.textContent=text||'';e.className='df-employees-message'+(type?' '+type:'')}
function dfEmployeeTeamOptions(value){const opts=['','관리','사무실','1팀','2팀','LAB'];return opts.map(v=>`<option value="${dfEmployeeEsc(v)}" ${String(value||'')===v?'selected':''}>${v||'미지정'}</option>`).join('')}
function dfEmployeeRoleOptions(value){return [['staff','직원'],['admin','관리자']].map(([v,l])=>`<option value="${v}" ${String(value||'staff')===v?'selected':''}>${l}</option>`).join('')}
async function dfEmployeesFetch(){if(!dfSupabase)throw Error('온라인 DB에 연결되어 있지 않습니다.');if(!dfV68IsAdmin())throw Error('관리자만 직원관리를 사용할 수 있습니다.');const {data,error}=await dfSupabase.from('profiles').select('id,name,email,role,team,active').order('active',{ascending:true}).order('name',{ascending:true});if(error)throw error;return data||[]}
function dfEmployeesRender(rows){const list=document.getElementById('dfEmployeesList');if(!list)return;const pending=rows.filter(r=>!r.active).length,active=rows.filter(r=>!!r.active).length;document.getElementById('dfEmployeesTotal').textContent=rows.length;document.getElementById('dfEmployeesPending').textContent=pending;document.getElementById('dfEmployeesActive').textContent=active;const badge=document.getElementById('dfEmployeePendingBadge');if(badge){badge.textContent=pending;badge.hidden=!pending}if(!rows.length){list.innerHTML='<div class="df-employees-empty">등록된 직원이 없습니다.</div>';return}list.innerHTML=rows.map(r=>{const self=r.id===dfCloudUser?.id;const status=r.active?'사용중':'승인대기';return `<div class="df-employee-card ${r.active?'active':'pending'}" data-employee-id="${dfEmployeeEsc(r.id)}"><div class="df-employee-person"><strong>${dfEmployeeEsc(r.name||'이름 없음')}</strong><small>${dfEmployeeEsc(r.email||r.id)}</small><span class="status">${status}${self?' · 내 계정':''}</span></div><div class="df-employee-field"><label>권한</label><select data-emp-role ${self?'disabled':''}>${dfEmployeeRoleOptions(r.role)}</select></div><div class="df-employee-field"><label>소속</label><select data-emp-team>${dfEmployeeTeamOptions(r.team)}</select></div><div class="df-employee-actions"><button type="button" data-emp-save>설정 저장</button>${r.active?`<button type="button" class="disable" data-emp-disable ${self?'disabled':''}>사용중지</button>`:`<button type="button" class="approve" data-emp-approve>승인</button>`}</div></div>`}).join('');list.querySelectorAll('[data-employee-id]').forEach(card=>{const id=card.dataset.employeeId;card.querySelector('[data-emp-save]')?.addEventListener('click',()=>dfEmployeesSaveCard(card,id,false));card.querySelector('[data-emp-approve]')?.addEventListener('click',()=>dfEmployeesSaveCard(card,id,true));card.querySelector('[data-emp-disable]')?.addEventListener('click',()=>dfEmployeesDisable(id));})}
async function dfEmployeesLoad(){if(!dfV68IsAdmin())return;try{dfEmployeesMsg('직원 정보를 불러오는 중입니다.');const rows=await dfEmployeesFetch();dfEmployeesRender(rows);dfEmployeesMsg('')}catch(e){dfEmployeesMsg('직원 정보를 불러오지 못했습니다: '+e.message,'bad')}}
async function dfEmployeesSaveCard(card,id,approve){try{const role=card.querySelector('[data-emp-role]')?.value||'staff',team=card.querySelector('[data-emp-team]')?.value||null;if(id===dfCloudUser?.id&&role!=='admin')throw Error('현재 로그인한 관리자 계정의 관리자 권한은 해제할 수 없습니다.');dfEmployeesMsg(approve?'승인 처리 중...':'설정 저장 중...');const payload={role,team};if(approve)payload.active=true;const {error}=await dfSupabase.from('profiles').update(payload).eq('id',id);if(error)throw error;dfEmployeesMsg(approve?'승인되었습니다.':'설정을 저장했습니다.','ok');await dfEmployeesLoad()}catch(e){dfEmployeesMsg('처리 실패: '+e.message,'bad')}}
async function dfEmployeesDisable(id){if(id===dfCloudUser?.id){dfEmployeesMsg('현재 로그인한 관리자 본인 계정은 사용중지할 수 없습니다.','bad');return}if(!confirm('이 직원의 시스템 사용을 중지할까요?'))return;try{dfEmployeesMsg('사용중지 처리 중...');const {error}=await dfSupabase.from('profiles').update({active:false}).eq('id',id);if(error)throw error;dfEmployeesMsg('사용중지되었습니다.','ok');await dfEmployeesLoad()}catch(e){dfEmployeesMsg('사용중지 실패: '+e.message,'bad')}}
async function dfEmployeesUpdatePendingBadge(){if(!dfSupabase||!dfV68IsAdmin())return;try{const {count,error}=await dfSupabase.from('profiles').select('id',{count:'exact',head:true}).eq('active',false);if(error)throw error;const b=document.getElementById('dfEmployeePendingBadge');if(b){b.textContent=count||0;b.hidden=!(count>0)}}catch(e){console.warn('직원 승인대기 확인',e)}}
document.addEventListener('DOMContentLoaded',()=>{document.getElementById('dfEmployeesRefresh')?.addEventListener('click',dfEmployeesLoad)});

function dfV68IsAdmin(){return String(dfCloudProfile?.role||'').toLowerCase()==='admin'}

async function dfV68FetchAll(table,columns='*',orderCol=''){
  const out=[];let from=0;const size=1000;
  while(true){
    let q=dfSupabase.from(table).select(columns).range(from,from+size-1);
    if(orderCol)q=q.order(orderCol,{ascending:true});
    const {data,error}=await q;if(error)throw error;
    out.push(...(data||[]));if(!data||data.length<size)break;from+=size;
  }
  return out;
}
function dfV68CompanyRow(c){
  return {legacy_id:String(c.Id||''),name:c.Name||'',address:c.Address||'',biz_no:c.BizNo||'',representative:c.Representative||'',environment_manager:c.EnvironmentManager||'',phone:c.Phone||'',email:c.Email||'',industry:c.Industry||'',grade:c.Grade||'',cycle:c.Cycle||'',measurement_items:c.MeasurementItems||[],measurement_history:c.MeasurementHistory||[],tracking:c.Tracking||{},active:c.Active!==false,extra_data:{PreventionFacility:c.PreventionFacility||'',EmissionFacility:c.EmissionFacility||'',StackHeight:c.StackHeight||'',Item:c.Item||'',UpdatedAt:c.UpdatedAt||'',FacilityMasterSource:c.FacilityMasterSource||'',ManualMeasurementDates:Array.isArray(c.ManualMeasurementDates)?c.ManualMeasurementDates:null}};
}
function dfV79NumOrNull(v){
  if(v===null||v===undefined||String(v).trim()==='')return null;
  const n=Number(String(v).replace(/,/g,'').trim());
  return Number.isFinite(n)?n:null;
}
function dfV95NormalizeItemCycles(raw,items,defaultCycle){
  const list=[];
  if(Array.isArray(raw)){
    raw.forEach(x=>{if(x&&typeof x==='object'&&String(x.Item||x.item||'').trim())list.push({Item:String(x.Item||x.item||'').trim(),Cycle:String(x.Cycle||x.cycle||defaultCycle||'반기 1회').trim()})});
  }else if(raw&&typeof raw==='object'){
    Object.entries(raw).forEach(([item,cycle])=>{if(String(item||'').trim())list.push({Item:String(item).trim(),Cycle:String(cycle||defaultCycle||'반기 1회').trim()})});
  }
  const known=new Set(list.map(x=>x.Item));
  (Array.isArray(items)?items:[]).forEach(item=>{item=String(item||'').trim();if(item&&!known.has(item)){list.push({Item:item,Cycle:String(defaultCycle||'반기 1회').trim()});known.add(item)}});
  return list;
}
function dfV68FacilityRow(f,companyId){
  return {
    legacy_id:String(f.Id||''),company_id:companyId,
    name:f.FacilityName||'',prevention_facility:f.PreventionFacility||f.FacilityName||'',emission_facility:f.EmissionFacility||'',
    capacity:dfV79NumOrNull(f.Capacity),stack_height:dfV79NumOrNull(f.StackHeight),
    cycle:f.Cycle||'',items:f.Items||[],item_cycles:f.ItemCycles||[],stack_shape:f.StackShape||'',
    diameter:dfV79NumOrNull(f.Diameter),stack_w:dfV79NumOrNull(f.StackW),stack_h:dfV79NumOrNull(f.StackH),
    dimension_raw:f.DimensionRaw||'',measurement_history:f.MeasurementHistory||[],memo:f.Memo||'',extra_data:{Source:f.Source||'',ManualMeasurementDates:Array.isArray(f.ManualMeasurementDates)?f.ManualMeasurementDates:null}
  };
}
async function dfV68UpsertChunks(table,rows,onConflict){
  for(let i=0;i<rows.length;i+=150){const {error}=await dfSupabase.from(table).upsert(rows.slice(i,i+150),{onConflict});if(error)throw error}
}
async function dfV68PushInitialCompanies(){
  const src=companyState?.db?.Companies||[];if(!src.length)return;
  await dfV68UpsertChunks('companies',src.map(dfV68CompanyRow),'legacy_id');
  const online=await dfV68FetchAll('companies','id,legacy_id');const map=new Map(online.map(x=>[String(x.legacy_id),x.id]));
  const fac=[];src.forEach(c=>(c.Facilities||[]).forEach(f=>{const id=map.get(String(c.Id));if(id&&f.Id)fac.push(dfV68FacilityRow(f,id))}));
  await dfV68UpsertChunks('facilities',fac,'legacy_id');
}
async function dfV96PullSchedules(){
  if(!dfSupabase||!dfCloudUser)return 0;
  try{
    const rows=await dfV68FetchAll('schedules','*','schedule_date');
    if(!rows.length)return 0;
    const companies=companyState.db?.Companies||[];
    const uuidToLegacy=new Map();
    // company_id UUID를 legacy_id로 변환하기 위한 현재 companies 재조회
    const cr=await dfV68FetchAll('companies','id,legacy_id');cr.forEach(x=>uuidToLegacy.set(String(x.id),String(x.legacy_id||x.id)));
    const mapped=rows.map(r=>{const x=r.extra_data||{};const legacy=x.legacy_id||`schedule-online-${r.id}`;const companyLegacy=r.company_id?uuidToLegacy.get(String(r.company_id)):'';return {
      Id:String(legacy),OnlineId:r.id,Date:r.schedule_date||'',Employee:r.employee||'',Team:r.team||'',Type:r.schedule_type||'',Company:x.company||'',Companies:Array.isArray(x.companies)?x.companies:(x.company?[x.company]:[]),CompanyIds:companyLegacy?[companyLegacy]:[],
      Facility:'',Facilities:[],FacilityIds:[],FacilityPlans:[],MeasurementItems:'',Detail:r.detail||'',Note:r.memo||'',Confirmed:r.status==='confirmed'||r.status==='completed'||x.confirmed===true,ConfirmedAt:x.confirmed_at||'',Completed:!!r.completed||r.status==='completed',CompletedAt:x.completed_at||'',Deleted:x.deleted===true,UpdatedAt:r.updated_at||x.updated_at||'',UpdatedBy:x.updated_by||'온라인'
    }});
    const existing=companyState.db?.Schedules||[];const map=new Map(existing.map(s=>[String(s.Id),s]));mapped.forEach(s=>map.set(String(s.Id),s));companyState.db.Schedules=[...map.values()];
    try{companySaveDb()}catch(e){console.warn('온라인 일정 로컬 캐시 저장 생략',e)}
    return mapped.length;
  }catch(e){console.warn('온라인 일정 불러오기 실패',e);return 0;}
}
async function dfV68PullCompanies(){
  const cs=await dfV68FetchAll('companies','*','name');
  if(!cs.length)return false;
  const fs=await dfV68FetchAll('facilities','*');const byCompany=new Map();fs.forEach(f=>{if(!byCompany.has(f.company_id))byCompany.set(f.company_id,[]);byCompany.get(f.company_id).push(f)});
  const companies=cs.map(r=>{
    const x=r.extra_data||{};return companyEnsureFields({Id:r.legacy_id||r.id,Name:r.name||'',Address:r.address||'',BizNo:r.biz_no||'',Representative:r.representative||'',EnvironmentManager:r.environment_manager||'',Phone:r.phone||'',Email:r.email||'',Industry:r.industry||'',Grade:r.grade||'',Cycle:r.cycle||'',MeasurementItems:r.measurement_items||[],MeasurementHistory:r.measurement_history||[],Tracking:r.tracking||{},Active:r.active!==false,PreventionFacility:x.PreventionFacility||'',EmissionFacility:x.EmissionFacility||'',StackHeight:x.StackHeight||'',Item:x.Item||'',UpdatedAt:r.updated_at||x.UpdatedAt||'',ManualMeasurementDates:Array.isArray(x.ManualMeasurementDates)?x.ManualMeasurementDates:undefined,Facilities:(byCompany.get(r.id)||[]).map(f=>({Id:f.legacy_id||f.id,FacilityName:f.facility_name||f.name||'',PreventionFacility:f.prevention_facility||f.facility_name||f.name||'',EmissionFacility:f.emission_facility||'',Capacity:f.capacity||'',StackHeight:f.stack_height||'',Cycle:f.cycle||'',Items:f.items||[],ItemCycles:dfV95NormalizeItemCycles(f.item_cycles,f.items,f.cycle),StackShape:f.stack_shape||'',Diameter:f.diameter||'',StackW:(f.stack_w??f.stack_width)??'',StackH:f.stack_h??'',DimensionRaw:f.dimension_raw||'',MeasurementHistory:f.measurement_history||[],Memo:f.memo||'',ManualMeasurementDates:Array.isArray(f.extra_data?.ManualMeasurementDates)?f.extra_data.ManualMeasurementDates:undefined,Source:f.extra_data?.Source||f.extra_data?.migration_source||''}))});
  });
  if(!companyState.db)companyState.db={Companies:[],Schedules:[]};
  companyState.db.Companies=companies;
  await dfV96PullSchedules();
  try{companySaveDb()}catch(e){console.warn('업체/일정 로컬 캐시 저장 생략',e)}
  const s=document.getElementById('companyOnlineState');if(s)s.textContent=`온라인 업체 ${companies.length}개`;companyRender();syncSampleCompanySelectors(true);scheduleRenderAll();return true;
}
async function dfV68WaitCompanyDb(){for(let i=0;i<50;i++){if(companyState?.db?.Companies?.length)return true;await new Promise(r=>setTimeout(r,100))}return false}
async function dfV68OnlineBootstrap(){
  if(!dfSupabase||!dfCloudUser)return;
  try{
    // v76: 로컬 DB 로드를 기다리다 서로 멈추는 순환 의존 제거
    let count=0;
    const q=await dfSupabase.from('companies').select('id',{count:'exact',head:true});
    if(q.error)throw q.error;count=q.count||0;
    if(count>0){await dfV68PullCompanies();return}
    // v94: Supabase가 단일 원본이다. 온라인 DB가 비어 있어도 내장/로컬 DB를 자동 업로드하지 않는다.
    // 자동 bootstrap은 과거 데이터가 온라인 정본을 덮어쓰는 원인이 될 수 있으므로 명시적으로 차단한다.
    const state=document.getElementById('companyOnlineState');
    if(state){state.textContent='온라인 업체 DB 비어있음';state.className='company-online-state bad'}
    console.warn('v94: companies 테이블이 비어 있습니다. 자동 복원/업로드하지 않습니다.');
    return false;
  }catch(e){console.error('v76 online company bootstrap',e)}
}
async function dfV68SyncCompany(c){
  if(!dfSupabase||!dfCloudUser||!c?.Id)return;
  try{
    const {data,error}=await dfSupabase.from('companies').upsert(dfV68CompanyRow(c),{onConflict:'legacy_id'}).select('id').single();if(error)throw error;
    const rows=(c.Facilities||[]).filter(f=>f.Id).map(f=>dfV68FacilityRow(f,data.id));
    if(rows.length)await dfV68UpsertChunks('facilities',rows,'legacy_id');
    // v94: 시설 편집 화면에서 삭제한 시설도 온라인 DB에 동일하게 반영한다.
    // 이 함수는 사용자가 업체/시설 저장을 눌렀을 때만 호출된다.
    const currentIds=new Set(rows.map(x=>String(x.legacy_id)));
    const online=await dfSupabase.from('facilities').select('id,legacy_id').eq('company_id',data.id);
    if(online.error)throw online.error;
    const remove=(online.data||[]).filter(x=>x.legacy_id&&!currentIds.has(String(x.legacy_id))).map(x=>x.id);
    if(remove.length){const del=await dfSupabase.from('facilities').delete().in('id',remove);if(del.error)throw del.error}
    return data.id;
  }catch(e){console.error('업체 온라인 저장 실패',e);alert('업체 정보 온라인 DB 저장에 실패했습니다.\n'+(e.message||e));throw e}
}

// v94: 계약 신규 등록 시 계약 대상 업체가 companies에 없으면 온라인 업체 마스터에도 생성한다.
// 사업자번호를 최우선으로 찾고, 없을 때만 정규화된 업체명을 사용한다.
async function dfV94EnsureContractCompany(payload){
  if(!dfSupabase||!dfCloudUser)return null;
  const name=(payload.target_name||payload.requester_name||'').trim();
  const biz=(payload.target_biz_no||payload.requester_biz_no||'').trim();
  const address=(payload.target_address||payload.requester_address||'').trim();
  if(!name)return null;
  const rows=await dfV68FetchAll('companies','id,legacy_id,name,biz_no');
  const nb=dfV68Biz(biz), nn=dfV68NormName(name);
  let hit=nb?rows.find(x=>dfV68Biz(x.biz_no)===nb):null;
  if(!hit&&nn)hit=rows.find(x=>dfV68NormName(x.name)===nn);
  if(hit)return hit.id;
  const legacy=`company-web-${Date.now()}-${Math.random().toString(36).slice(2,7)}`;
  const row={legacy_id:legacy,name,address,biz_no:biz,grade:payload.grade||'',cycle:'',measurement_items:[],measurement_history:[],tracking:{},active:true,extra_data:{CreatedFrom:'contract',CreatedAt:new Date().toISOString()}};
  const ins=await dfSupabase.from('companies').insert(row).select('id').single();
  if(ins.error)throw ins.error;
  return ins.data?.id||null;
}

function dfV68Date(v){if(!v)return null;const d=new Date(String(v)+'T00:00:00');return Number.isNaN(d.getTime())?null:d}
function dfV68ContractStatus(r){
  const now=new Date();now.setHours(0,0,0,0);const st=dfV68Date(r.start_date),en=dfV68Date(r.end_date);const src=String(r.source_status||'');
  if(!['계약진행','입력완료'].includes(src))return {key:'ended',label:src||'종결'};
  if(st&&st>now)return {key:'future',label:'계약예정'};
  if(en&&en<now)return {key:'renew',label:'재계약 필요'};
  if(en){const days=Math.ceil((en-now)/86400000);if(days<=60)return {key:'expiring',label:`만료예정 D-${Math.max(0,days)}`}}
  return {key:'active',label:'계약중'};
}
function dfV68Money(v){return `${Number(v||0).toLocaleString('ko-KR')}원`}
function dfV68Esc(v){return String(v??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]))}
function dfV68Period(r){return `${r.start_date||'-'} ~ ${r.end_date||'-'}`}
async function dfV68LoadContracts(force=false){
  if(!dfV68IsAdmin())return;
  const badge=document.getElementById('contractOnlineBadge');
  if(!dfSupabase){if(badge){badge.textContent='온라인 DB 미연결';badge.className='bad'};return}
  if(dfV68ContractState.loaded&&!force){dfV68RenderContracts();return}
  try{
    if(badge){badge.textContent='Supabase 불러오는 중';badge.className=''}
    dfV68ContractState.rows=await dfV68FetchAll('contracts','*','contract_date');dfV68ContractState.loaded=true;
    if(badge){badge.textContent=`Supabase · ${dfV68ContractState.rows.length}건`;badge.className='ok'}
    dfV68RenderContracts();
  }catch(e){
    console.error(e);if(badge){badge.textContent='계약 DB 준비 필요';badge.className='bad'}
    const body=document.getElementById('contractTbody');if(body)body.innerHTML=`<tr><td colspan="9" class="contract-empty">계약 테이블을 불러오지 못했습니다.<br><strong>supabase_v68_contracts_import.sql</strong>을 Supabase SQL Editor에서 한 번 실행한 뒤 [온라인 새로고침]을 눌러주세요.<br><small>${dfV68Esc(e.message||e)}</small></td></tr>`;
  }
}
function dfV68FilteredContracts(){
  const q=dfV68ContractState.search.trim().toLowerCase();
  return dfV68ContractState.rows.filter(r=>{
    if(dfV68ContractState.year!=='all'){
      const y=Number(dfV68ContractState.year), yStart=new Date(y,0,1), yEnd=new Date(y,11,31,23,59,59);
      const st=dfV68Date(r.start_date||r.contract_date), en=dfV68Date(r.end_date||r.contract_date);
      if(st&&st>yEnd)return false;
      if(en&&en<yStart)return false;
      if(!st&&!en&&String(r.source_year)!==String(y))return false;
    }
    const st=dfV68ContractStatus(r);if(dfV68ContractState.status!=='all'){
      if(dfV68ContractState.status==='ended'){if(st.key!=='ended')return false}else if(st.key!==dfV68ContractState.status)return false;
    }
    if(q && ![r.contract_no,r.contract_name,r.requester_name,r.target_name,r.requester_address,r.target_address].some(v=>String(v||'').toLowerCase().includes(q)))return false;
    return true;
  }).sort((a,b)=>String(b.contract_date||'').localeCompare(String(a.contract_date||'')));
}
function dfV69InferAmountBasis(r){
  const saved=r?.extra_data?.amount_basis;
  if(saved)return saved;
  const s=`${r?.contract_name||''} ${r?.source_half||''}`.replace(/\s+/g,' ');
  if(/분기|분기별|연\s*4회|4회/.test(s))return '분기';
  if(/상반기|하반기|반기|연\s*2회|2회/.test(s))return '반기';
  if(/연간|1년|년간|연\s*1회/.test(s))return '1년';
  const st=dfV68Date(r?.start_date), en=dfV68Date(r?.end_date);
  if(st&&en){
    const days=(en-st)/86400000;
    if(days>=300)return '1년';
    if(days>=120&&days<=220)return '반기';
    if(days>=60&&days<=120)return '분기';
  }
  return '확인필요';
}
function dfV69CsvCell(v){return '"'+String(v??'').replace(/"/g,'""')+'"'}
function dfV69ExportContractsCsv(){
  const rows=dfV68FilteredContracts();
  const headers=['관리상태','계약번호','의뢰기관','측정대상사업장','계약명','계약일','과업시작','과업종료','금액기준','계약금액','사업장종별','관할행정기관'];
  const lines=[headers.map(dfV69CsvCell).join(',')];
  rows.forEach(r=>lines.push([dfV68ContractStatus(r).label,r.contract_no,r.requester_name,r.target_name,r.contract_name,r.contract_date,r.start_date,r.end_date,dfV69InferAmountBasis(r),Number(r.amount||0),r.grade,r.authority].map(dfV69CsvCell).join(',')));
  const blob=new Blob(['\ufeff'+lines.join('\r\n')],{type:'text/csv;charset=utf-8'});
  const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`드림포이엔_계약체결누적현황_${dfV68ContractState.year}_${new Date().toISOString().slice(0,10)}.csv`;a.click();URL.revokeObjectURL(a.href);
}
function dfV69PrintContractSummary(r){
  const st=dfV68ContractStatus(r), basis=dfV69InferAmountBasis(r), esc=dfV68Esc;
  const w=window.open('','_blank','width=900,height=1000');
  if(!w){alert('팝업이 차단되었습니다. 브라우저 팝업 허용 후 다시 시도해주세요.');return}
  w.document.write(`<!doctype html><html lang="ko"><head><meta charset="utf-8"><title>계약정보</title><style>body{font-family:Arial,"Malgun Gothic",sans-serif;margin:28px;color:#222}h1{font-size:22px}table{width:100%;border-collapse:collapse;font-size:12px}th,td{border:1px solid #bbb;padding:8px;text-align:left}th{width:18%;background:#f4f5f6}@media print{body{margin:12mm}}</style></head><body><h1>측정대행 계약정보 요약</h1><table>${[['관리상태',st.label],['계약번호',r.contract_no],['계약명',r.contract_name],['의뢰기관',r.requester_name],['측정대상사업장',r.target_name],['계약일',r.contract_date],['과업기간',dfV68Period(r)],['금액기준',basis],['계약금액',dfV68Money(r.amount)],['사업장종별',r.grade],['관할행정기관',r.authority],['의뢰기관 주소',r.requester_address],['사업장 주소',r.target_address],['원본상태',r.source_status]].map(x=>`<tr><th>${esc(x[0])}</th><td>${esc(x[1])}</td></tr>`).join('')}</table><script>window.onload=()=>setTimeout(()=>window.print(),150)<\/script></body></html>`);
  w.document.close();
}
async function dfV69SaveAmountBasis(r,basis){
  if(!dfSupabase||!dfV68IsAdmin())return;
  const extra={...(r.extra_data||{}),amount_basis:basis};
  const {error}=await dfSupabase.from('contracts').update({extra_data:extra}).eq('id',r.id);
  if(error){alert('금액기준 저장 실패\n'+error.message);return}
  r.extra_data=extra;dfV68RenderContracts();dfV68RenderContractDetail();
}
function dfV70ContractStatusValue(r){
  const s=String(r?.source_status||'계약진행');
  if(s==='입력완료')return '입력완료';
  if(['계약종결','계약중지','계약취소','중도해지','임시저장'].includes(s))return s;
  return '계약진행';
}
function dfV70CustomFields(r){
  const x=r?.extra_data?.custom_fields;
  return (x&&typeof x==='object'&&!Array.isArray(x))?x:{};
}
function dfV70ContractFormValue(v){return dfV68Esc(v??'')}
function dfV70ContractNo(){
  const d=new Date(),p=n=>String(n).padStart(2,'0');
  return `DFEN-WEB-${d.getFullYear()}${p(d.getMonth()+1)}${p(d.getDate())}-${p(d.getHours())}${p(d.getMinutes())}${p(d.getSeconds())}`;
}
function dfV70ContractForm(r=null){
  const n=r||{};
  const extra=n.extra_data||{};
  const basis=dfV69InferAmountBasis(n);
  const custom=dfV70CustomFields(n);
  const rows=Object.entries(custom).map(([k,v])=>`<div class="contract-custom-row"><input data-contract-custom-key value="${dfV70ContractFormValue(k)}" placeholder="항목명"><input data-contract-custom-value value="${dfV70ContractFormValue(v)}" placeholder="내용"><button type="button" class="contract-custom-remove">삭제</button></div>`).join('');
  return `<div class="contract-editor-grid">
    <label>계약번호<input id="ct_contract_no" value="${dfV70ContractFormValue(n.contract_no||'')}" placeholder="비우면 자동생성"></label>
    <label>계약상태<select id="ct_source_status">
      ${[['계약진행','진행중'],['입력완료','입력완료'],['계약종결','종결'],['계약중지','중지'],['계약취소','취소'],['중도해지','중도해지'],['임시저장','임시저장']].map(([v,l])=>`<option value="${v}" ${dfV70ContractStatusValue(n)===v?'selected':''}>${l}</option>`).join('')}
    </select></label>
    <label class="span-2">계약명<input id="ct_contract_name" value="${dfV70ContractFormValue(n.contract_name||'')}"></label>
    <label>측정분야<input id="ct_field" value="${dfV70ContractFormValue(n.field||'대기')}"></label>
    <label>사업장 종<input id="ct_grade" value="${dfV70ContractFormValue(n.grade||'')}"></label>
    <label>계약일<input id="ct_contract_date" type="date" value="${dfV70ContractFormValue(n.contract_date||'')}"></label>
    <label>금액기준<select id="ct_amount_basis">${['1년','반기','분기','월','건별','기타','확인필요'].map(v=>`<option ${basis===v?'selected':''}>${v}</option>`).join('')}</select></label>
    <label>과업 시작일<input id="ct_start_date" type="date" value="${dfV70ContractFormValue(n.start_date||'')}"></label>
    <label>과업 종료일<input id="ct_end_date" type="date" value="${dfV70ContractFormValue(n.end_date||'')}"></label>
    <label>계약금액<input id="ct_amount" type="number" min="0" step="1" value="${Number(n.amount||0)}"></label>
    <label>관할행정기관<input id="ct_authority" value="${dfV70ContractFormValue(n.authority||'')}"></label>

    <label>의뢰기관명<input id="ct_requester_name" value="${dfV70ContractFormValue(n.requester_name||'')}"></label>
    <label>의뢰기관 사업자번호<input id="ct_requester_biz_no" value="${dfV70ContractFormValue(n.requester_biz_no||'')}"></label>
    <label class="span-2">의뢰기관 주소<input id="ct_requester_address" value="${dfV70ContractFormValue(n.requester_address||'')}"></label>

    <label>측정대상 사업장<input id="ct_target_name" value="${dfV70ContractFormValue(n.target_name||'')}"></label>
    <label>사업장 사업자번호<input id="ct_target_biz_no" value="${dfV70ContractFormValue(n.target_biz_no||'')}"></label>
    <label class="span-2">사업장 주소<input id="ct_target_address" value="${dfV70ContractFormValue(n.target_address||'')}"></label>

    <label>업체 담당자<input id="ct_contact_name" value="${dfV70ContractFormValue(extra.contact_name||'')}"></label>
    <label>담당자 연락처<input id="ct_contact_phone" value="${dfV70ContractFormValue(extra.contact_phone||'')}"></label>
    <label class="span-2">계약 메모<textarea id="ct_memo">${dfV70ContractFormValue(extra.memo||'')}</textarea></label>
  </div>
  <div class="contract-editor-section"><h3>추가 항목</h3>
    <div class="contract-custom-list" id="contractCustomList">${rows}</div>
    <button type="button" class="company-btn secondary" id="contractCustomAdd">+ 항목 추가</button>
    <div class="contract-doc-note">앞으로 계약에 새 정보가 생기면 항목명과 내용을 자유롭게 추가할 수 있습니다.</div>
  </div>`;
}
function dfV70BindCustomRows(){
  const box=document.getElementById('contractCustomList');if(!box)return;
  box.querySelectorAll('.contract-custom-remove').forEach(b=>b.onclick=()=>b.closest('.contract-custom-row')?.remove());
  document.getElementById('contractCustomAdd')?.addEventListener('click',()=>{
    box.insertAdjacentHTML('beforeend','<div class="contract-custom-row"><input data-contract-custom-key placeholder="항목명"><input data-contract-custom-value placeholder="내용"><button type="button" class="contract-custom-remove">삭제</button></div>');
    dfV70BindCustomRows();
  });
}
function dfV70CollectContractForm(existing=null){
  const val=id=>document.getElementById(id)?.value?.trim()||'';
  const contractDate=val('ct_contract_date');
  const sourceYear=contractDate?Number(contractDate.slice(0,4)):(existing?.source_year||new Date().getFullYear());
  const month=contractDate?Number(contractDate.slice(5,7)):new Date().getMonth()+1;
  const custom={};
  document.querySelectorAll('#contractCustomList .contract-custom-row').forEach(row=>{
    const k=row.querySelector('[data-contract-custom-key]')?.value.trim(),v=row.querySelector('[data-contract-custom-value]')?.value.trim();
    if(k)custom[k]=v;
  });
  const extra={...(existing?.extra_data||{}),amount_basis:val('ct_amount_basis')||'확인필요',contact_name:val('ct_contact_name'),contact_phone:val('ct_contact_phone'),memo:val('ct_memo'),custom_fields:custom};
  return {
    contract_no:val('ct_contract_no')||dfV70ContractNo(),
    contract_name:val('ct_contract_name'),
    field:val('ct_field'),
    grade:val('ct_grade'),
    requester_name:val('ct_requester_name'),
    requester_address:val('ct_requester_address'),
    requester_biz_no:val('ct_requester_biz_no'),
    target_name:val('ct_target_name'),
    target_address:val('ct_target_address'),
    target_biz_no:val('ct_target_biz_no'),
    contract_date:contractDate||null,start_date:val('ct_start_date')||null,end_date:val('ct_end_date')||null,
    amount:Number(document.getElementById('ct_amount')?.value||0),
    source_status:val('ct_source_status')||'계약진행',
    authority:val('ct_authority'),source_year:sourceYear,source_half:month<=6?'상반기':'하반기',
    source_file:existing?.source_file||'웹 직접등록',registered_date:existing?.registered_date||new Date().toISOString().slice(0,10),
    extra_data:extra
  };
}
async function dfV70SaveContract(existing=null){
  if(!dfSupabase||!dfV68IsAdmin())return;
  const payload=dfV70CollectContractForm(existing);
  if(!payload.requester_name&&!payload.target_name){alert('의뢰기관명 또는 측정대상 사업장 중 하나는 입력해주세요.');return}
  try{
    let q;
    if(existing?.id) q=dfSupabase.from('contracts').update(payload).eq('id',existing.id).select('*').single();
    else q=dfSupabase.from('contracts').insert(payload).select('*').single();
    const {data,error}=await q;if(error)throw error;
    // v94: 신규/수정 계약의 측정대상 업체를 업체 마스터와 연결한다.
    await dfV94EnsureContractCompany(payload);
    dfV68ContractState.loaded=false;
    dfV68ContractState.selectedId=data.id;
    await dfV68LoadContracts(true);
    await dfV68PullCompanies();
    await dfV68RefreshCurrentContractCompaniesOnline();
    dfV69CloseContractModal();
    alert(existing?'계약내용을 수정했습니다.':'새 계약을 추가했습니다.');
  }catch(e){alert('계약 저장 실패\n'+(e.message||e))}
}
async function dfV70DeleteContract(r){
  if(!r?.id||!dfV68IsAdmin())return;
  if(!confirm(`"${r.requester_name||r.target_name||r.contract_no}" 계약을 삭제하시겠습니까?\n삭제 후에는 계약관리에서 보이지 않습니다.`))return;
  const {error}=await dfSupabase.from('contracts').delete().eq('id',r.id);
  if(error){alert('계약 삭제 실패\n'+error.message);return}
  dfV68ContractState.selectedId=null;dfV68ContractState.loaded=false;
  await dfV68LoadContracts(true);await dfV68RefreshCurrentContractCompaniesOnline();dfV69CloseContractModal();
}
function dfV70OpenContractEditor(r=null){
  const modal=document.getElementById('contractModal'),body=document.getElementById('contractModalBody');if(!modal||!body)return;
  document.getElementById('contractModalTitle').textContent=r?'계약 수정':'계약 추가';
  document.getElementById('contractModalSub').textContent=r?`${r.contract_no||''} · ${r.requester_name||r.target_name||''}`:'새 계약내용을 입력하세요.';
  body.innerHTML=`${dfV70ContractForm(r)}
  <div class="contract-editor-actions">
    <div>${r?'<button type="button" class="company-btn danger" id="contractDeleteBtn">계약 삭제</button>':''}</div>
    <div class="right"><button type="button" class="company-btn secondary" id="contractEditCancel">취소</button><button type="button" class="company-btn primary" id="contractEditSave">저장</button></div>
  </div>`;
  dfV70BindCustomRows();
  document.getElementById('contractEditCancel').onclick=dfV69CloseContractModal;
  document.getElementById('contractEditSave').onclick=()=>dfV70SaveContract(r);
  document.getElementById('contractDeleteBtn')?.addEventListener('click',()=>dfV70DeleteContract(r));
  modal.hidden=false;modal.style.display='flex';
}
function dfV68RenderContracts(){
  const all=dfV68ContractState.rows, list=dfV68FilteredContracts();
  const yearOnly=all.filter(r=>{
    if(dfV68ContractState.year==='all')return true;
    const y=Number(dfV68ContractState.year),a=new Date(y,0,1),b=new Date(y,11,31,23,59,59);
    const st=dfV68Date(r.start_date||r.contract_date),en=dfV68Date(r.end_date||r.contract_date);
    if(st&&st>b)return false;if(en&&en<a)return false;
    return st||en?true:String(r.source_year)===String(y);
  });
  const stAll=yearOnly.map(dfV68ContractStatus);
  document.getElementById('contractCountAll').textContent=yearOnly.length;
  document.getElementById('contractCountActive').textContent=stAll.filter(x=>x.key==='active').length;
  document.getElementById('contractCountExpiring').textContent=stAll.filter(x=>x.key==='expiring').length;
  document.getElementById('contractCountRenew').textContent=stAll.filter(x=>x.key==='renew').length;
  const endedEl=document.getElementById('contractCountEnded');if(endedEl)endedEl.textContent=stAll.filter(x=>x.key==='ended').length;
  const yearRows=yearOnly;
  document.getElementById('contractAmountYear').textContent=dfV68Money(yearRows.reduce((s,r)=>s+Number(r.amount||0),0));
  document.getElementById('contractPosition').textContent=`표시 ${list.length}건 / 전체 ${all.length}건`;
  const body=document.getElementById('contractTbody');if(!body)return;
  body.innerHTML=list.map(r=>{const st=dfV68ContractStatus(r);return `<tr data-contract-id="${dfV68Esc(r.id)}" class="${dfV68ContractState.selectedId===r.id?'selected':''}">
    <td><span class="contract-status ${st.key}">${dfV68Esc(st.label)}</span></td><td>${dfV68Esc(r.contract_no)}</td>
    <td><strong>${dfV68Esc(r.requester_name)}</strong></td><td><div class="contract-target-clamp" title="${dfV68Esc(r.target_name)}">${dfV68Esc(r.target_name)}</div></td>
    <td><div class="contract-name-clamp" title="${dfV68Esc(r.contract_name)}">${dfV68Esc(r.contract_name)}</div></td><td>${dfV68Esc(r.contract_date)}</td>
    <td>${dfV68Esc(dfV68Period(r))}</td><td>${dfV68Esc(dfV69InferAmountBasis(r))}</td><td class="contract-money">${dfV68Esc(dfV68Money(r.amount))}</td></tr>`}).join('')||'<tr><td colspan="9" class="contract-empty">조건에 맞는 계약이 없습니다.</td></tr>';
  body.querySelectorAll('tr[data-contract-id]').forEach(tr=>tr.onclick=()=>{dfV68ContractState.selectedId=tr.dataset.contractId;const r=dfV68ContractState.rows.find(x=>String(x.id)===String(tr.dataset.contractId));dfV70OpenContractEditor(r)});
}
function dfV68RenderContractDetail(){
  const r=dfV68ContractState.rows.find(x=>String(x.id)===String(dfV68ContractState.selectedId));if(r)dfV70OpenContractEditor(r);
}
function dfV69CloseContractModal(){
  const m=document.getElementById('contractModal');if(!m)return;
  m.hidden=true;m.style.display='none';
  const b=document.getElementById('contractModalBody');if(b)b.innerHTML='';
}


function dfV68InitContractUi(){
  if(window.__dfContractUiBound)return;
  window.__dfContractUiBound=true;
  document.getElementById('contractYear')?.addEventListener('change',e=>{dfV68ContractState.year=e.target.value;dfV68RenderContracts()});
  document.getElementById('contractStatus')?.addEventListener('change',e=>{
    dfV68ContractState.status=e.target.value;
    document.querySelectorAll('.v86-contract-filter').forEach(x=>x.classList.toggle('active',x.dataset.contractFilter===dfV68ContractState.status));
    dfV68RenderContracts();
  });
  document.getElementById('contractSearch')?.addEventListener('input',e=>{dfV68ContractState.search=e.target.value;dfV68RenderContracts()});
  document.getElementById('contractRefresh')?.addEventListener('click',()=>dfV68LoadContracts(true));
  document.querySelectorAll('.v86-contract-filter').forEach(btn=>btn.addEventListener('click',()=>{
    dfV68ContractState.status=btn.dataset.contractFilter||'all';
    const sel=document.getElementById('contractStatus');if(sel)sel.value=dfV68ContractState.status;
    document.querySelectorAll('.v86-contract-filter').forEach(x=>x.classList.toggle('active',x===btn));
    dfV68RenderContracts();
  }));
  document.getElementById('contractAddBtn')?.addEventListener('click',()=>dfV70OpenContractEditor(null));
  document.getElementById('contractExportCsv')?.addEventListener('click',dfV69ExportContractsCsv);
  document.getElementById('contractModalClose')?.addEventListener('click',e=>{e.preventDefault();e.stopPropagation();dfV69CloseContractModal()});
  document.getElementById('contractModal')?.addEventListener('click',e=>{if(e.target?.id==='contractModal')dfV69CloseContractModal()});
}

document.addEventListener('DOMContentLoaded',()=>{dfV68LoadCurrentContractCompanies();dfV68InitContractUi()});

// v72: 과거 capture 라우터/동적 팝업 때문에 클릭이 삼켜지는 경우에도 계약 팝업 닫기 보장
document.addEventListener('click',e=>{
  const close=e.target.closest?.('#contractModalClose,#contractEditCancel,[data-close-contract-modal]');
  if(close){
    e.preventDefault();
    e.stopPropagation();
    dfV69CloseContractModal();
  }
},true);
document.addEventListener('keydown',e=>{
  if(e.key==='Escape'&&!document.getElementById('contractModal')?.hidden)dfV69CloseContractModal();
});


// v96.2: completed schedule dates shown in company monthly status; explicit schedule save result alert.

// v102: Excel date raw serial first, LAB explicit per-record save, readonly sample-linked Vs, unified oxygen-correction final result.

// ==========================================================
// v111 드림포이엔 자료실 + 시료채취/LAB 온라인 동기화
// 동일 시료접수번호 1개 = 측정자료 + 분석자료 1세트
// ==========================================================
const DF_REPOSITORY_TABLE='dreampoen_repository';
let dfRepositoryRows=[];
let dfRepositorySyncing=false;
let dfRepositoryLastSync='';

function dfRepoEsc(v){return String(v??'').replace(/[&<>'"]/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[m]))}
function dfRepoReceipt(data){return String(data?.fields?.receiptNo||'').trim()}
function dfRepoDate(data){return String(data?.fields?.measureDate||'').slice(0,10)}
function dfRepoCompany(data){return String(data?.fields?.company||'').trim()}
function dfRepoFacility(data){return String(data?.fields?.facility||'').trim()}
function dfRepoTypeName(t){return t==='dust'?'먼지':t==='metal'?'중금속':t==='combo'?'먼지+중금속':String(t||'')}
function dfRepoTs(v){const t=Date.parse(v||'');return Number.isFinite(t)?t:0}
function dfRepoStatus(msg,bad=false){const el=document.getElementById('dfRepositoryStatus');if(el){el.textContent=msg;el.style.color=bad?'#a53434':''}}
function dfRepoDownload(name,obj){const blob=new Blob([JSON.stringify(obj,null,2)],{type:'application/json;charset=utf-8'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name.replace(/[\\/:*?"<>|]+/g,'_');document.body.appendChild(a);a.click();setTimeout(()=>{URL.revokeObjectURL(a.href);a.remove()},100)}
function dfRepoFolderName(row){const d=String(row.measure_date||'').replace(/-/g,'');return `${row.receipt_no||'접수번호미입력'} ${row.company_name||''}`.trim()}

async function dfRepoFetch(){
  if(!dfSupabase||!dfCloudUser)return [];
  const {data,error}=await dfSupabase.from(DF_REPOSITORY_TABLE).select('*').order('measure_date',{ascending:false}).order('updated_at',{ascending:false});
  if(error)throw error;
  return data||[];
}

async function dfRepoUpsertMeasurement(record,{quiet=false}={}){
  if(!dfSupabase||!dfCloudUser||!record?.data)return false;
  const receipt=dfRepoReceipt(record.data);
  if(!receipt){if(!quiet)alert('온라인 자료실 저장은 시료접수번호가 필요합니다.\n접수번호 입력 후 다시 저장해주세요.');return false}
  const payload={
    receipt_no:receipt,
    measure_date:dfRepoDate(record.data)||null,
    company_name:dfRepoCompany(record.data)||null,
    facility_name:dfRepoFacility(record.data)||null,
    record_type:record.data.recordType||null,
    measurement_data:record,
    measurement_updated_at:record.updatedAt||new Date().toISOString(),
    updated_by:dfCloudUser.id,
    updated_at:new Date().toISOString()
  };
  const {error}=await dfSupabase.from(DF_REPOSITORY_TABLE).upsert(payload,{onConflict:'receipt_no'});
  if(error)throw error;
  return true;
}

async function dfRepoUpsertAnalysis(recordId){
  if(!dfSupabase||!dfCloudUser||!recordId)return false;
  const rec=analysisSavedRecords().find(r=>r.id===recordId);
  if(!rec)return false;
  const receipt=dfRepoReceipt(rec.data);
  if(!receipt)throw Error('시료접수번호가 없어 LAB 자료를 온라인 저장할 수 없습니다.');
  const vals=analysisInputCache()[recordId]||{};
  const now=new Date().toISOString();
  const payload={
    receipt_no:receipt,
    measure_date:dfRepoDate(rec.data)||null,
    company_name:dfRepoCompany(rec.data)||null,
    facility_name:dfRepoFacility(rec.data)||null,
    record_type:rec.data.recordType||null,
    analysis_data:{recordId,values:vals,savedAt:now},
    analysis_updated_at:now,
    updated_by:dfCloudUser.id,
    updated_at:now
  };
  const {error}=await dfSupabase.from(DF_REPOSITORY_TABLE).upsert(payload,{onConflict:'receipt_no'});
  if(error)throw error;
  return true;
}

function dfRepoMergeCloud(rows){
  const local=readRecordStore();
  const byReceipt=new Map();
  local.forEach((r,i)=>{const no=dfRepoReceipt(r?.data);if(no)byReceipt.set(no,{r,i})});
  let changed=false;
  const lab=analysisInputCache(); let labChanged=false;
  rows.forEach(row=>{
    const cloud=row.measurement_data;
    if(cloud?.data){
      const no=String(row.receipt_no||dfRepoReceipt(cloud.data)).trim();
      const hit=byReceipt.get(no);
      if(!hit){local.push(cloud);byReceipt.set(no,{r:cloud,i:local.length-1});changed=true}
      else if(dfRepoTs(cloud.updatedAt)>=dfRepoTs(hit.r.updatedAt)){
        local[hit.i]=cloud;byReceipt.set(no,{r:cloud,i:hit.i});changed=true;
      }
    }
    const a=row.analysis_data;
    if(a?.recordId&&a?.values){
      const current=lab[a.recordId];
      if(!current || dfRepoTs(a.savedAt)>=dfRepoTs(current?._localUpdatedAt||current?._cloudSavedAt)){
        lab[a.recordId]={...a.values,_cloudSavedAt:a.savedAt||row.analysis_updated_at||row.updated_at};labChanged=true;
      }
    }
  });
  if(changed)writeRecordStore(local);
  if(labChanged)localStorage.setItem(ANALYSIS_INPUT_CACHE_KEY,JSON.stringify(lab));
  return {changed,labChanged};
}

async function dfRepoPushLocalNewer(rows){
  const cloudByReceipt=new Map(rows.map(r=>[String(r.receipt_no||''),r]));
  const local=readRecordStore();
  for(const rec of local){
    const no=dfRepoReceipt(rec?.data);if(!no)continue;
    const cloud=cloudByReceipt.get(no);
    const localTs=dfRepoTs(rec.updatedAt||rec.createdAt);
    const cloudTs=dfRepoTs(cloud?.measurement_updated_at||cloud?.updated_at);
    if(!cloud || localTs>cloudTs){
      try{await dfRepoUpsertMeasurement(rec,{quiet:true})}catch(e){console.warn('로컬 기록 온라인 업로드 실패',no,e)}
    }
  }
}

async function dfRepositorySync({quiet=false}={}){
  if(dfRepositorySyncing||!dfSupabase||!dfCloudUser)return false;
  dfRepositorySyncing=true;
  if(!quiet)dfRepoStatus('온라인 자료 동기화 중...');
  try{
    let rows=await dfRepoFetch();
    await dfRepoPushLocalNewer(rows);
    rows=await dfRepoFetch();
    dfRepoMergeCloud(rows);
    dfRepositoryRows=rows;
    dfRepositoryLastSync=new Date().toISOString();
    refreshAnalysisRecordList?.(true);
    renderTodayRecords?.();
    dfRepositoryRender();
    if(!quiet)dfRepoStatus('온라인 동기화 완료');
    return true;
  }catch(e){
    console.error('자료실 동기화 오류',e);if(!quiet)dfRepoStatus('동기화 실패: '+e.message,true);return false;
  }finally{dfRepositorySyncing=false}
}
window.dfRepositorySync=dfRepositorySync;

function dfRepositoryFiltered(){
  const q=String(document.getElementById('dfRepositorySearch')?.value||'').trim().toLowerCase();
  const date=String(document.getElementById('dfRepositoryDate')?.value||'');
  return (dfRepositoryRows||[]).filter(r=>{
    if(date&&String(r.measure_date||'')!==date)return false;
    if(q){const hay=[r.receipt_no,r.company_name,r.facility_name].join(' ').toLowerCase();if(!hay.includes(q))return false}
    return true;
  });
}
async function dfRepositoryDownloadMeasurementExcel(receipt){
  const row=dfRepositoryRows.find(r=>r.receipt_no===receipt),rec=row?.measurement_data;
  if(!rec?.data)return alert('다운로드할 시료채취기록이 없습니다.');
  // 자료실에서 바로 Excel을 받아도 현재 작성 중 화면은 그대로 복원한다.
  const snapshot={
    data:clone(collect()),currentRecordId,recordType,comboParticleMode,
    comboParticleStates:clone(comboParticleStates),workingStates:clone(workingStates),
    recordTypeInitialized:clone(recordTypeInitialized)
  };
  try{
    currentRecordId=rec.id||null;
    apply(clone(rec.data));
    await exactTemplateExcelExport();
    dfRepoStatus(`${receipt} 시료채취기록지 Excel 다운로드 완료`);
  }catch(e){
    console.error('자료실 Excel 다운로드 실패',e);
    alert(`시료채취기록지 Excel 다운로드에 실패했습니다.\n${e?.message||e}`);
  }finally{
    currentRecordId=snapshot.currentRecordId;
    recordType=snapshot.recordType;
    comboParticleMode=snapshot.comboParticleMode;
    comboParticleStates=clone(snapshot.comboParticleStates);
    workingStates=clone(snapshot.workingStates);
    recordTypeInitialized=clone(snapshot.recordTypeInitialized);
    apply(clone(snapshot.data));
    renderTodayRecords();
  }
}

function dfRepositoryRender(){
  const list=document.getElementById('dfRepositoryList');if(!list)return;
  const rows=dfRepositoryFiltered();
  const count=document.getElementById('dfRepositoryCount');if(count)count.textContent=rows.length;
  const tm=document.getElementById('dfRepositorySyncTime');if(tm)tm.textContent=dfRepositoryLastSync?`동기화 ${new Date(dfRepositoryLastSync).toLocaleString('ko-KR')}`:'아직 동기화 전';
  if(!rows.length){list.innerHTML='<div class="df-repository-empty">조건에 맞는 저장자료가 없습니다.</div>';return}
  const groups=new Map();rows.forEach(r=>{const d=String(r.measure_date||'날짜 미입력');if(!groups.has(d))groups.set(d,[]);groups.get(d).push(r)});
  list.innerHTML=[...groups.entries()].map(([date,items])=>`<section class="df-repository-date-group"><h3 class="df-repository-date-title">${dfRepoEsc(date)}</h3>${items.map(r=>{
    const hasM=!!r.measurement_data,hasA=!!r.analysis_data;
    const mtime=r.measurement_updated_at?new Date(r.measurement_updated_at).toLocaleString('ko-KR'):'-';
    const atime=r.analysis_updated_at?new Date(r.analysis_updated_at).toLocaleString('ko-KR'):'-';
    return `<article class="df-repository-folder" data-repo-receipt="${dfRepoEsc(r.receipt_no)}"><div class="df-repository-folder-head"><div><strong>📁 ${dfRepoEsc([dfRepoFolderName(r),r.facility_name||''].filter(Boolean).join(' '))}</strong><br><small>${dfRepoEsc(dfRepoTypeName(r.record_type))}</small></div><small>${hasM&&hasA?'측정 + 분석 완료':hasM?'분석 대기':'측정자료 없음'}</small></div><div class="df-repository-files">
      <div class="df-repository-file ${hasM?'':'missing'}"><div class="df-repository-file-icon">측정</div><div class="df-repository-file-main"><b>(측정) 시료채취기록 <span class="df-repository-badge ${hasM?'':'missing'}">${hasM?'저장됨':'없음'}</span></b><small>${dfRepoEsc(mtime)}</small></div><div class="df-repository-file-actions">${hasM?`<button class="primary" data-repo-open-measure="${dfRepoEsc(r.receipt_no)}">열기</button><button data-repo-down-measure="${dfRepoEsc(r.receipt_no)}">Excel 다운로드</button>`:''}</div></div>
      <div class="df-repository-file analysis ${hasA?'':'missing'}"><div class="df-repository-file-icon">분석</div><div class="df-repository-file-main"><b>(분석) LAB 자료 <span class="df-repository-badge ${hasA?'':'missing'}">${hasA?'저장됨':'대기'}</span></b><small>${hasA?dfRepoEsc(atime):'LAB에서 같은 접수번호를 열어 저장하세요.'}</small></div><div class="df-repository-file-actions">${hasM?`<button class="primary" data-repo-open-analysis="${dfRepoEsc(r.receipt_no)}">${hasA?'열기':'분석 입력'}</button>`:''}${hasA?`<button data-repo-down-analysis="${dfRepoEsc(r.receipt_no)}">인쇄 / PDF</button>`:''}<button data-repo-down-all="${dfRepoEsc(r.receipt_no)}">한파일 백업</button></div></div>
    </div></article>`}).join('')}</section>`).join('');
  list.querySelectorAll('[data-repo-open-measure]').forEach(b=>b.onclick=()=>dfRepositoryOpenMeasurement(b.dataset.repoOpenMeasure));
  list.querySelectorAll('[data-repo-open-analysis]').forEach(b=>b.onclick=()=>dfRepositoryOpenAnalysis(b.dataset.repoOpenAnalysis));
  list.querySelectorAll('[data-repo-down-measure]').forEach(b=>b.onclick=()=>dfRepositoryDownloadMeasurementExcel(b.dataset.repoDownMeasure));
  list.querySelectorAll('[data-repo-down-analysis]').forEach(b=>b.onclick=()=>dfRepositoryPrintAnalysis(b.dataset.repoDownAnalysis));
  list.querySelectorAll('[data-repo-down-all]').forEach(b=>b.onclick=()=>{const r=dfRepositoryRows.find(x=>x.receipt_no===b.dataset.repoDownAll);if(r)dfRepoDownload(`${dfRepoFolderName(r)}_전체백업.json`,{receiptNo:r.receipt_no,measureDate:r.measure_date,company:r.company_name,facility:r.facility_name,measurement:r.measurement_data,analysis:r.analysis_data,exportedAt:new Date().toISOString()})});
}

async function dfRepositoryOpen(){
  dfRepoStatus('온라인 자료 확인 중...');
  await dfRepositorySync({quiet:true});
  dfRepoStatus('온라인 자료실 연결됨');
  const backup=document.getElementById('dfRepositoryBackup');if(backup)backup.hidden=dfCloudProfile?.role!=='admin';
  dfRepositoryRender();
}
window.dfRepositoryOpen=dfRepositoryOpen;

function dfRepositoryOpenMeasurement(receipt){
  const row=dfRepositoryRows.find(r=>r.receipt_no===receipt);const rec=row?.measurement_data;if(!rec?.id)return;
  const store=readRecordStore();const i=store.findIndex(x=>x.id===rec.id);if(i<0){store.push(rec);writeRecordStore(store)}else{store[i]=rec;writeRecordStore(store)}
  v62ShowOnly('sample');setTimeout(()=>openSavedRecord(rec.id),60);
}
function dfRepositoryOpenAnalysis(receipt){
  const row=dfRepositoryRows.find(r=>r.receipt_no===receipt);const rec=row?.measurement_data;if(!rec?.id)return;
  const store=readRecordStore();const i=store.findIndex(x=>x.id===rec.id);if(i<0){store.push(rec);writeRecordStore(store)}else{store[i]=rec;writeRecordStore(store)}
  if(row.analysis_data?.recordId&&row.analysis_data?.values){const c=analysisInputCache();c[rec.id]={...row.analysis_data.values,_cloudSavedAt:row.analysis_data.savedAt};localStorage.setItem(ANALYSIS_INPUT_CACHE_KEY,JSON.stringify(c))}
  v62ShowOnly('analysis');setTimeout(()=>{refreshAnalysisRecordList(false);const sel=document.getElementById('analysisRecordSelect');if(sel){sel.value=rec.id;const r=(sel._records||[]).find(x=>x.id===rec.id);if(r)loadAnalysisRecord(r,{preserveLab:false})}},80);
}

document.addEventListener('dreampoen:record-saved',async e=>{
  const id=e.detail?.id;if(!id||!dfSupabase||!dfCloudUser)return;
  const rec=readRecordStore().find(x=>x.id===id);if(!rec)return;
  try{await dfRepoUpsertMeasurement(rec);dfRepoStatus(`${dfRepoReceipt(rec.data)} 측정자료 온라인 저장됨`);await dfRepositorySync({quiet:true})}catch(err){console.error(err);alert('시료채취기록은 이 기기에 저장됐지만 온라인 자료실 저장에 실패했습니다.\n'+err.message)}
});

document.addEventListener('DOMContentLoaded',()=>{
  document.getElementById('dfRepositoryRefresh')?.addEventListener('click',()=>dfRepositorySync({quiet:false}));
  document.getElementById('dfRepositoryDate')?.addEventListener('change',dfRepositoryRender);
  document.getElementById('dfRepositorySearch')?.addEventListener('input',dfRepositoryRender);
  document.getElementById('dfRepositoryClear')?.addEventListener('click',()=>{const d=document.getElementById('dfRepositoryDate'),q=document.getElementById('dfRepositorySearch');if(d)d.value='';if(q)q.value='';dfRepositoryRender()});
  document.getElementById('dfRepositoryBackup')?.addEventListener('click',()=>{if(dfCloudProfile?.role!=='admin')return alert('관리자만 전체 백업을 받을 수 있습니다.');dfRepoDownload(`DREAMFOREN_자료실_전체백업_${new Date().toISOString().slice(0,10)}.json`,{version:'v112.4',exportedAt:new Date().toISOString(),rows:dfRepositoryRows})});
  // 기존 LAB 저장 버튼의 로컬 저장 동작 뒤 온라인 저장을 추가한다.
  document.getElementById('analysisSaveBtn')?.addEventListener('click',()=>setTimeout(async()=>{
    if(!analysisSelectedRecordId||!dfSupabase||!dfCloudUser)return;
    try{await dfRepoUpsertAnalysis(analysisSelectedRecordId);const rec=analysisSavedRecords().find(r=>r.id===analysisSelectedRecordId);const no=dfRepoReceipt(rec?.data);const st=document.getElementById('analysisSaveStatus');if(st){st.textContent=`${no} 온라인 저장완료`;st.classList.add('saved')}await dfRepositorySync({quiet:true})}catch(e){alert('LAB 로컬 저장은 완료됐지만 온라인 자료실 저장에 실패했습니다.\n'+e.message)}
  },80));
});


// ==========================================================
// v112 runtime stabilization
// 1) 자료실 메뉴/화면을 로그인 후에도 반복 보증
// 2) 모바일/PC: 화면 진입·포커스 복귀 시 온라인 자료 재동기화
// 3) 시료채취기록지 숫자칸을 모바일에서 일반 자판으로 입력 가능하게 함
// 4) O2/CO2 1자리, 수분 2자리 고정 표시
// ==========================================================
(function dfV112Stabilize(){
  function ensureRepoUI(){
    try{
      const nav=document.querySelector('.df-side-nav');
      if(nav && !nav.querySelector('[data-view="repository"]')){
        const b=document.createElement('button');
        b.type='button';b.className='df-nav-item';b.dataset.view='repository';b.textContent='드림포이엔 자료실';
        const sample=nav.querySelector('[data-view="sample"]');
        sample?nav.insertBefore(b,sample):nav.appendChild(b);
        // 동적으로 만들어진 버튼도 즉시 동작하도록 직접 연결
        b.addEventListener('click',()=>{try{window.v62ShowOnly?.('repository');window.dfRepositoryOpen?.()}catch(e){console.warn(e)}});
      }
      let badge=document.getElementById('dfBuildVersion');
      if(!badge && nav){badge=document.createElement('div');badge.id='dfBuildVersion';badge.textContent='ONLINE v112.9';badge.style.cssText='margin:10px 12px 2px;font-size:11px;color:#98a2b3;text-align:center';nav.appendChild(badge)}
    }catch(e){console.warn('v112 자료실 UI 보증 실패',e)}
  }

  function makeSampleInputsFreeKeyboard(){
    const root=document.getElementById('dfViewSample');if(!root)return;
    root.querySelectorAll('input[type="number"]').forEach(inp=>{
      // 계산은 기존 parseFloat/Number 로직을 그대로 사용하고, 모바일 입력 제한만 해제
      try{inp.type='text'}catch(e){}
      inp.setAttribute('inputmode','text');
      inp.dataset.numeric='free';
    });
    root.querySelectorAll('.o2val,.co2val,.moist').forEach(inp=>{inp.setAttribute('inputmode','text');});
  }
  function fixed(v,d){const n=parseFloat(String(v??'').replace(',','.'));return Number.isFinite(n)?n.toFixed(d):String(v??'')}
  function normalizeSamplingDecimals(){
    document.querySelectorAll('.o2val,.co2val').forEach(i=>{if(String(i.value).trim()!=='')i.value=fixed(i.value,1)});
    document.querySelectorAll('.moist').forEach(i=>{if(String(i.value).trim()!=='')i.value=fixed(i.value,2)});
    try{recalc?.()}catch(e){}
  }
  window.dfV112NormalizeSamplingDecimals=normalizeSamplingDecimals;

  let lastSync=0;
  async function syncNow(force=false){
    if(!window.dfRepositorySync||!window.dfCloudUser&&!dfCloudUser)return;
    const now=Date.now();if(!force&&now-lastSync<1200)return;lastSync=now;
    try{await window.dfRepositorySync({quiet:true})}catch(e){console.warn('v112 online sync',e)}
  }

  document.addEventListener('DOMContentLoaded',()=>{
    ensureRepoUI();makeSampleInputsFreeKeyboard();normalizeSamplingDecimals();
    // 동적 포인트/수분 입력 재생성에도 적용
    const sample=document.getElementById('dfViewSample');
    if(sample){new MutationObserver(()=>{makeSampleInputsFreeKeyboard()}).observe(sample,{childList:true,subtree:true})}
    document.addEventListener('focusout',e=>{
      if(e.target?.matches?.('.o2val,.co2val,.moist')) normalizeSamplingDecimals();
    },true);
    document.addEventListener('click',e=>{
      const btn=e.target.closest?.('.df-nav-item');if(!btn)return;
      if(['repository','sample','analysis'].includes(btn.dataset.view))setTimeout(()=>syncNow(true),80);
      if(btn.dataset.view==='sample')setTimeout(()=>{makeSampleInputsFreeKeyboard();normalizeSamplingDecimals()},120);
    },true);
    window.addEventListener('focus',()=>syncNow(false));
    document.addEventListener('visibilitychange',()=>{if(!document.hidden)syncNow(false)});
    // 구 버전 index/app 캐시가 섞여도 메뉴가 사라지지 않도록 한 번 더 확인
    setTimeout(ensureRepoUI,500);setTimeout(ensureRepoUI,1800);
  });

  // 저장 직전 소수점 형식 고정 — 이후 온라인 저장 payload에도 동일 값 사용
  document.addEventListener('dreampoen:record-saved',()=>setTimeout(()=>{normalizeSamplingDecimals();syncNow(true)},120));
})();


// ==========================================================
// v112.7 HOME DASHBOARD — 공지/시험법/진행률/기타게시판
// ==========================================================
const DF_HOME_POST_TABLE='dreampoen_dashboard_posts';
function dfHomeEsc(v){return String(v??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]))}
function dfHomeFormatDate(v){if(!v)return '';try{return new Date(v).toLocaleDateString('ko-KR',{month:'2-digit',day:'2-digit'})}catch(e){return String(v).slice(0,10)}}
function dfHomeRenderPosts(cat,rows){
  const map={notice:'dfHomeNotice',method:'dfHomeMethod',board:'dfHomeBoard'}, el=document.getElementById(map[cat]);if(!el)return;
  const list=(rows||[]).filter(x=>x.category===cat).slice(0,6);
  if(!list.length){el.innerHTML='<div class="df-home-empty">등록된 내용이 없습니다.</div>';return}
  el.innerHTML=list.map(x=>`<div class="df-home-post"><div class="df-home-post-main"><b>${dfHomeEsc(x.title)}</b>${x.content?`<small>${dfHomeEsc(x.content)}</small>`:''}</div><span>${dfHomeFormatDate(x.created_at)}</span>${dfCloudProfile?.role==='admin'?`<button type="button" class="df-home-del" data-home-delete="${dfHomeEsc(x.id)}" title="삭제">×</button>`:''}</div>`).join('');
}
function dfHomeRenderProgress(){
  const y=new Date().getFullYear();const yr=document.getElementById('dfHomeProgressYear');if(yr)yr.textContent=y+'년';
  let companies=[];try{companies=dfV75SourceCompanies()}catch(e){}
  const statuses=companies.map(c=>dfV82StatusFromHistory(c,y));
  const all=statuses.length,completed=statuses.filter(x=>x.key==='complete').length,
        incomplete=statuses.filter(x=>x.key==='incomplete').length,
        check=statuses.filter(x=>x.key==='check'||x.key==='unregistered').length,
        pct=all?Math.round(completed/all*100):0;
  const set=(id,v)=>{const e=document.getElementById(id);if(e)e.textContent=v};
  set('dfHomeMeasureAll',all);set('dfHomeMeasurePlanned',incomplete);set('dfHomeMeasureConfirmed',check);set('dfHomeMeasureCompleted',completed);
  set('dfHomeProgressPct',pct+'%');set('dfHomeProgressText',all?`${completed}개 업체 완료 / ${all}개 계약 진행업체`:'계약 진행업체가 없습니다.');
  const bar=document.getElementById('dfHomeProgressBar');if(bar)bar.style.width=pct+'%';
}
async function dfHomeLoad(){
  const welcome=document.getElementById('dfHomeWelcome');if(welcome)welcome.textContent=`${dfCloudProfile?.name||'사용자'}님, 오늘의 공지와 측정 진행상황입니다.`;
  dfHomeRenderProgress();
  if(!dfSupabase||!dfCloudUser){['notice','method','board'].forEach(c=>dfHomeRenderPosts(c,[]));return}
  try{
    const {data,error}=await dfSupabase.from(DF_HOME_POST_TABLE).select('id,category,title,content,created_at,created_by').order('created_at',{ascending:false}).limit(60);
    if(error)throw error;['notice','method','board'].forEach(c=>dfHomeRenderPosts(c,data||[]));
  }catch(e){
    const msg=String(e.message||e).includes('dreampoen_dashboard_posts')?'게시판 DB 설치가 필요합니다. ZIP의 06_v1127_dashboard_board.sql을 Supabase SQL Editor에서 1회 실행해주세요.':'게시판을 불러오지 못했습니다.';
    ['dfHomeNotice','dfHomeMethod','dfHomeBoard'].forEach(id=>{const el=document.getElementById(id);if(el)el.innerHTML=`<div class="df-home-empty">${dfHomeEsc(msg)}</div>`});
  }
}
