// ============================================================
// v120.1 - 데이터 흐름 확정용 측정진행현황
// 핵심: 일정 상태는 측정실적으로 사용하지 않는다.
// ============================================================
(function(){
  let filter='all';
  function esc(v){return String(v??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]))}
  function datesFor(c,f,year){
    const out=[];
    if(Array.isArray(f?.ManualMeasurementDates)) f.ManualMeasurementDates.forEach(x=>{const d=companyIsoDate(x);if(d&&+d.slice(0,4)===year)out.push(d)});
    else {
      (f?.MeasurementHistory||[]).forEach(h=>{if(String(h?.Source||'').includes('일정'))return;const d=companyIsoDate(h?.Date);if(d&&+d.slice(0,4)===year)out.push(d)});
      (c?.MeasurementHistory||[]).forEach(h=>{if(String(h?.Source||'').includes('일정'))return;if(!dfV83FacilityMatchesHistory(f,h))return;const d=companyIsoDate(h?.Date);if(d&&+d.slice(0,4)===year)out.push(d)});
    }
    return [...new Set(out)].sort();
  }
  function evalCycle(cycle,dates,year){
    const months=dates.map(d=>+d.slice(5,7)), now=new Date(), cy=now.getFullYear(), cm=now.getMonth()+1;
    if(year>cy)return {done:false,label:'측정 필요',next:'향후 측정 대상'};
    if(/월\s*2회/.test(cycle)){const upto=year<cy?12:cm;for(let m=1;m<=upto;m++)if(dates.filter(d=>+d.slice(5,7)===m).length<2)return {done:false,label:'측정 필요',next:`${m}월 실적 확인`};return {done:true,label:'완료',next:'현재 기준 충족'}}
    if(/월|12회/.test(cycle)){const upto=year<cy?12:cm;for(let m=1;m<=upto;m++)if(!months.includes(m))return {done:false,label:'측정 필요',next:`${m}월 측정 필요`};return {done:true,label:'완료',next:'현재 기준 충족'}}
    if(/분기|4회/.test(cycle)){const upto=year<cy?4:Math.ceil(cm/3);for(let q=1;q<=upto;q++){const a=(q-1)*3+1,b=a+2;if(!months.some(m=>m>=a&&m<=b))return {done:false,label:'측정 필요',next:`${q}분기 측정 필요`}}return {done:true,label:'완료',next:'현재 기준 충족'}}
    if(/반기|연\s*2회|2회/.test(cycle)){const h1=months.some(m=>m<=6),h2=months.some(m=>m>=7);if(year<cy)return h1&&h2?{done:true,label:'완료',next:'연간 기준 충족'}:{done:false,label:'측정 필요',next:!h1?'상반기 실적 확인':'하반기 실적 확인'};if(cm<=6)return h1?{done:true,label:'완료',next:'하반기 측정 예정'}:{done:false,label:'측정 필요',next:'상반기 측정 필요'};return h1&&h2?{done:true,label:'완료',next:'연간 기준 충족'}:{done:false,label:'측정 필요',next:!h1?'상반기 실적 확인':'하반기 측정 필요'}}
    return dates.length?{done:true,label:'완료',next:'연 1회 기준 충족'}:{done:false,label:'측정 필요',next:'연 1회 측정 필요'};
  }
  window.dfV1201RenderProgress=function(){
    const body=document.getElementById('df1201Tbody');if(!body)return;
    const year=+(document.getElementById('df1201Year')?.value||companyState?.year||2026),q=String(document.getElementById('df1201Search')?.value||'').trim().toLowerCase();
    const companies=typeof dfV75SourceCompanies==='function'?dfV75SourceCompanies():[];
    const rows=[];let doneCompanies=0,needCompanies=0,facCount=0;
    companies.forEach(c=>{let companyDone=true;const fs=c.Facilities||[];facCount+=fs.length;if(!fs.length)companyDone=false;fs.forEach(f=>{const cycle=dfV86FacilityCycle(f),dates=datesFor(c,f,year),st=evalCycle(cycle,dates,year);if(!st.done)companyDone=false;rows.push({c,f,cycle,dates,st})});if(companyDone)doneCompanies++;else needCompanies++});
    document.getElementById('df1201All').textContent=companies.length;document.getElementById('df1201Need').textContent=needCompanies;document.getElementById('df1201Done').textContent=doneCompanies;document.getElementById('df1201Facilities').textContent=facCount;
    const shown=rows.filter(r=>{if(filter==='done'&&!r.st.done)return false;if(filter==='need'&&r.st.done)return false;if(q&&!`${r.c.Name||''} ${r.f.FacilityName||''} ${r.f.EmissionFacility||''}`.toLowerCase().includes(q))return false;return true});
    body.innerHTML=shown.map(r=>`<tr><td><strong>${esc(r.c.Name||'-')}</strong></td><td>${esc(r.f.FacilityName||r.f.EmissionFacility||'-')}</td><td>${esc(r.cycle)}</td><td class="df1201-dates">${r.dates.length?r.dates.map(d=>esc(d)).join('<br>'):'-'}</td><td><span class="df1201-status ${r.st.done?'done':'need'}">${esc(r.st.label)}</span></td><td class="df1201-action">${esc(r.st.next)}</td></tr>`).join('')||'<tr><td colspan="6" class="df1201-empty">표시할 측정진행 자료가 없습니다.</td></tr>';
  };
  document.addEventListener('DOMContentLoaded',()=>{
    document.querySelectorAll('[data-pfilter]').forEach(b=>b.addEventListener('click',()=>{filter=b.dataset.pfilter==='fac'?'all':b.dataset.pfilter;document.querySelectorAll('[data-pfilter]').forEach(x=>x.classList.toggle('active',x===b));dfV1201RenderProgress()}));
    document.getElementById('df1201Year')?.addEventListener('change',dfV1201RenderProgress);
    document.getElementById('df1201Search')?.addEventListener('input',dfV1201RenderProgress);
    document.getElementById('df1201ProgressRefresh')?.addEventListener('click',()=>{try{companyRender?.()}catch(_){}dfV1201RenderProgress()});
  });
})();

// v120.6.2: 업체현황 통합 이후 검색·관리연도·현황판을 유지한다. 일정 완료 저장 로직은 변경하지 않는다.

(function(){let pf='all';const norm=v=>String(v||'').toLowerCase().replace(/\s/g,'');function cycles(c){const s=new Set();(c.Facilities||[]).forEach(f=>[(f.Cycle||''),...(f.ItemCycles||[]).map(x=>x.Cycle||'')].forEach(x=>{if(/월|12회/.test(x))s.add('월');else if(/분기|4회/.test(x))s.add('분기');else if(/반기|연\s*2회|2회/.test(x))s.add('반기');else if(x)s.add('연')}));return s.size?s:new Set(['연'])}function dates(c,y){const a=[];(typeof scheduleItems==='function'?scheduleItems():[]).forEach(s=>{if(s.Deleted||!s.Completed||s.Type!=='측정출장')return;const d=companyIsoDate(s.Date);if(!d||+d.slice(0,4)!==y)return;const names=[s.Company,...(s.Companies||[])].filter(Boolean),ids=(s.CompanyIds||[]).map(String);if(names.some(n=>norm(n)===norm(c.Name))||ids.includes(String(c.Id)))a.push(d)});return [...new Set(a)].sort()}function n(k){return k==='월'?12:k==='분기'?4:k==='반기'?2:1}function cnt(k,ds){const m=ds.map(d=>+d.slice(5,7));return k==='월'?new Set(m).size:k==='분기'?new Set(m.map(x=>Math.ceil(x/3))).size:k==='반기'?new Set(m.map(x=>x<=6?1:2)).size:ds.length?1:0}window.dfV1201RenderProgress=function(){const b=document.getElementById('df1201Tbody');if(!b)return;const y=+(document.getElementById('df1201Year')?.value||2026),q=norm(document.getElementById('df1201Search')?.value),cs=typeof dfV75SourceCompanies==='function'?dfV75SourceCompanies():[];let done=0,need=0,rows=[];cs.forEach(c=>{const cy=cycles(c),ds=dates(c,y),ok=[...cy].every(k=>cnt(k,ds)>=n(k));ok?done++:need++;rows.push({c,cy,ds,ok})});document.getElementById('df1201All').textContent=cs.length;document.getElementById('df1201Need').textContent=need;document.getElementById('df1201Done').textContent=done;b.innerHTML=rows.filter(r=>(pf==='all'||pf==='done'&&r.ok||pf==='need'&&!r.ok)&&(!q||norm(r.c.Name).includes(q))).map(r=>{const td=k=>r.cy.has(k)?`<b>${cnt(k,r.ds)}/${n(k)}</b>`:'-';return `<tr class="v1202-progress-row" data-id="${r.c.Id}"><td><strong>${r.c.Name}</strong></td><td>${[...r.cy].join(' + ')}</td><td>${td('연')}</td><td>${td('반기')}</td><td>${td('분기')}</td><td>${td('월')}</td><td>${r.ds.at(-1)||'-'}</td><td>${r.ok?'-':'측정 필요'}</td><td><span class="df1201-status ${r.ok?'done':'need'}">${r.ok?'완료':'진행중'}</span></td></tr>`}).join('');b.querySelectorAll('.v1202-progress-row').forEach(tr=>tr.onclick=()=>{const c=cs.find(x=>String(x.Id)===tr.dataset.id),cy=cycles(c),ds=dates(c,y);document.getElementById('v1202ModalTitle').textContent=`${c.Name} · ${y} 측정 상세`;document.getElementById('v1202ModalBody').innerHTML=`<div class="v1202-cycle-line"><b>계약주기</b><span>${[...cy].join(' + ')}</span></div><div class="v1202-slot-grid">${[...cy].map(k=>`<div><span>${k}</span><strong>${cnt(k,ds)}/${n(k)}</strong></div>`).join('')}</div><label class="v1202-detail-label">완료 날짜<textarea rows="5">${ds.join('\\n')}</textarea><small>수정 저장은 데이터 원본 구조 확정 후 연결합니다.</small></label>`;document.getElementById('v1202ProgressModal').hidden=false})};document.addEventListener('DOMContentLoaded',()=>{document.querySelectorAll('[data-pfilter]').forEach(x=>x.onclick=()=>{pf=x.dataset.pfilter;document.querySelectorAll('[data-pfilter]').forEach(z=>z.classList.toggle('active',z===x));dfV1201RenderProgress()});['v1202ModalClose','v1202ModalClose2'].forEach(id=>document.getElementById(id)?.addEventListener('click',()=>document.getElementById('v1202ProgressModal').hidden=true));document.getElementById('v1202ModalSave')?.addEventListener('click',()=>alert('화면 구조 확인 버전입니다. 수정 저장은 다음 단계에서 연결합니다.'))})})();

// ==========================================================
// v120.3 CONTRACT CYCLE FOUNDATION
// 계약관리 = 시설별 측정주기의 기준DB.
// 기존 업체현황/시설/시료채취기록지 데이터는 읽기만 하며 절대 수정하지 않는다.
// ==========================================================
(function(){
  const FLAG='contract_cycle_initial_v1203';
  const REPAIR_FLAG='contract_cycle_unmatched_repair_v1204';
  const TABLE='dreampoen_contract_facility_cycles';
  const FLAG_TABLE='dreampoen_migration_flags';
  const esc=v=>typeof dfV68Esc==='function'?dfV68Esc(v):String(v??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));
  const norm=v=>String(v||'').toLowerCase().replace(/주식회사|\(주\)|㈜/g,'').replace(/[\s\-_/().,\[\]]+/g,'');

  function facilityKey(f){
    const id=String(f?.Id||'').trim();
    return id || `name:${norm(f?.FacilityName||f?.PreventionFacility||'facility')}`;
  }
  function contractCompany(r){
    const cs=typeof dfV75SourceCompanies==='function'?dfV75SourceCompanies():((typeof companyState!=='undefined'&&companyState?.db?.Companies)||[]);
    return cs.find(c=>typeof dfV73MatchCompanyToContract==='function'&&dfV73MatchCompanyToContract(c,r))
      || cs.find(c=>norm(c?.Name)===norm(r?.target_name||r?.requester_name));
  }
  function parseCycleLabel(label,out,unknown){
    const raw=String(label||'').trim(); if(!raw)return;
    const s=raw.replace(/\s+/g,'');
    if(/월2회|월2번|매월2회/.test(s)){out.monthly_2=true;return}
    if(/월1회|매월1회|매월/.test(s)){out.monthly_1=true;return}
    if(/분기|연4회|년4회/.test(s)){out.quarterly_1=true;return}
    if(/반기|연2회|년2회/.test(s)){out.halfyear_1=true;return}
    if(/연1회|년1회|1년1회/.test(s)){out.yearly_1=true;return}
    unknown.add(raw);
  }
  function inferFacilityCycles(f){
    const out={monthly_1:false,monthly_2:false,quarterly_1:false,halfyear_1:false,yearly_1:false,other_cycle:false,other_label:'',note:''};
    const unknown=new Set(), noteParts=[];
    const itemRows=Array.isArray(f?.ItemCycles)?f.ItemCycles.filter(x=>x&&String(x.Cycle||'').trim()):[];
    if(itemRows.length){
      itemRows.forEach(x=>{parseCycleLabel(x.Cycle,out,unknown); if(x.Item||x.Cycle)noteParts.push(`${String(x.Item||'항목').trim()} ${String(x.Cycle||'').trim()}`.trim())});
    }else if(f?.Cycle){parseCycleLabel(f.Cycle,out,unknown)}
    if(!itemRows.length && Array.isArray(f?.Items) && f.Items.length && f?.Cycle) noteParts.push(`${f.Items.join(', ')} ${f.Cycle}`);
    if(!out.monthly_1&&!out.monthly_2&&!out.quarterly_1&&!out.halfyear_1&&!out.yearly_1 && f?.Cycle)parseCycleLabel(f.Cycle,out,unknown);
    if(unknown.size){out.other_cycle=true;out.other_label=[...unknown].join(', ')}
    out.note=noteParts.join(' / ') || String(f?.Memo||'').trim();
    return out;
  }
  async function tableReady(){
    if(typeof dfSupabase==='undefined'||!dfSupabase){window.DF_DIAG?.warn('CONTRACT-CYCLE','Supabase 클라이언트 없음');return false}
    const {error}=await dfSupabase.from(TABLE).select('id').limit(1);
    if(error)window.DF_DIAG?.error('CONTRACT-CYCLE','측정주기 테이블 확인 실패',error);
    return !error;
  }
  async function flagStatus(){
    if(typeof dfSupabase==='undefined'||!dfSupabase)return null;
    const {data,error}=await dfSupabase.from(FLAG_TABLE).select('*').eq('flag_key',FLAG).maybeSingle();
    if(error)return null; return data||null;
  }
  async function refreshMigrationStatus(){
    const el=document.getElementById('v1203MigrationStatus'); if(!el)return;
    if(typeof dfSupabase==='undefined'||!dfSupabase){el.className='v1203-contract-cycle-status warn';el.textContent='온라인 DB가 연결되지 않았습니다.';return}
    if(!(await tableReady())){el.className='v1203-contract-cycle-status warn';el.innerHTML='<b>v120.3 SQL 설치 필요</b> · 11_v1203_contract_facility_cycles.sql을 Supabase SQL Editor에서 1회 실행하세요.';return}
    const f=await flagStatus();
    if(f?.completed){
      const d=f.details||{}; el.className='v1203-contract-cycle-status ok';
      el.textContent=`최초 이관 완료 · 계약 ${d.contracts??'-'}건 · 시설기준 ${d.rows??'-'}건 · 이후 계약관리 값만 기준으로 사용합니다.`;
      const b=document.getElementById('v1203MigrateCycles');if(b){b.disabled=true;b.textContent='기존 주기 이관 완료'}
      const repair=document.getElementById('v1204RepairUnmatched');
      if(repair){const rf=await (async()=>{const {data}=await dfSupabase.from(FLAG_TABLE).select('*').eq('flag_key',REPAIR_FLAG).maybeSingle();return data||null})();repair.hidden=!!rf?.completed;repair.disabled=false}
    }else{
      el.className='v1203-contract-cycle-status';
      el.textContent='최초 1회 이관 전 · 현재 업체현황의 시설별 측정주기를 계약관리 기준DB로 복사합니다. 업체현황 원본은 변경하지 않습니다.';
    }
  }
  async function repairKnownUnmatched(){
    const btn=document.getElementById('v1204RepairUnmatched'),status=document.getElementById('v1203MigrationStatus');
    if(btn){btn.disabled=true;btn.textContent='누락 업체 복구 중...'}
    window.DF_DIAG?.step('CONTRACT-CYCLE-REPAIR','[STEP 1] 누락 업체 2건 복구 시작');
    if(typeof dfV68IsAdmin!=='function'||!dfV68IsAdmin()){
      if(btn){btn.disabled=false;btn.textContent='누락 업체 2건 복구'}
      alert('누락 업체 복구는 관리자 계정에서만 가능합니다.');return;
    }
    try{
      if(!dfV68ContractState?.loaded)await dfV68LoadContracts?.(true);
      const contracts=dfV68ContractState?.rows||[];
      const oldName='동원카독크',newName='경기자동차공업사',civicName='시민대로현대서비스 주식회사';
      const oldNorm=norm(oldName),civicNorm=norm(civicName);
      const dongwon=contracts.find(r=>[r.target_name,r.requester_name].some(x=>norm(x)===oldNorm));
      const civic=contracts.find(r=>[r.target_name,r.requester_name].some(x=>norm(x)===civicNorm));
      if(!dongwon)throw new Error('계약 DB에서 동원카독크 계약을 찾지 못했습니다.');
      if(!civic)throw new Error('계약 DB에서 시민대로현대서비스 주식회사 계약을 찾지 못했습니다.');

      const rename={};
      if(norm(dongwon.target_name)===oldNorm){rename.target_name=newName;rename.target_biz_no='844-53-00842';rename.target_address='경기도 평택시 경기대로 731 (지제동)'}
      if(norm(dongwon.requester_name)===oldNorm){rename.requester_name=newName;rename.requester_biz_no='844-53-00842';rename.requester_address='경기도 평택시 경기대로 731 (지제동)'}
      const renamed=await dfSupabase.from('contracts').update(rename).eq('id',dongwon.id).select('*').single();
      if(renamed.error)throw renamed.error;
      Object.assign(dongwon,renamed.data||rename);
      window.DF_DIAG?.step('CONTRACT-CYCLE-REPAIR','[STEP 2] 동원카독크 계약명 변경 완료',`${oldName} → ${newName}`);

      try{await dfV68PullCompanies?.()}catch(e){window.DF_DIAG?.warn('CONTRACT-CYCLE-REPAIR','업체목록 새로고침 일부 실패',e?.message||e)}
      const companyRows=await dfV68FetchAll('companies','id,legacy_id,name,biz_no,address');
      const gyeonggi=companyRows.find(x=>String(x.biz_no||'').replace(/\D/g,'')==='8445300842')
        || companyRows.find(x=>norm(x.name)===norm(newName)&&String(x.address||'').replace(/\s/g,'').includes('평택시경기대로731'));
      if(!gyeonggi)throw new Error('업체현황에서 평택 경기자동차공업사(844-53-00842)를 찾지 못했습니다.');
      const localCompanies=companyState?.db?.Companies||[];
      const gyeonggiLocal=localCompanies.find(x=>String(x.BizNo||'').replace(/\D/g,'')==='8445300842')
        || localCompanies.find(x=>norm(x.Name)===norm(newName)&&String(x.Address||'').replace(/\s/g,'').includes('평택시경기대로731'));
      if(!gyeonggiLocal)throw new Error('평택 경기자동차공업사의 시설정보를 불러오지 못했습니다.');
      const cycleRows=(gyeonggiLocal.Facilities||[]).map(fac=>({contract_id:dongwon.id,company_legacy_id:String(gyeonggiLocal.Id||gyeonggi.legacy_id||''),company_name:newName,facility_key:facilityKey(fac),facility_legacy_id:String(fac.Id||''),facility_name:fac.FacilityName||fac.PreventionFacility||'시설',...inferFacilityCycles(fac),migration_source:'unmatched_repair_v1204'}));
      if(cycleRows.length){const q=await dfSupabase.from(TABLE).upsert(cycleRows,{onConflict:'contract_id,facility_key',ignoreDuplicates:true});if(q.error)throw q.error}
      window.DF_DIAG?.step('CONTRACT-CYCLE-REPAIR','[STEP 3] 경기자동차공업사 시설주기 연결 완료',`시설 ${cycleRows.length}건`);

      const civicPayload={...civic,target_name:civicName,target_biz_no:civic.target_biz_no||civic.requester_biz_no||'138-81-03918',target_address:civic.target_address||civic.requester_address||'경기도 안양시 동안구 벌말로 91'};
      const civicCompanyId=await dfV94EnsureContractCompany(civicPayload);
      if(!civicCompanyId)throw new Error('시민대로현대서비스 업체현황 생성에 실패했습니다.');
      window.DF_DIAG?.step('CONTRACT-CYCLE-REPAIR','[STEP 4] 시민대로현대서비스 신규 업체 생성 완료',`company id: ${civicCompanyId}`);

      const details={renamed_contract_id:dongwon.id,renamed_to:newName,linked_facilities:cycleRows.length,created_company:civicName,created_company_id:civicCompanyId,completed_at:new Date().toISOString()};
      const flag=await dfSupabase.from(FLAG_TABLE).upsert({flag_key:REPAIR_FLAG,completed:true,completed_at:new Date().toISOString(),details,updated_at:new Date().toISOString()},{onConflict:'flag_key'});
      if(flag.error)throw flag.error;
      await dfV68PullCompanies?.();dfV68ContractState.loaded=false;await dfV68LoadContracts?.(true);
      if(status){status.className='v1203-contract-cycle-status ok';status.textContent=`누락 업체 복구 완료 · 경기자동차공업사 시설 ${cycleRows.length}건 연결 · 시민대로현대서비스 신규 생성`}
      if(btn)btn.hidden=true;
      window.DF_DIAG?.info('CONTRACT-CYCLE-REPAIR','누락 업체 2건 복구 성공',details);
      alert(`누락 업체 2건 복구가 완료되었습니다.\n\n• 동원카독크 → 경기자동차공업사 명칭 변경\n• 경기자동차공업사 시설주기 ${cycleRows.length}건 연결\n• 시민대로현대서비스 주식회사 신규 업체 생성\n\n시민대로현대서비스 시설정보는 측정하면서 업체현황에 추가하면 됩니다.`);
    }catch(e){
      console.error('[CONTRACT-CYCLE-REPAIR-1204-01]',e);window.DF_DIAG?.error('CONTRACT-CYCLE-REPAIR','[CONTRACT-CYCLE-REPAIR-1204-01] 누락 업체 복구 실패',e?.stack||e?.message||e);
      if(status){status.className='v1203-contract-cycle-status warn';status.textContent='누락 업체 복구 중 오류가 발생했습니다. 오류진단 로그를 복사해주세요.'}
      if(btn){btn.disabled=false;btn.textContent='누락 업체 2건 복구'}window.DF_DIAG?.open();
    }
  }
  async function migrateInitial(){
    const btn=document.getElementById('v1203MigrateCycles'),status=document.getElementById('v1203MigrationStatus');
    if(btn){btn.disabled=true;btn.textContent='이관 준비 중...'}
    if(status){status.className='v1203-contract-cycle-status';status.textContent='이관 준비 중 · 관리자 권한과 온라인 DB를 확인하고 있습니다.'}
    window.DF_DIAG?.step('CONTRACT-CYCLE-MIGRATE','[STEP 1] 이관 버튼 클릭 확인');
    if(typeof dfV68IsAdmin!=='function'||!dfV68IsAdmin()){
      window.DF_DIAG?.warn('CONTRACT-CYCLE-MIGRATE','관리자 권한 확인 실패',`profile role: ${String(dfCloudProfile?.role||'(없음)')}`);
      if(btn){btn.disabled=false;btn.textContent='기존 측정주기 1회 이관'}
      if(status){status.className='v1203-contract-cycle-status warn';status.textContent='이관은 관리자 계정에서만 가능합니다. 현재 로그인 계정의 권한을 확인해주세요.'}
      alert('기존 측정주기 이관은 관리자 계정에서만 가능합니다.\n\n오류진단 버튼을 눌러 로그를 복사해 보내주시면 권한 상태도 확인할 수 있습니다.');return;
    }
    window.DF_DIAG?.step('CONTRACT-CYCLE-MIGRATE','[STEP 2] 관리자 권한 확인 완료');
    if(!(await tableReady())){
      window.DF_DIAG?.error('CONTRACT-CYCLE-MIGRATE','[STEP 3] SQL 테이블 확인 실패','11_v1203_contract_facility_cycles.sql 실행 여부를 확인하세요.');
      if(btn){btn.disabled=false;btn.textContent='기존 측정주기 1회 이관'}
      if(status){status.className='v1203-contract-cycle-status warn';status.textContent='측정주기 DB를 찾지 못했습니다. 오류진단 로그를 확인해주세요.'}
      alert('먼저 11_v1203_contract_facility_cycles.sql을 Supabase SQL Editor에서 실행해주세요.\n\n이미 실행했다면 오류진단 로그를 복사해 보내주세요.');return;
    }
    window.DF_DIAG?.step('CONTRACT-CYCLE-MIGRATE','[STEP 3] SQL 테이블 확인 완료');
    const f=await flagStatus();
    if(f?.completed){if(btn){btn.disabled=true;btn.textContent='기존 주기 이관 완료'}await refreshMigrationStatus();window.DF_DIAG?.info('CONTRACT-CYCLE-MIGRATE','최초 이관이 이미 완료된 상태');alert('최초 측정주기 이관은 이미 완료되었습니다.\n기존 데이터를 다시 덮어쓰지 않습니다.');return}
    if(!confirm('현재 업체현황에 있는 시설별 측정주기를 계약관리 기준DB로 최초 1회 복사합니다.\n\n• 업체현황/시설 원본은 수정하지 않습니다.\n• 시료채취기록지 연결도 변경하지 않습니다.\n• 기존 계약주기 행이 있으면 덮어쓰지 않습니다.\n\n진행할까요?')){if(btn){btn.disabled=false;btn.textContent='기존 측정주기 1회 이관'}if(status)status.textContent='사용자가 이관을 취소했습니다.';window.DF_DIAG?.info('CONTRACT-CYCLE-MIGRATE','사용자가 확인창에서 이관 취소');return}
    try{
      if(btn)btn.textContent='이관 중...';if(status)status.textContent='계약 및 업체 시설정보를 불러오는 중입니다.';
      window.DF_DIAG?.step('CONTRACT-CYCLE-MIGRATE','[STEP 4] 계약 데이터 조회 시작');
      if(!dfV68ContractState?.loaded)await dfV68LoadContracts?.(true);
      try{await dfV68PullCompanies?.()}catch(e){window.DF_DIAG?.warn('CONTRACT-CYCLE-MIGRATE','업체정보 온라인 새로고침 실패 · 현재 데이터로 계속',e?.message||e)}
      const contracts=(dfV68ContractState?.rows||[]).filter(r=>typeof dfV73ContractIsCurrent==='function'?dfV73ContractIsCurrent(r):true);
      window.DF_DIAG?.step('CONTRACT-CYCLE-MIGRATE','[STEP 5] 계약 데이터 조회 완료',`현재 계약 ${contracts.length}건`);
      let rows=[],matched=0,unmatched=[];
      for(const r of contracts){
        const c=contractCompany(r); if(!c){unmatched.push(r.target_name||r.requester_name||r.contract_no);continue}
        matched++;
        for(const fac of (c.Facilities||[])){
          const inf=inferFacilityCycles(fac);
          rows.push({contract_id:r.id,company_legacy_id:String(c.Id||''),company_name:c.Name||r.target_name||r.requester_name||'',facility_key:facilityKey(fac),facility_legacy_id:String(fac.Id||''),facility_name:fac.FacilityName||fac.PreventionFacility||'시설',...inf,migration_source:'company_cycle_initial_v1203'});
        }
      }
      window.DF_DIAG?.step('CONTRACT-CYCLE-MIGRATE','[STEP 6] 시설별 측정주기 변환 완료',`계약 연결 ${matched}건 / 시설 ${rows.length}건 / 미연결 ${unmatched.length}건`);
      let inserted=0;
      for(let i=0;i<rows.length;i+=100){
        const batch=rows.slice(i,i+100);
        if(status)status.textContent=`측정주기 저장 중 · ${Math.min(i+batch.length,rows.length)} / ${rows.length}건`;
        const {data,error}=await dfSupabase.from(TABLE).upsert(batch,{onConflict:'contract_id,facility_key',ignoreDuplicates:true}).select('id');
        if(error)throw error; inserted+=(data||[]).length;
      }
      window.DF_DIAG?.step('CONTRACT-CYCLE-MIGRATE','[STEP 7] 시설별 측정주기 저장 완료',`신규 저장 ${inserted}건`);
      const details={contracts:matched,rows:rows.length,inserted,unmatched:unmatched.length,unmatched_names:unmatched.slice(0,30),completed_at:new Date().toISOString()};
      const {error:fe}=await dfSupabase.from(FLAG_TABLE).upsert({flag_key:FLAG,completed:true,completed_at:new Date().toISOString(),details,updated_at:new Date().toISOString()},{onConflict:'flag_key'});
      if(fe)throw fe;
      window.DF_DIAG?.step('CONTRACT-CYCLE-MIGRATE','[STEP 8] 최초 이관 완료 플래그 저장');
      await refreshMigrationStatus();
      window.DF_DIAG?.info('CONTRACT-CYCLE-MIGRATE','측정주기 최초 이관 성공',details);
      alert(`최초 측정주기 이관이 완료되었습니다.\n\n계약 연결: ${matched}건\n시설 기준: ${rows.length}건\n계약 미연결: ${unmatched.length}건\n\n기존 업체현황 및 시료채취기록지 데이터는 변경하지 않았습니다.`);
    }catch(e){
      console.error('[CONTRACT-CYCLE-MIGRATE-1203-01]',e);
      window.DF_DIAG?.error('CONTRACT-CYCLE-MIGRATE','[CONTRACT-CYCLE-MIGRATE-1203-01] 측정주기 이관 실패',e?.stack||e?.message||e);
      alert('측정주기 이관 중 오류가 발생했습니다.\n[CONTRACT-CYCLE-MIGRATE-1203-01]\n'+(e.message||e));
      const btn=document.getElementById('v1203MigrateCycles');if(btn){btn.disabled=false;btn.textContent='기존 측정주기 1회 이관'}
      if(status){status.className='v1203-contract-cycle-status warn';status.textContent='이관 중 오류가 발생했습니다. 오른쪽 아래 오류진단에서 로그를 복사해주세요.'}
      window.DF_DIAG?.open();
    }
  }
  function cycleRowHtml(f,s={}){
    const ck=(k)=>s[k]?'checked':'';
    return `<div class="v1203-cycle-row" data-fkey="${esc(facilityKey(f))}" data-fid="${esc(f?.Id||'')}" data-fname="${esc(f?.FacilityName||f?.PreventionFacility||'시설')}">
      <div class="v1203-cycle-cell v1203-cycle-fac"><strong title="${esc(f?.FacilityName||f?.PreventionFacility||'시설')}">${esc(f?.FacilityName||f?.PreventionFacility||'시설')}</strong><small>${esc(f?.EmissionFacility||'')}</small></div>
      <div class="v1203-cycle-cell v1203-cycle-check"><input type="checkbox" data-cycle="monthly_1" ${ck('monthly_1')} title="월 1회"></div>
      <div class="v1203-cycle-cell v1203-cycle-check"><input type="checkbox" data-cycle="monthly_2" ${ck('monthly_2')} title="월 2회"></div>
      <div class="v1203-cycle-cell v1203-cycle-check"><input type="checkbox" data-cycle="quarterly_1" ${ck('quarterly_1')} title="분기 1회"></div>
      <div class="v1203-cycle-cell v1203-cycle-check"><input type="checkbox" data-cycle="halfyear_1" ${ck('halfyear_1')} title="반기 1회"></div>
      <div class="v1203-cycle-cell v1203-cycle-check"><input type="checkbox" data-cycle="yearly_1" ${ck('yearly_1')} title="연 1회"></div>
      <div class="v1203-cycle-cell v1203-cycle-check"><input type="checkbox" data-cycle="other_cycle" ${ck('other_cycle')} title="기타"></div>
      <div class="v1203-cycle-cell v1203-cycle-note"><input data-cycle-note value="${esc(s.note||'')}" placeholder="예: 염화수소 월2회 / 먼지 연1회 / 황산화물 분기1회"></div>
    </div>`;
  }
  async function mountContractCycles(r){
    const body=document.getElementById('contractModalBody'); if(!body)return;
    const sec=document.createElement('div');sec.className='v1203-cycle-section';sec.id='v1203ContractCycleSection';
    if(!r?.id){sec.innerHTML='<div class="v1203-cycle-section-head"><div><h3>시설별 측정주기 기준</h3><p>신규 계약을 먼저 저장한 뒤 기존 시설을 연결하고 측정주기를 설정합니다.</p></div></div><div class="v1203-cycle-empty">계약 저장 후 설정할 수 있습니다.</div>';body.insertBefore(sec,body.querySelector('.contract-editor-actions'));return}
    sec.innerHTML='<div class="v1203-cycle-section-head"><div><h3>시설별 측정주기 기준</h3><p>시설정보는 업체현황 DB를 읽기만 합니다. 여기서는 계약상 측정주기와 참고사항만 저장합니다.</p></div><span class="v1203-cycle-badge">불러오는 중</span></div><div class="v1203-cycle-empty">시설과 계약주기를 확인하는 중입니다.</div>';
    body.insertBefore(sec,body.querySelector('.contract-editor-actions'));
    if(!(await tableReady())){sec.querySelector('.v1203-cycle-empty').innerHTML='<b>SQL 설치 필요</b><br>11_v1203_contract_facility_cycles.sql을 먼저 실행하세요.';return}
    const c=contractCompany(r);
    if(!c){sec.querySelector('.v1203-cycle-badge').textContent='업체 연결 필요';sec.querySelector('.v1203-cycle-empty').textContent='계약의 측정대상 사업장과 업체현황 DB를 연결하지 못했습니다. 업체명/사업자번호를 확인해주세요.';return}
    const fs=c.Facilities||[];
    const {data,error}=await dfSupabase.from(TABLE).select('*').eq('contract_id',r.id);
    if(error){sec.querySelector('.v1203-cycle-empty').textContent='측정주기 DB 조회 실패: '+error.message;return}
    const map=new Map((data||[]).map(x=>[x.facility_key,x]));
    sec.querySelector('.v1203-cycle-badge').textContent=`시설 ${fs.length}개 · 설정 ${map.size}개`;
    if(!fs.length){sec.querySelector('.v1203-cycle-empty').innerHTML='등록된 시설이 없습니다.<br><small>신규 계약은 첫 측정 시 업체현황/시료채취기록지에서 시설정보를 등록한 뒤 여기에서 측정주기를 설정합니다.</small>';return}
    sec.innerHTML=`<div class="v1203-cycle-section-head"><div><h3>시설별 측정주기 기준</h3><p><b>${esc(c.Name)}</b>의 기존 시설을 그대로 참조합니다. 내경·가로·세로·시설명은 여기서 수정하지 않습니다.</p></div><span class="v1203-cycle-badge">시설 ${fs.length}개 · 설정 ${map.size}개</span></div>
      <div class="v1203-cycle-list"><div class="v1203-cycle-row header"><div class="v1203-cycle-cell">시설</div><div class="v1203-cycle-cell">월1</div><div class="v1203-cycle-cell">월2</div><div class="v1203-cycle-cell">분기</div><div class="v1203-cycle-cell">반기</div><div class="v1203-cycle-cell">연1</div><div class="v1203-cycle-cell">기타</div><div class="v1203-cycle-cell">비고 / 참고사항</div></div>${fs.map(f=>cycleRowHtml(f,map.get(facilityKey(f))||{})).join('')}</div>
      <div class="v1203-cycle-actions"><small>체크값은 향후 일정관리·측정진행현황의 기준이 됩니다. 업체현황 시설 원본에는 쓰지 않습니다.</small><button type="button" class="company-btn primary" id="v1203CycleSave">측정주기 저장</button></div>`;
    document.getElementById('v1203CycleSave')?.addEventListener('click',()=>saveContractCycles(r,c));
  }
  async function saveContractCycles(r,c){
    if(!dfV68IsAdmin?.()||!r?.id)return;
    const btn=document.getElementById('v1203CycleSave');if(btn){btn.disabled=true;btn.textContent='저장 중...'}
    try{
      const rows=[...document.querySelectorAll('#v1203ContractCycleSection .v1203-cycle-row[data-fkey]')].map(el=>{
        const get=k=>!!el.querySelector(`[data-cycle="${k}"]`)?.checked;
        return {contract_id:r.id,company_legacy_id:String(c.Id||''),company_name:c.Name||'',facility_key:el.dataset.fkey,facility_legacy_id:el.dataset.fid||null,facility_name:el.dataset.fname||'',monthly_1:get('monthly_1'),monthly_2:get('monthly_2'),quarterly_1:get('quarterly_1'),halfyear_1:get('halfyear_1'),yearly_1:get('yearly_1'),other_cycle:get('other_cycle'),other_label:'',note:el.querySelector('[data-cycle-note]')?.value.trim()||'',migration_source:'contract_manual_v1203',updated_at:new Date().toISOString()};
      });
      const {error}=await dfSupabase.from(TABLE).upsert(rows,{onConflict:'contract_id,facility_key'});if(error)throw error;
      await window.dfV1205LoadCompanyCycles?.();
      alert('시설별 측정주기를 계약관리 기준DB에 저장했습니다.\n업체현황 및 시료채취기록지 시설정보는 변경하지 않았습니다.');
      await mountReload(r);
    }catch(e){console.error('[CONTRACT-CYCLE-SAVE-1203-01]',e);alert('측정주기 저장 실패\n[CONTRACT-CYCLE-SAVE-1203-01]\n'+(e.message||e))}
    finally{if(btn){btn.disabled=false;btn.textContent='측정주기 저장'}}
  }
  async function mountReload(r){
    document.getElementById('v1203ContractCycleSection')?.remove();await mountContractCycles(r);
  }

  // 기존 계약수정 UI는 보존하고 측정주기 섹션만 뒤에 붙인다.
  const oldOpen=window.dfV70OpenContractEditor || (typeof dfV70OpenContractEditor==='function'?dfV70OpenContractEditor:null);
  if(oldOpen){
    window.dfV70OpenContractEditor=function(r=null){oldOpen(r);setTimeout(()=>mountContractCycles(r),0)};
    try{dfV70OpenContractEditor=window.dfV70OpenContractEditor}catch(_){ }
  }

  window.dfV12031MigrateCycles=migrateInitial;
  document.addEventListener('DOMContentLoaded',()=>{
    const migrateBtn=document.getElementById('v1203MigrateCycles');
    if(migrateBtn&&!migrateBtn.dataset.v12031Bound){migrateBtn.dataset.v12031Bound='1';migrateBtn.addEventListener('click',migrateInitial)}
    document.getElementById('v1204RepairUnmatched')?.addEventListener('click',repairKnownUnmatched);
    setTimeout(refreshMigrationStatus,1200);
  });
  window.dfV1203RefreshMigrationStatus=refreshMigrationStatus;
})();

// ==========================================================
// v120.6.3.2 FRESH MEASUREMENT SOURCE SYNC
// 사용자 제공 2026 상·하반기 Excel 원본을 별도 데이터 파일로 분리하여 로드한다.
// 이 단계에서는 기존 MeasurementHistory나 일정관리와 합치지 않는다.
// 다음 단계의 점수매칭이 완료되기 전까지 업체별 진행판정에는 사용하지 않는다.
// ==========================================================
(function dfV120632MeasurementSourceSync(){
  function validate(){
    const src=window.DF_MEASUREMENT_DATES_2026;
    if(!src||!Array.isArray(src.groups)){
      window.DF_DIAG?.error('MEASUREMENT-SOURCE-SYNC','신규 측정일 원본 파일을 불러오지 못했습니다.','measurement_dates_2026_fresh.js 확인 필요');
      return false;
    }
    const ok=+src.recordCount===918 && +src.upperHalfCount===732 && +src.lowerHalfCount===186 && +src.duplicateMeasurementCount===0;
    const detail=`상반기 ${src.upperHalfCount}건 / 하반기 ${src.lowerHalfCount}건 / 총 ${src.recordCount}건 / 사업장그룹 ${src.siteGroupCount}개 / 측정번호중복 ${src.duplicateMeasurementCount}건`;
    if(ok) window.DF_DIAG?.info('MEASUREMENT-SOURCE-SYNC','상·하반기 신규 측정일 원본 동기화 완료',detail);
    else window.DF_DIAG?.warn('MEASUREMENT-SOURCE-SYNC','신규 측정일 원본 건수 확인 필요',detail);
    const national=src.groups.find(x=>String(x.name||'').includes('내쇼날모터스'));
    if(national) window.DF_DIAG?.info('MEASUREMENT-SOURCE-CHECK','내쇼날모터스 신규 원본 확인',`${national.dates.join(', ')} / ${national.records}건 / ${national.halves.join(', ')}`);
    return ok;
  }
  window.dfV120632MeasurementSource=()=>window.DF_MEASUREMENT_DATES_2026||null;
  window.dfV120632ValidateMeasurementSource=validate;
  document.addEventListener('DOMContentLoaded',()=>setTimeout(validate,500),{once:true});
})();

// ==========================================================
// v120.5 CONTRACT CYCLE -> COMPANY STATUS (READ-THROUGH)
// 업체/시설 원본은 유지하고 계약관리 측정주기를 화면과 완료판정에 우선 적용한다.
// ==========================================================
(function dfV1205CompanyCycleBridge(){
  const TABLE='dreampoen_contract_facility_cycles';
  let cycleByFacility=new Map();
  const labels=[['monthly_2','월 2회'],['monthly_1','월 1회'],['quarterly_1','분기 1회'],['halfyear_1','반기 1회'],['yearly_1','연 1회']];
  const key=v=>String(v||'').trim();
  function rowLabels(row){
    const out=labels.filter(([k])=>row?.[k]).map(([,v])=>v);
    if(row?.other_cycle)out.push(String(row.other_label||'기타').trim()||'기타');
    return [...new Set(out)];
  }
  function facilityKey(f){const id=key(f?.Id);return id||`name:${String(f?.FacilityName||f?.PreventionFacility||'facility').toLowerCase().replace(/주식회사|\(주\)|㈜/g,'').replace(/[\s\-_/().,\[\]]+/g,'')}`}
  function cycleIn(text){
    const s=String(text||'');
    const m=s.match(/월\s*2회|매월\s*2회|월\s*1회|매월\s*1회|분기\s*1회|연\s*4회|년\s*4회|반기\s*1회|연\s*2회|년\s*2회|연\s*1회|년\s*1회|1년\s*1회/i);
    if(!m)return '';
    const x=m[0].replace(/\s+/g,'');
    if(/월2회|매월2회/.test(x))return '월 2회';if(/월1회|매월1회/.test(x))return '월 1회';if(/분기|4회/.test(x))return '분기 1회';if(/반기|2회/.test(x))return '반기 1회';return '연 1회';
  }
  function rowFor(f){return f?._ContractCycleRow||cycleByFacility.get(key(f?.Id))||null}
  window.dfV1205HasContractCycle=f=>!!rowFor(f);
  window.dfV1205EffectiveCycle=function(f){const row=rowFor(f);if(!row)return '';const list=rowLabels(row);return list.length===1?list[0]:list.length?list.join(' + '):''};
  window.dfV1205EffectiveItemCycles=function(f){
    const row=rowFor(f);if(!row)return null;
    const base=(f.ItemCycles||[]).length?f.ItemCycles:(f.Items||[]).map(Item=>({Item,Cycle:f.Cycle||'반기 1회'}));
    const parts=String(row.note||'').split(/\s*\/\s*|\n+/).map(x=>x.trim()).filter(Boolean),single=rowLabels(row);
    if(!base.length)return [];
    return base.map(x=>{
      const item=String(x.Item||'').trim(),part=parts.find(p=>item&&p.toLowerCase().includes(item.toLowerCase())),parsed=cycleIn(part||'');
      return {...x,Cycle:parsed||(single.length===1?single[0]:x.Cycle||f.Cycle||'반기 1회'),ContractSource:true};
    });
  };
  window.dfV1205CompanyCycle=function(c){const values=[...new Set((c?.Facilities||[]).map(f=>window.dfV1205EffectiveCycle(f)).filter(Boolean))];return values.length===1?values[0]:values.length?'복합주기':''};

  async function load(){
    if(typeof dfSupabase==='undefined'||!dfSupabase||typeof dfV68FetchAll!=='function')return 0;
    try{
      const rows=await dfV68FetchAll(TABLE,'*','updated_at'),byExact=new Map(),byFallback=new Map();cycleByFacility=new Map();
      rows.forEach(r=>{const k1=`${key(r.company_legacy_id)}::${key(r.facility_legacy_id)}`,k2=`${key(r.company_legacy_id)}::${key(r.facility_key)}`;if(r.company_legacy_id&&r.facility_legacy_id){byExact.set(k1,r);cycleByFacility.set(key(r.facility_legacy_id),r)}if(r.company_legacy_id&&r.facility_key)byFallback.set(k2,r)});
      let applied=0,companies=0;
      (companyState?.db?.Companies||[]).forEach(c=>{let hit=false;(c.Facilities||[]).forEach(f=>{const row=byExact.get(`${key(c.Id)}::${key(f.Id)}`)||byFallback.get(`${key(c.Id)}::${facilityKey(f)}`);try{delete f._ContractCycleRow}catch(_){}if(row){Object.defineProperty(f,'_ContractCycleRow',{value:row,writable:true,configurable:true,enumerable:false});applied++;hit=true}});if(hit)companies++});
      let badge=document.getElementById('v1205CompanyCycleState');
      const host=document.querySelector('.company-toolbar,.company-page-head,.company-head');
      if(!badge&&host){badge=document.createElement('div');badge.id='v1205CompanyCycleState';badge.className='v1203-contract-cycle-status ok';host.insertAdjacentElement('afterend',badge)}
      if(badge)badge.textContent=`계약관리 측정주기 적용 중 · 업체 ${companies}개 · 시설 ${applied}개`;
      window.DF_DIAG?.info('COMPANY-CYCLE-BRIDGE','계약관리 측정주기 업체현황 반영 완료',`업체 ${companies}개 / 시설 ${applied}개`);
      try{companyRender?.()}catch(e){window.DF_DIAG?.warn('COMPANY-CYCLE-BRIDGE','업체현황 재표시 실패',e?.message||e)}
      return applied;
    }catch(e){window.DF_DIAG?.error('COMPANY-CYCLE-BRIDGE','계약관리 측정주기 불러오기 실패',e?.stack||e?.message||e);return 0}
  }
  const pullBase=typeof dfV68PullCompanies==='function'?dfV68PullCompanies:null;
  if(pullBase)dfV68PullCompanies=async function(){const result=await pullBase.apply(this,arguments);await load();return result};
  window.dfV1205LoadCompanyCycles=load;
  document.addEventListener('DOMContentLoaded',()=>setTimeout(load,2200));
})();
